window.PLAZA_EVENTS = [{"id":"1980-guadalajara-cartel-consolidation","date":"1980-01-01","precision":"year","title":"Guadalajara Cartel forms under Félix Gallardo, Caro Quintero, Fonseca","summary":"After the Army's Operation Condor (launched 1977) razed the Sinaloa highlands and pioneer boss Pedro Avilés Pérez was killed in a shootout with federal police near Culiacán on 15 September 1978, the surviving Sinaloan traffickers regrouped in Guadalajara. By around 1980 Miguel Ángel Félix Gallardo, Rafael Caro Quintero and Ernesto 'Don Neto' Fonseca Carrillo ran a single federation from the city, growing marijuana and opium in the Sierra and shipping to the United States under the protection of the Dirección Federal de Seguridad (DFS) and the federal judicial police.","impact":"Created Mexico's first nationwide trafficking federation; every major cartel of the following decades (Sinaloa, Tijuana, Juárez, Sonora) descends from this organization and its Sinaloan founders.","state":"JAL","city":"Guadalajara","lat":20.6597,"lng":-103.3496,"cartels":["guadalajara","sinaloa","government"],"figures":["Miguel Ángel Félix Gallardo","Rafael Caro Quintero","Ernesto 'Don Neto' Fonseca Carrillo","Pedro Avilés Pérez"],"type":"formation","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Guadalajara_Cartel","https://kellogg.nd.edu/operation-condor-war-drugs-and-counterinsurgency-golden-triangle-1977-1983","https://en.wikipedia.org/wiki/Pedro_Avil%C3%A9s_P%C3%A9rez"]},{"id":"1982-matta-ballesteros-medellin-cocaine-link","date":"1982-01-01","precision":"year","title":"Matta-Ballesteros links Guadalajara Cartel to Medellín cocaine","summary":"Honduran trafficker Juan Ramón Matta Ballesteros, an associate of Félix Gallardo since the 1970s, brokered the arrangement under which Medellín Cartel cocaine was flown through Central America and Mexico and moved across the US border by the Guadalajara federation. The pipeline expanded sharply in the early 1980s as US interdiction in South Florida and the Caribbean pushed Colombian suppliers to Mexican routes; the start date is approximate.","impact":"Turned the Mexican marijuana and heroin smugglers into the Colombians' primary transport partners, the single most important structural shift in Mexican organized crime; cocaine money financed the bribery networks exposed in the Camarena case.","state":"JAL","city":"Guadalajara","lat":20.6597,"lng":-103.3496,"cartels":["guadalajara","other"],"figures":["Juan Ramón Matta Ballesteros","Miguel Ángel Félix Gallardo"],"type":"alliance","importance":4,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Juan_Matta-Ballesteros","https://insightcrime.org/honduras-organized-crime-news/juan-matta-ballesteros/","https://en.wikipedia.org/wiki/Guadalajara_Cartel"]},{"id":"1984-manuel-buendia-murder","date":"1984-05-30","precision":"day","title":"Columnist Manuel Buendía shot dead in Mexico City by DFS agent","summary":"Manuel Buendía, Mexico's most-read political columnist, was shot four times in the back as he left his office near the Insurgentes-Reforma intersection on the edge of Mexico City's Zona Rosa on 30 May 1984. DFS agent Juan Rafael Moro Ávila was later convicted as the material author, acting on orders of DFS director José Antonio Zorrilla Pérez, whose links to drug traffickers Buendía had been investigating. Zorrilla's agents took over the crime scene and removed Buendía's files and the shell casings; Zorrilla was arrested in 1989 and sentenced to 35 years in February 1993 as the intellectual author.","impact":"Exposed the DFS as an armed protector of the Guadalajara traffickers and became the emblematic case of state-narco collusion of the 1980s, contributing to the agency's dissolution in 1985.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["government","guadalajara"],"figures":["Manuel Buendía","José Antonio Zorrilla Pérez","Juan Rafael Moro Ávila"],"type":"killing","importance":4,"confidence":"high","sources":["https://www.proceso.com.mx/nacional/2023/9/20/zorrilla-el-autor-intelectual-del-homicidio-de-buendia-que-nunca-fue-esposado-315197.html","https://es.wikipedia.org/wiki/Manuel_Buend%C3%ADa","https://memoricamexico.gob.mx/es/memorica/Asesinato_del_periodista_Manuel_Buendia_atribuido"]},{"id":"1984-rancho-bufalo-raid","date":"1984-11-06","precision":"day","title":"Army raids Rancho Búfalo, Caro Quintero's giant marijuana plantation","summary":"On 6 November 1984 more than 400 Mexican soldiers, acting on intelligence developed by DEA agent Enrique Camarena and pilot Alfredo Zavala, descended by helicopter on the Búfalo ranch complex at Colonia Búfalo, Allende municipality, Chihuahua. They found an industrial marijuana operation with thousands of laborers, irrigation systems and processing sheds; estimates of the crop destroyed range from roughly 2,500 to 10,000 tons, then the largest marijuana seizure ever recorded.","impact":"Cost Caro Quintero and his partners billions in lost product and set in motion the cartel's decision to hunt down the DEA source, leading directly to Camarena's abduction three months later.","state":"CHH","city":"Colonia Búfalo, Allende","lat":27.2994,"lng":-105.1736,"cartels":["guadalajara","government","us_government"],"figures":["Rafael Caro Quintero","Enrique 'Kiki' Camarena","Alfredo Zavala Avelar"],"type":"discovery","importance":4,"confidence":"high","sources":["https://es.wikipedia.org/wiki/Colonia_B%C3%BAfalo","https://www.infobae.com/mexico/2023/10/31/asi-era-el-bufalo-el-rancho-de-caro-quintero-donde-mas-de-10-mil-jornaleros-trabajaban-y-vivian-clandestinamente/","https://www.cronicadechihuahua.com/Hace-29-anos-el-mas-espectacular.html"]},{"id":"1985-amado-carrillo-ojinaga-apprenticeship","date":"1985-01-01","precision":"year","title":"Amado Carrillo Fuentes posted to Ojinaga under Pablo Acosta","summary":"In the mid-1980s Amado Carrillo Fuentes, a nephew of Ernesto Fonseca Carrillo, was sent by the Guadalajara federation to Ojinaga, Chihuahua, to oversee Colombian cocaine loads landing on the desert airstrips of Pablo Acosta Villarreal's Ojinaga-Big Bend corridor and to learn border operations. After Acosta's death in 1987 he worked under Rafael Aguilar Guajardo in Ciudad Juárez; he was jailed briefly in 1989 and released.","impact":"The apprenticeship that produced the future 'Señor de los Cielos'; Carrillo Fuentes would turn the Juárez corridor into Mexico's dominant cocaine route in the 1990s.","state":"CHH","city":"Ojinaga","lat":29.5647,"lng":-104.4164,"cartels":["juarez","guadalajara"],"figures":["Amado Carrillo Fuentes","Pablo Acosta Villarreal","Ernesto 'Don Neto' Fonseca Carrillo"],"type":"other","importance":3,"confidence":"medium","sources":["https://druglord.com/cast-of-characters/amado-carrillo-fuentes/","https://en.wikipedia.org/wiki/Amado_Carrillo_Fuentes"]},{"id":"1985-la-langosta-restaurant-killings","date":"1985-01-30","precision":"day","title":"Two Americans killed at La Langosta restaurant in Guadalajara","summary":"On the night of 30 January 1985 American writer John Clay Walker and his friend Alberto Radelat walked into La Langosta seafood restaurant in Guadalajara, where Caro Quintero, Fonseca Carrillo and enforcer Javier Barba Hernández were holding a private party. Mistaken for DEA agents, the two were beaten, tortured in a storeroom and murdered; their bodies were unearthed in a park outside the city in June 1985.","impact":"Showed how paranoid and violent the cartel had become after the Búfalo raid and became part of the US federal case against the Guadalajara leadership, with several participants later convicted in Los Angeles.","state":"JAL","city":"Guadalajara","lat":20.6597,"lng":-103.3496,"cartels":["guadalajara"],"figures":["John Clay Walker","Alberto Radelat","Rafael Caro Quintero","Ernesto 'Don Neto' Fonseca Carrillo","Javier Barba Hernández"],"type":"killing","importance":3,"confidence":"high","sources":["https://www.courtlistener.com/opinion/661793/united-states-v-javier-vasquez-velasco/","https://www.upi.com/Archives/1985/06/18/Police-Tuesday-unearthed-the-remains-of-two-men-believed/9221487915200/"]},{"id":"1985-operation-camarena-border-slowdown","date":"1985-02-01","precision":"month","title":"US Customs near-closes the border in 'Operation Camarena'","summary":"In mid-February 1985 Customs Commissioner William von Raab ordered inspectors at the southwest border ports of entry (reported as all 15 official crossings) to search virtually every vehicle entering from Mexico, ostensibly to intercept information on Camarena. Wait times reached seven hours or more for about a week, paralyzing cross-border commerce, and the Mexican government lodged a formal protest.","impact":"The first use of the border itself as a coercive lever in the drug relationship; it forced the De la Madrid government to escalate the search and prosecutions and set a precedent for later US pressure tactics.","state":"US","city":"San Ysidro, California","lat":32.5527,"lng":-117.043,"cartels":["us_government","government"],"figures":["William von Raab"],"type":"policy","importance":3,"confidence":"high","sources":["https://www.washingtonpost.com/archive/politics/1985/02/20/mexico-protests-us-border-delays-in-kidnap-probe/d986295c-c755-4ad8-a62f-986ffc1d7819/","https://dailycaller.com/2018/10/29/reagan-us-mexico-border-shut-down/","https://www.borderlandbeat.com/2013/08/how-murder-of-kiki-camarena-nearly.html"]},{"id":"1985-camarena-kidnapping-and-murder","date":"1985-02-07","precision":"day","title":"DEA agent Enrique 'Kiki' Camarena kidnapped in Guadalajara","summary":"At midday on 7 February 1985 DEA special agent Enrique Camarena was seized by armed men, several of them police officers working for the cartel, steps from the US consulate in Guadalajara; his Mexican pilot Alfredo Zavala Avelar was taken hours later on the Chapala road. Camarena was interrogated and tortured for roughly 30 hours at a house on Lope de Vega street and died around 9 February.","impact":"Triggered Operation Leyenda, the largest homicide investigation in DEA history, and the worst US-Mexico crisis in decades; it ultimately brought down the Guadalajara Cartel's leadership and forced Mexico to dismantle the DFS.","state":"JAL","city":"Guadalajara","lat":20.6597,"lng":-103.3496,"cartels":["guadalajara","government","us_government"],"figures":["Enrique 'Kiki' Camarena","Alfredo Zavala Avelar","Rafael Caro Quintero","Ernesto 'Don Neto' Fonseca Carrillo","Miguel Ángel Félix Gallardo"],"type":"killing","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Kiki_Camarena","https://zetatijuana.com/2020/02/a-35-anos-del-caso-camarena/","https://www.nbcnews.com/news/us-news/family-slain-us-dea-agent-sues-cartel-3-suspected-drug-kingpins-1985-m-rcna197449"]},{"id":"1985-caro-quintero-guadalajara-airport-escape","date":"1985-02-09","precision":"day","title":"Caro Quintero flies out of Guadalajara after bribing MFJP comandante","summary":"Two days after the kidnapping, federal judicial police comandante Armando Pavón Reyes, assigned to help the DEA find Camarena, cornered Caro Quintero and his gunmen at Guadalajara airport but accepted a bribe (reported as a check for roughly 60 million pesos, about US$275,000-300,000) and let the trafficker's jet take off. Caro Quintero moved between Sonora and Sinaloa before flying to Costa Rica on 17 March. Pavón Reyes was later dismissed and prosecuted for the bribe.","impact":"Became the defining image of police complicity in the Camarena case and hardened the US conviction that Mexican law enforcement was protecting the cartel.","state":"JAL","city":"Guadalajara","lat":20.6597,"lng":-103.3496,"cartels":["guadalajara","government"],"figures":["Rafael Caro Quintero","Armando Pavón Reyes"],"type":"corruption","importance":4,"confidence":"high","sources":["https://zetatijuana.com/2020/02/a-35-anos-del-caso-camarena/","https://en.wikipedia.org/wiki/Kiki_Camarena","https://es.wikipedia.org/wiki/Rafael_Caro_Quintero"]},{"id":"1985-diaz-parada-arrest-oaxaca","date":"1985-03-01","precision":"month","title":"Army arrests Oaxaca marijuana boss Pedro Díaz Parada","summary":"In March 1985 the Mexican Army captured Pedro Díaz Parada, the Isthmus of Tehuantepec grower who had made Oaxaca one of the country's largest marijuana producers, hours before he could board a flight out of the country. On 24 April 1985 federal judge Pedro Villafuerte Gallegos sentenced him to 33 years; Díaz Parada threatened the judge in open court and within months (accounts range from days to about three months) walked out of the Santa María Ixcotel prison in Oaxaca with help from allies inside.","impact":"Marked the emergence of an autonomous southern trafficking clan outside the Guadalajara federation and previewed the impunity of regional bosses; his escape and the judge's later murder made the case notorious.","state":"OAX","city":"Oaxaca de Juárez","lat":17.0732,"lng":-96.7266,"cartels":["oaxaca","government"],"figures":["Pedro Díaz Parada","Pedro Villafuerte Gallegos"],"type":"capture","importance":3,"confidence":"medium","sources":["https://www.milenio.com/policia/cartel-istmo-asesinato-juez-federal-mexico","https://www.cndh.org.mx/sites/default/files/doc/Recomendaciones/1990/REC_1990_015.pdf","https://www.jornada.com.mx/2007/01/18/index.php?section=politica&article=020n1pol"]},{"id":"1985-el-mareno-bravo-family-massacre","date":"1985-03-02","precision":"day","title":"MFJP kills Bravo family at El Mareño ranch in Michoacán","summary":"Acting on a tip that Camarena was being held there, federal judicial police stormed the El Mareño ranch near La Angostura, in the municipality of Vista Hermosa, Michoacán, on 2 March 1985 and killed former Michoacán state legislator Manuel Bravo Cervantes, his wife and three sons; one policeman also died and two 11-year-old boys survived. US investigators later concluded the family had no connection to the kidnapping and suspected the raid was staged to justify placing the bodies of Camarena and Zavala nearby.","impact":"Demonstrated the extent to which the federal police were covering for the cartel; the tampered crime scene and destroyed evidence poisoned DEA-MFJP relations for years.","state":"MIC","city":"La Angostura, Vista Hermosa","lat":20.1964,"lng":-102.4417,"cartels":["government","guadalajara"],"figures":["Manuel Bravo Cervantes"],"type":"massacre","importance":3,"confidence":"medium","sources":["https://zetatijuana.com/2020/02/a-35-anos-del-caso-camarena/","https://www.upi.com/Archives/1985/03/06/A-peasant-discovered-two-bound-bodies-and-police-speculated/4398478933200/","https://partidero.com/el-mareno-comandante-de-la-pjf-ordeno-masacrar-a-familia-para-librar-a-caro-quintero/"]},{"id":"1985-camarena-body-found-la-angostura","date":"1985-03-05","precision":"day","title":"Bodies of Camarena and pilot Zavala found near La Angostura","summary":"On 5 March 1985 the plastic-wrapped, bound bodies of Enrique Camarena and Alfredo Zavala were found beside the road toward Zamora outside La Angostura, Michoacán, a short distance from the El Mareño ranch raided days earlier; they were identified in the Guadalajara morgue on 7 March. Autopsies showed Camarena had been beaten, his skull crushed and a hole drilled into his head; soil analysis showed the bodies had been moved from elsewhere.","impact":"Converted the disappearance into a murder case, producing US indictments of the Guadalajara leadership and a wave of arrests in Mexico within weeks.","state":"MIC","city":"La Angostura, Vista Hermosa","lat":20.1964,"lng":-102.4417,"cartels":["guadalajara","government","us_government"],"figures":["Enrique 'Kiki' Camarena","Alfredo Zavala Avelar"],"type":"discovery","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Kiki_Camarena","https://www.upi.com/Archives/1985/03/06/A-peasant-discovered-two-bound-bodies-and-police-speculated/4398478933200/","https://zetatijuana.com/2020/02/a-35-anos-del-caso-camarena/"]},{"id":"1985-caro-quintero-arrest-costa-rica","date":"1985-04-04","precision":"day","title":"Caro Quintero captured in Alajuela, Costa Rica","summary":"On 4 April 1985 Costa Rican police, guided by the DEA and Mexican federal police commander Guillermo González Calderoni, arrested Rafael Caro Quintero at a mansion (Quinta La California) in San Rafael de Ojo de Agua, Alajuela, near San José's international airport. He had flown out of Guadalajara on 17 March with Sara Cosío Vidaurri, a young woman from a prominent Jalisco political family whose reported kidnapping and a 2 April telephone call home helped investigators trace him. He was expelled to Mexico the next day and later sentenced to 40 years for the Camarena murder.","impact":"Removed the cartel's most flamboyant leader and delivered the first of the three founders to prison; his 2013 early release and 2022 recapture kept the case alive for four decades.","state":"CR","city":"Alajuela, Costa Rica","lat":10.0162,"lng":-84.2117,"cartels":["guadalajara","us_government","government"],"figures":["Rafael Caro Quintero","Sara Cosío Vidaurri","Guillermo González Calderoni"],"type":"capture","importance":4,"confidence":"high","sources":["https://ticotimes.net/2022/07/17/caro-quintero-the-veteran-mexican-narco-of-narcos-never-forgotten-by-the-us","https://www.nacion.com/sucesos/rafael-caro-quintero-y-costa-rica-de-la-opulencia/SDDB5ZOBPBFVTJGJ2B6KOFZC4E/story/","https://www.milenio.com/policia/quien-es-sara-cosio-mujer-que-llevo-a-caro-quintero-a-la-carcel"]},{"id":"1985-fonseca-carrillo-arrest-puerto-vallarta","date":"1985-04-07","precision":"day","title":"Ernesto 'Don Neto' Fonseca Carrillo arrested in Puerto Vallarta","summary":"Three days after Caro Quintero's capture, the Mexican Army surrounded a villa in Puerto Vallarta, Jalisco, on 7 April 1985 and arrested Ernesto Fonseca Carrillo along with his bodyguards, several of them police officers. Fonseca was convicted of the Camarena kidnapping and murder and sentenced to 40 years; he was moved to house arrest in 2016 and released on 5 April 2025 after completing the sentence.","impact":"Left Félix Gallardo as the only founder still free and shifted the federation's day-to-day power to the younger plaza bosses who would later inherit it.","state":"JAL","city":"Puerto Vallarta","lat":20.6534,"lng":-105.2253,"cartels":["guadalajara","government"],"figures":["Ernesto 'Don Neto' Fonseca Carrillo"],"type":"capture","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Ernesto_Fonseca_Carrillo","https://mexiconewsdaily.com/news/guadalajara-cartel-founder-don-neto-released/","https://www.bostonglobe.com/2025/04/09/world/mexican-drug-lord-convicted-killing-dea-agent-released-after-completing-sentence/"]},{"id":"1985-dfs-dissolved","date":"1985-11-29","precision":"day","title":"Mexico dissolves the DFS after narco-corruption scandals","summary":"On 29 November 1985 the De la Madrid government dissolved the Dirección Federal de Seguridad, the political police whose credentials and commanders had shielded the Guadalajara Cartel and whose former director Zorrilla was implicated in the Buendía murder. Its functions passed to a new Dirección General de Investigación y Seguridad Nacional (DISEN), the forerunner of CISEN. Many former DFS agents, including Rafael Aguilar Guajardo, moved directly into trafficking.","impact":"The most significant institutional consequence of the Camarena affair inside Mexico; it broke the formal state umbrella over the traffickers but scattered trained ex-agents into the cartels.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["government","guadalajara"],"figures":["Miguel de la Madrid","Manuel Bartlett","Jorge Carrillo Olea","José Antonio Zorrilla Pérez"],"type":"policy","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Direcci%C3%B3n_Federal_de_Seguridad","https://www.gob.mx/agn/articulos/la-direccion-federal-de-seguridad-dfs-segunda-etapa-policia-politica"]},{"id":"1986-verdugo-urquidez-handover-calexico","date":"1986-01-01","precision":"month","title":"Camarena suspect Verdugo Urquídez handed to US marshals at Calexico","summary":"In January 1986 Mexican police, after discussions with US marshals, seized René Martín Verdugo Urquídez, a Guadalajara Cartel associate suspected in the Camarena murder, in Baja California and drove him to the Border Patrol station at Calexico, California, where US marshals arrested him. DEA agents then searched his Mexicali and San Felipe homes, producing the Supreme Court's 1990 ruling that the Fourth Amendment does not protect foreigners' property abroad.","impact":"The first informal rendition of a Camarena defendant, opening the era of cross-border seizures that culminated in the 1990 abduction of Humberto Álvarez Machaín and a landmark constitutional ruling.","state":"US","city":"Calexico, California","lat":32.6789,"lng":-115.4989,"cartels":["guadalajara","government","us_government"],"figures":["René Verdugo Urquídez"],"type":"extradition","importance":3,"confidence":"high","sources":["https://www.law.cornell.edu/supremecourt/text/494/259","https://caselaw.findlaw.com/court/us-supreme-court/494/259.html"]},{"id":"1986-matta-ballesteros-escapes-bogota-prison","date":"1986-03-01","precision":"month","title":"Matta-Ballesteros escapes Bogotá prison, returns to Honduras","summary":"Juan Ramón Matta Ballesteros had been arrested in Cartagena, Colombia, in April 1985 at the DEA's request as US investigators traced the Camarena case to him. In March 1986, while extradition proceedings were pending, he walked out of Bogotá's La Picota prison, reportedly after paying a multimillion-dollar bribe, and returned to Tegucigalpa, where he lived openly under military protection.","impact":"Kept the Guadalajara-Medellín broker in business for two more years and embarrassed Washington, setting up the 1988 snatch operation in Honduras.","state":"CO","city":"Bogotá, Colombia","lat":4.711,"lng":-74.0721,"cartels":["guadalajara","other"],"figures":["Juan Ramón Matta Ballesteros"],"type":"escape","importance":2,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Juan_Matta-Ballesteros","https://insightcrime.org/honduras-organized-crime-news/juan-matta-ballesteros/"]},{"id":"1986-nsdd-221-narcotics-national-security","date":"1986-04-08","precision":"day","title":"Reagan's NSDD-221 declares drug trafficking a national security threat","summary":"On 8 April 1986 President Reagan signed National Security Decision Directive 221, 'Narcotics and National Security', formally defining the international drug trade as a threat to US security and authorizing the Defense Department, intelligence agencies and the military to support counter-narcotics operations abroad.","impact":"Militarized US drug policy toward Latin America and provided the doctrinal basis for the pressure campaign on Mexico that followed the Camarena murder.","state":"US","city":"Washington, D.C.","lat":38.9072,"lng":-77.0369,"cartels":["us_government"],"figures":["Ronald Reagan"],"type":"policy","importance":3,"confidence":"high","sources":["https://www.reaganlibrary.gov/public/archives/reference/scanned-nsdds/nsdd221.pdf","https://irp.fas.org/offdocs/nsdd/nsdd-221.htm"]},{"id":"1986-ontiveros-el-grenas-arrest-juarez","date":"1986-04-25","precision":"day","title":"Calderoni arrests Juárez boss Gilberto 'El Greñas' Ontiveros","summary":"On 25 April 1986 federal judicial police commander Guillermo González Calderoni arrested Gilberto Ontiveros Lucero, 'El Greñas', the dominant marijuana smuggler of Ciudad Juárez, together with several associates in a drug and weapons raid on his home. The arrest followed US media pressure after Ontiveros kidnapped and tortured El Paso Herald-Post photographer Al Gutiérrez, whom he mistook for a DEA agent. Released on 27 May 1988, Ontiveros was rearrested on 9 January 1989 after tons of marijuana were found in his warehouse and remained imprisoned until 2007.","impact":"Cleared the Juárez plaza for the Guadalajara-linked network of Pablo Acosta, Rafael Aguilar Guajardo and Amado Carrillo Fuentes, and established Calderoni as the government's kingpin hunter.","state":"CHH","city":"Ciudad Juárez","lat":31.6904,"lng":-106.4245,"cartels":["juarez","government"],"figures":["Gilberto 'El Greñas' Ontiveros","Guillermo González Calderoni"],"type":"capture","importance":3,"confidence":"high","sources":["https://eldiariodechihuahua.mx/estado/2025/apr/29/fue-el-grenas-pionero-del-cartel-de-juarez-696214.html","https://www.upi.com/Archives/1986/04/26/Gilberto-Ontiveros-Lucero-a-suspected-border-drug-lord-accused/8528514875600/","https://www.infobae.com/mexico/2025/04/30/muere-el-grenas-pionero-del-cartel-de-juarez-nombrado-como-zar-del-narcotrafico/"]},{"id":"1986-helms-hearings-von-raab-mexico-corruption","date":"1986-05-13","precision":"day","title":"Helms hearings: von Raab accuses Mexican officials of narco-corruption","summary":"At Senate Foreign Relations subcommittee hearings chaired by Jesse Helms in May 1986, Customs Commissioner William von Raab testified that corruption was 'ingrained' in Mexican law enforcement and on 13 May 1986 accused Sonora governor Rodolfo Félix Valdés of involvement in marijuana and opium production. Mexico protested formally and the US government was forced to issue an apology, but the hearings kept Mexican complicity in the Camarena case on the front pages.","impact":"Institutionalized US congressional scrutiny of Mexico's drug record and fed directly into the certification law enacted five months later.","state":"US","city":"Washington, D.C.","lat":38.9072,"lng":-77.0369,"cartels":["us_government","government"],"figures":["William von Raab","Jesse Helms","Rodolfo Félix Valdés"],"type":"policy","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/William_von_Raab"]},{"id":"1986-anti-drug-abuse-act-certification","date":"1986-10-27","precision":"day","title":"Reagan signs Anti-Drug Abuse Act, creating drug certification","summary":"On 27 October 1986 President Reagan signed the Anti-Drug Abuse Act (Public Law 99-570), which imposed mandatory minimum sentences at home and, abroad, required the president to certify each year that major drug-producing and transit countries were 'cooperating fully' with US counter-narcotics efforts or face aid cuts and US opposition to multilateral loans.","impact":"Gave Washington an annual lever over Mexico City; the certification fight became the central irritant in bilateral drug relations until the process was softened in 2002.","state":"US","city":"Washington, D.C.","lat":38.9072,"lng":-77.0369,"cartels":["us_government"],"figures":["Ronald Reagan"],"type":"policy","importance":4,"confidence":"high","sources":["https://www.reaganlibrary.gov/archives/speech/remarks-signing-anti-drug-abuse-act-1986","https://en.wikipedia.org/wiki/Anti-Drug_Abuse_Act_of_1986"]},{"id":"1986-javier-barba-hernandez-killed-mazatlan","date":"1986-11-13","precision":"day","title":"Cartel enforcer Javier Barba Hernández killed by MFJP in Mazatlán","summary":"Javier Barba Hernández, a lawyer turned enforcer for Fonseca Carrillo, Caro Quintero and Félix Gallardo and a wanted suspect in the Camarena and La Langosta cases, was killed in a shootout with federal judicial police in Mazatlán, Sinaloa, on 13 November 1986. The DEA questioned the account after Mexican police declined to share fingerprints for identification.","impact":"Eliminated a key witness to the Camarena torture and deepened DEA suspicions that Mexican police were silencing participants rather than prosecuting them.","state":"SIN","city":"Mazatlán","lat":23.2494,"lng":-106.4111,"cartels":["guadalajara","government"],"figures":["Javier Barba Hernández"],"type":"killing","importance":2,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Javier_Barba-Hern%C3%A1ndez"]},{"id":"1987-garcia-abrego-gulf-cartel-cali-cocaine","date":"1987-01-01","precision":"year","title":"García Ábrego takes the Gulf Cartel into Cali cocaine","summary":"By the late 1980s Juan García Ábrego had effectively displaced his aging uncle Juan Nepomuceno Guerra at the head of the Matamoros smuggling organization that became the Gulf Cartel. Rather than work through the Guadalajara federation, he struck his own deal with the Cali Cartel, taking roughly half of each cocaine shipment as payment for guaranteed delivery into Texas, an arrangement that by the early 1990s moved hundreds of tons a year. The 1987 date is approximate.","impact":"Created the first cocaine cartel independent of the Sinaloan federation and made Tamaulipas the eastern pillar of Mexican trafficking, with the corruption reaching Mexico City that would surface under Salinas.","state":"TAM","city":"Matamoros","lat":25.869,"lng":-97.5027,"cartels":["gulf","other"],"figures":["Juan García Ábrego","Juan Nepomuceno Guerra"],"type":"alliance","importance":4,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Juan_Garc%C3%ADa_Abrego","https://www.texasmonthly.com/true-crime/anatomy-of-a-drug-cartel/"]},{"id":"1987-acapulco-plaza-division-meeting","date":"1987-01-01","precision":"year","title":"Reported Acapulco summit: Félix Gallardo divides the plazas","summary":"According to accounts widely repeated by journalists and the DEA, Félix Gallardo convened the federation's senior traffickers at a house in Acapulco and assigned territories: Tijuana to the Arellano Félix brothers, Ciudad Juárez to Rafael Aguilar Guajardo and the Carrillo Fuentes family, the Pacific corridor to Joaquín Guzmán, Héctor Palma and Ismael Zambada, and Sonora to the Caro Quintero clan, keeping overall arbitration for himself. Some sources place the meeting around 1987, while he was living in Guadalajara; others say his lawyer convened it in 1989 after his arrest, and Félix Gallardo himself has denied it.","impact":"Whether a single meeting or a gradual arrangement, this division is the origin story of the Tijuana, Juárez, Sinaloa and Sonora cartels and of the plaza system that structured Mexican trafficking wars for decades.","state":"GRO","city":"Acapulco","lat":16.8531,"lng":-99.8237,"cartels":["guadalajara","tijuana","juarez","sinaloa","sonora"],"figures":["Miguel Ángel Félix Gallardo","Benjamín Arellano Félix","Rafael Aguilar Guajardo","Amado Carrillo Fuentes","Joaquín 'El Chapo' Guzmán","Héctor 'El Güero' Palma","Ismael 'El Mayo' Zambada","Miguel Caro Quintero"],"type":"split","importance":4,"confidence":"low","sources":["https://en.wikipedia.org/wiki/Miguel_%C3%81ngel_F%C3%A9lix_Gallardo","https://en.wikipedia.org/wiki/Guadalajara_Cartel","https://insightcrime.org/news/analysis/mexicos-top-10-narco-conspiracy-theories/"]},{"id":"1987-pablo-acosta-killed-santa-elena","date":"1987-04-24","precision":"day","title":"Pablo Acosta killed in FBI-backed MFJP raid on Santa Elena","summary":"On 24 April 1987 federal judicial police led by Guillermo González Calderoni, flown in by helicopter across US territory with FBI assistance, attacked the hideout of Ojinaga boss Pablo Acosta Villarreal in the Rio Grande village of Santa Elena, Chihuahua, opposite Big Bend National Park. Acosta, who had been negotiating to become a DEA informant and had given a damaging newspaper interview, refused to surrender and died in the ensuing gun battle, reported to have lasted about an hour.","impact":"Ended the Ojinaga corridor's independence; the Juárez plaza passed to ex-DFS commander Rafael Aguilar Guajardo with Amado Carrillo Fuentes as his lieutenant, the nucleus of the Juárez Cartel.","state":"CHH","city":"Santa Elena, Manuel Benavides","lat":29.1171,"lng":-103.5246,"cartels":["juarez","government","us_government"],"figures":["Pablo Acosta Villarreal","Guillermo González Calderoni","Rafael Aguilar Guajardo"],"type":"killing","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Pablo_Acosta_Villarreal","https://www.texastribune.org/2010/09/22/an-interview-with-the-author-of-drug-lord/","https://druglord.com/cast-of-characters/pablo-acosta/"]},{"id":"1987-javier-caro-payan-arrested-montreal","date":"1987-06-06","precision":"day","title":"Tijuana plaza boss Javier Caro Payán arrested in Montreal","summary":"Javier Caro Payán, a cousin of Rafael Caro Quintero who ran the Tijuana plaza for Félix Gallardo and had brought the young Benjamín Arellano Félix into the business as his secretary, was arrested with his wife Yolanda in Montreal on 6 June 1987 on charges of conspiring to import and traffic marijuana. He was extradited to the United States on 19 April 1988, prosecuted in San Diego and sentenced to 25 years. Some accounts suggest the Arellano Félix brothers tipped off authorities.","impact":"Left the Tijuana corridor in the hands of the Arellano Félix brothers, who consolidated it after Félix Gallardo's arrest; when Caro Payán got out of prison and tried to reclaim the plaza around 1996, Ramón Arellano Félix had him killed in Guadalajara.","state":"CA","city":"Montreal, Canada","lat":45.5017,"lng":-73.5673,"cartels":["tijuana","guadalajara"],"figures":["Javier Caro Payán","Benjamín Arellano Félix"],"type":"capture","importance":3,"confidence":"medium","sources":["https://www.infobae.com/mexico/2024/01/03/asi-fue-como-los-arellano-felix-asesinaron-a-su-maestro-javier-caro-payan/","https://www.upi.com/Archives/1988/02/11/Alleged-Mexican-drug-kingpin-has-extradition-hearing/3514571554000/"]},{"id":"1987-judge-villafuerte-murdered-cuernavaca","date":"1987-09-20","precision":"day","title":"Federal judge who sentenced Díaz Parada murdered in Cuernavaca","summary":"On 20 September 1987 federal judge Pedro Villafuerte Gallegos, who had sentenced Oaxaca trafficker Pedro Díaz Parada to 33 years in 1985 and been threatened by him in court, was shot dead outside his home on Tepozteco street, Colonia Reforma, Cuernavaca, Morelos, where he had been transferred for his safety. The killers, former prisoners who had escaped from the Morelos state penitentiary in June 1987, used two .380-caliber handguns and left a note reading 'balazo por año' ('one bullet per year'), a reference to the 33-year sentence. It is regarded as the first assassination of a federal judge in modern Mexican history.","impact":"An early signal that regional traffickers were willing to kill federal judges, foreshadowing the systematic intimidation of the judiciary in later decades.","state":"MOR","city":"Cuernavaca","lat":18.9242,"lng":-99.2216,"cartels":["oaxaca"],"figures":["Pedro Villafuerte Gallegos","Pedro Díaz Parada"],"type":"killing","importance":3,"confidence":"high","sources":["https://www.milenio.com/policia/cartel-istmo-asesinato-juez-federal-mexico","https://www.cndh.org.mx/sites/default/files/doc/Recomendaciones/1990/REC_1990_015.pdf"]},{"id":"1988-amezcua-colima-cartel-founded","date":"1988-01-01","precision":"year","title":"Amezcua brothers found the Colima Cartel, future meth kings","summary":"The DEA dates to 1988 the emergence of the organization of José de Jesús, Luis and Adán Amezcua Contreras, natives of Colima operating out of Guadalajara. It began by moving cocaine for Colombian suppliers and within a few years pivoted to methamphetamine, importing ephedrine in bulk through contacts in India and Thailand and later Europe, much of it through the port of Manzanillo, and supplying labs on both sides of the border.","impact":"Founded Mexico's first industrial-scale methamphetamine enterprise; by the late 1990s the 'Kings of Methamphetamine' were the leading meth and precursor suppliers to the United States, a business later inherited by the Sinaloa and Jalisco cartels.","state":"JAL","city":"Guadalajara","lat":20.6597,"lng":-103.3496,"cartels":["colima"],"figures":["Jesús Amezcua Contreras","Luis Amezcua Contreras","Adán Amezcua Contreras"],"type":"formation","importance":3,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Colima_Cartel","https://www.borderlandbeat.com/2010/08/colima-cartel.html"]},{"id":"1988-matta-ballesteros-seized-tegucigalpa","date":"1988-04-05","precision":"day","title":"Matta-Ballesteros seized in Tegucigalpa and flown to the US","summary":"On 5 April 1988 Honduran special forces, working with US marshals, grabbed Juan Ramón Matta Ballesteros outside his Tegucigalpa home, blindfolded him and flew him via the Dominican Republic into US custody, circumventing the absence of an extradition treaty. In the following two days crowds, reportedly encouraged by military figures, marched on the US embassy and burned its annex; five people died and a state of emergency was declared.","impact":"Delivered the Guadalajara Cartel's Colombian connection to a Los Angeles courtroom, where he received life sentences for trafficking and the Camarena kidnapping (the kidnapping conviction was vacated in 2017), and showed US willingness to seize suspects abroad.","state":"HN","city":"Tegucigalpa, Honduras","lat":14.0723,"lng":-87.1921,"cartels":["guadalajara","other","us_government"],"figures":["Juan Ramón Matta Ballesteros"],"type":"extradition","importance":3,"confidence":"high","sources":["https://www.upi.com/Archives/1988/04/05/Juan-Ramon-Matta-Ballesteros-described-by-officials-as-perhaps/1601576216000/","https://insightcrime.org/honduras-organized-crime-news/juan-matta-ballesteros/","https://en.wikipedia.org/wiki/Juan_Matta-Ballesteros"]},{"id":"1988-first-camarena-trial-los-angeles","date":"1988-09-01","precision":"month","title":"First Camarena murder trial in Los Angeles convicts three","summary":"In September 1988, after an eight-week trial, a federal jury in Los Angeles returned the first convictions in the Camarena case, finding René Verdugo Urquídez and former Jalisco state policeman Raúl López Álvarez guilty of direct participation in the kidnapping and murder of Camarena and Zavala, and Jesús Félix Gutiérrez, an admitted cocaine dealer who had sheltered Caro Quintero in Costa Rica, guilty of helping the fugitive. Verdugo and López Álvarez were sentenced to life plus 240 years; Félix Gutiérrez received 10 years.","impact":"Opened a decade of Los Angeles prosecutions (ten trials in all) that reached Matta Ballesteros, Rubén Zuno Arce and, in absentia, the cartel's founders, keeping US pressure on Mexico over the case.","state":"US","city":"Los Angeles, California","lat":34.0522,"lng":-118.2437,"cartels":["guadalajara","us_government"],"figures":["René Verdugo Urquídez","Raúl López Álvarez","Jesús Félix Gutiérrez"],"type":"trial","importance":3,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Kiki_Camarena","https://www.upi.com/Archives/1988/09/28/An-admited-cocaine-dealer-was-convicted-Wednesday-of-arranging/5342591422400/","https://www.upi.com/Archives/1990/07/31/The-following-is-a-chronology-of-key-events-in/6231649396800/"]},{"id":"1988-salinas-inauguration-coello-trejo","date":"1988-12-01","precision":"day","title":"Salinas takes office; Coello Trejo named anti-drug prosecutor","summary":"Carlos Salinas de Gortari was sworn in as president on 1 December 1988 after a contested election and, seeking legitimacy in Washington, made drug enforcement an early priority. He installed Javier Coello Trejo, the 'Iron Prosecutor', as deputy attorney general in charge of combating narcotics, with a mandate to deliver high-profile arrests.","impact":"Set up the 1989 offensive that captured Félix Gallardo and purged Sinaloa's police, while leaving the successor cartels to grow under new political arrangements during the NAFTA years.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["government"],"figures":["Carlos Salinas de Gortari","Javier Coello Trejo"],"type":"policy","importance":3,"confidence":"high","sources":["https://www.milenio.com/politica/quien-es-javier-coello-trejo-el-fiscal-de-hierro-perfil","https://en.wikipedia.org/wiki/Carlos_Salinas_de_Gortari"]},{"id":"1989-arellano-felix-take-tijuana-plaza","date":"1989-01-01","precision":"year","title":"Arellano Félix brothers take control of the Tijuana plaza","summary":"With Javier Caro Payán in prison and Félix Gallardo, their mentor and reputed relative, arrested in April 1989, Benjamín, Ramón, Francisco Javier and Eduardo Arellano Félix, Sinaloans who had settled in Tijuana in the 1970s and 1980s, consolidated command of the Baja California corridor, recruiting San Diego gang members and the sons of Tijuana's elite as gunmen.","impact":"Birth of the Tijuana Cartel (Arellano Félix Organization); its refusal to share the crossing with Guzmán and Palma produced the Sinaloa-Tijuana war of the 1990s.","state":"BCN","city":"Tijuana","lat":32.5149,"lng":-117.0382,"cartels":["tijuana","guadalajara"],"figures":["Benjamín Arellano Félix","Ramón Arellano Félix","Francisco Javier Arellano Félix"],"type":"formation","importance":4,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Tijuana_Cartel","https://expansion.mx/nacional/2011/04/29/benjamin-arellano-felix-de-sinaloa-a-tijuana-por-el-dominio-del-narco","https://www.infobae.com/mexico/2024/01/03/asi-fue-como-los-arellano-felix-asesinaron-a-su-maestro-javier-caro-payan/"]},{"id":"1989-palma-family-murders-clavel","date":"1989-01-01","precision":"year","title":"Clavel murders 'El Güero' Palma's wife and children","summary":"Venezuelan Rafael Enrique Clavel Moreno, reportedly sent by Félix Gallardo and the Arellano Félix brothers, seduced Guadalupe Leija Serrano, wife of Sinaloa trafficker Héctor 'El Güero' Palma, persuaded her to withdraw about US$2 million from Palma's accounts and murdered and beheaded her in a San Francisco, California, hotel, sending her head to Palma. About two weeks later he threw the couple's children, Héctor (5) and Nataly (4), from a bridge (identified in most accounts as La Concordia) in San Cristóbal, Táchira, Venezuela. Clavel was arrested in Venezuela and later killed in prison, reportedly on Palma's orders. Most accounts date the crimes to 1989, though some give 1990.","impact":"The atrocity that personalized the Sinaloa-Tijuana feud; Palma and Guzmán's vendetta against the Arellano Félix brothers escalated into the 1990s cartel war.","state":"VE","city":"San Cristóbal, Táchira, Venezuela","lat":7.7669,"lng":-72.225,"cartels":["tijuana","sinaloa"],"figures":["Héctor 'El Güero' Palma","Guadalupe Leija Serrano","Rafael Enrique Clavel Moreno"],"type":"killing","importance":3,"confidence":"medium","sources":["https://es.wikipedia.org/wiki/H%C3%A9ctor_%C2%ABel_G%C3%BCero%C2%BB_Palma","https://www.infobae.com/mexico/2023/02/11/el-pacto-roto-con-la-decapitacion-de-la-esposa-de-el-guero-palma-y-el-asesinato-de-sus-pequenos-hijos/","https://www.local10.com/espanol/2021/05/05/decapitaron-a-su-esposa-y-lanzaron-a-sus-hijos-de-un-puente-la-sangrienta-historia-del-guero-palma/"]},{"id":"1989-felix-gallardo-arrest-guadalajara","date":"1989-04-08","precision":"day","title":"Miguel Ángel Félix Gallardo arrested in Guadalajara","summary":"On 8 April 1989 federal judicial police under deputy attorney general Javier Coello Trejo, with Guillermo González Calderoni taking part, arrested Miguel Ángel Félix Gallardo without a shot at his home in Guadalajara and flew him to Mexico City. Long considered untouchable because of his political and police protection, 'El Padrino' was charged with the Camarena murder, trafficking and bribery; dozens of police officers in Sinaloa were detained in the following days and his properties were seized.","impact":"Ended the Guadalajara Cartel as a unified federation; its plazas passed to the Arellano Félix, Carrillo Fuentes, Guzmán-Palma-Zambada and Caro Quintero groups, whose rivalries defined the next thirty years.","state":"JAL","city":"Guadalajara","lat":20.6597,"lng":-103.3496,"cartels":["guadalajara","government"],"figures":["Miguel Ángel Félix Gallardo","Javier Coello Trejo","Guillermo González Calderoni"],"type":"capture","importance":5,"confidence":"high","sources":["https://www.washingtonpost.com/archive/politics/1989/04/11/mexicans-arrest-prime-drug-suspect/1070f106-7909-4328-a435-d4762d561adb/","https://www.thecrimson.com/article/1989/4/11/mexican-drug-pipeline-leader-arrested-pmexico/","https://www.upi.com/Archives/1989/04/26/Mexican-government-seizes-properties-of-major-drug-dealer/7029609566400/"]},{"id":"1989-zuno-arce-arrested-san-antonio","date":"1989-08-09","precision":"day","title":"Rubén Zuno Arce, ex-president's brother-in-law, held in Texas","summary":"On 9 August 1989 US immigration agents at San Antonio airport detained Rubén Zuno Arce, brother-in-law of former president Luis Echeverría and former owner of the Lope de Vega house where Camarena was tortured, as he arrived on a commercial flight from Mexico; a federal magistrate ordered him held without bail as a material witness. Indicted for perjury on 8 September for denying he knew Caro Quintero, Fonseca and Félix Gallardo, he was later charged and convicted in the Camarena conspiracy and died in US custody in 2012.","impact":"Brought the Camarena prosecution to the door of Mexico's political elite and became the case Mexico most bitterly contested as US judicial overreach.","state":"US","city":"San Antonio, Texas","lat":29.4241,"lng":-98.4936,"cartels":["guadalajara","us_government"],"figures":["Rubén Zuno Arce"],"type":"capture","importance":3,"confidence":"high","sources":["https://www.washingtonpost.com/archive/politics/1989/08/13/drug-suspect-held-in-dea-agents-slaying/72f76949-69b4-46c1-a84d-aa68764cfc7a/","https://www.upi.com/Archives/1989/09/08/Witness-in-Camarena-murder-indicted-for-perjury/7022621230400/"]},{"id":"1989-sylmar-record-cocaine-seizure","date":"1989-09-29","precision":"day","title":"Record 21.4-ton cocaine seizure in Sylmar traced to Juárez","summary":"On 29 September 1989, acting on a neighbor's tip, police and federal agents raided a warehouse at 12898 Bradley Street in Sylmar, Los Angeles, and found 21.4 tons of cocaine and about US$10 million in cash, the largest drug seizure in history at the time. Arrested handlers identified Ciudad Juárez trafficker Rafael Muñoz Talavera as the owner; the cocaine had been flown from Colombia to Chihuahua airstrips, trucked through Juárez and El Paso and warehoused in Los Angeles, and ledgers indicated hundreds of tons had passed through in the preceding months.","impact":"Revealed the scale of the Juárez corridor's cocaine throughput on the eve of Amado Carrillo Fuentes's rise and demonstrated that Mexican organizations, not Colombians, now controlled US-side distribution hubs.","state":"US","city":"Sylmar, Los Angeles, California","lat":34.3078,"lng":-118.4494,"cartels":["juarez","us_government"],"figures":["Rafael Muñoz Talavera"],"type":"discovery","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Sylmar,_Los_Angeles","https://www.upi.com/Archives/1989/11/02/Suspect-in-record-cocaine-seizure-charged/8531625986000/","https://www.latinamericanstudies.org/mexico/munoz.htm"]},{"id":"1990-alvarez-machain-abduction","date":"1990-04-02","precision":"day","title":"DEA-hired agents abduct Dr. Álvarez Machaín from Guadalajara","summary":"On April 2, 1990, Dr. Humberto Álvarez Machaín, a Guadalajara gynecologist accused of keeping DEA agent Enrique Camarena alive during his 1985 torture, was seized from his office by Mexican bounty hunters working for the DEA and flown to El Paso, Texas, where he was arrested. Mexico protested the abduction as a violation of its sovereignty and of the 1978 extradition treaty.","impact":"The case poisoned US–Mexico counternarcotics cooperation for years and framed the extradition debate of the decade; the US Supreme Court upheld the abduction in June 1992 and the doctor was acquitted on December 14, 1992 after Judge Edward Rafeedie called the evidence speculation.","state":"JAL","city":"Guadalajara","lat":20.6597,"lng":-103.3496,"cartels":["us_government","guadalajara"],"figures":["Humberto Álvarez Machaín","Enrique 'Kiki' Camarena"],"type":"capture","importance":4,"confidence":"high","sources":["https://www.abajournal.com/magazine/article/supreme-court-upholds-deas-kidnapping-of-mexican-doctor","https://en.wikipedia.org/wiki/Humberto_%C3%81lvarez_Macha%C3%ADn","https://www.upi.com/Archives/1992/12/15/Doctor-freed-by-US-judge-arrives-in-Mexico/1653724395600/"]},{"id":"1990-agua-prieta-douglas-tunnel","date":"1990-05-17","precision":"day","title":"First narco-tunnel found linking Agua Prieta to Douglas, Arizona","summary":"On May 17, 1990, US agents uncovered a concrete-lined tunnel roughly 80–90 meters (about 270 feet) long running from a house in Agua Prieta, Sonora, to a warehouse in Douglas, Arizona; the Mexican entrance was a pool table raised on hydraulic lifts when an outside water tap was turned, the US end a false floor drain. The raid followed the seizure of more than a ton of cocaine from a truck that had left the warehouse; the tunnel itself was empty. Front man Francisco Rafael Camarena Macías fled, and the structure was later attributed to Joaquín 'El Chapo' Guzmán and his architect Felipe de Jesús Corona Verbera.","impact":"The first cross-border drug tunnel ever discovered revealed the engineering ambition of the emerging Sinaloa organization and inaugurated a smuggling method that would define the border for decades.","state":"SON","city":"Agua Prieta","lat":31.3258,"lng":-109.5489,"cartels":["sinaloa","us_government"],"figures":["Joaquín 'El Chapo' Guzmán","Felipe de Jesús Corona Verbera","Francisco Rafael Camarena Macías"],"type":"discovery","importance":3,"confidence":"medium","sources":["https://themobmuseum.org/blog/the-airport-shootout-and-el-chapos-big-arrest/","https://99percentinvisible.org/episode/the-tunnel/","https://uamr.lib.arizona.edu/item/250919"]},{"id":"1991-cochiloco-killed-zapopan","date":"1991-10-09","precision":"day","title":"Manuel 'El Cochiloco' Salcido gunned down in Zapopan","summary":"Around midday on October 9, 1991, Manuel Salcido Uzeta, 'El Cochiloco', a feared Guadalajara Cartel enforcer and early partner of the Sinaloa traffickers, was shot more than 50 times by at least eight gunmen while driving on Avenida Obsidiana at Lapislázuli in the Residencial Victoria area of Zapopan, Jalisco; his daughter was wounded and an army lieutenant riding with him died. Accounts attribute the hit to Colombian suppliers he had cheated on a cocaine shipment, though military involvement was also alleged.","impact":"His death removed one of the last old-guard Guadalajara bosses still at large and cleared ground for the younger Sinaloa and Tijuana factions whose rivalry would erupt into open war the following year.","state":"JAL","city":"Zapopan","lat":20.7214,"lng":-103.3918,"cartels":["guadalajara","sinaloa"],"figures":["Manuel 'El Cochiloco' Salcido Uzeta"],"type":"killing","importance":3,"confidence":"high","sources":["https://es.wikipedia.org/wiki/Manuel_Salcido_Uzeta","https://www.radioformula.com.mx/noticias/20200224/el-cochiloco-muerto-manuel-salcido-unzueta-historia-narco-guadalajara/","https://www.mural.com.mx/a-30-anos-de-la-ejecucion-del-cochiloco-en-jalisco/ar2274155"]},{"id":"1991-tlalixcoyan-army-kills-federal-agents","date":"1991-11-07","precision":"day","title":"Army troops kill seven federal agents at Tlalixcoyan cocaine airstrip","summary":"In the early hours of November 7, 1991, at the Llano de la Víbora airstrip in Tlalixcoyan, Veracruz, soldiers of the 13th Infantry Battalion shot dead seven Federal Judicial Police agents who had landed in pursuit of a Colombian aircraft carrying cocaine, while a US surveillance plane filmed the scene. The CNDH concluded the agents had been executed, and the commander of the 26th Military Zone, Gen. Alfredo Morán Acevedo, was removed.","impact":"The episode exposed army complicity in protecting Colombian cocaine flights on the Gulf coast and became the emblematic Salinas-era clash between the military and the PGR, foreshadowing the later Gutiérrez Rebollo scandal.","state":"VER","city":"Tlalixcoyan","lat":18.8036,"lng":-96.0625,"cartels":["government","other"],"figures":["Alfredo Morán Acevedo","Ignacio Morales Lechuga"],"type":"corruption","importance":4,"confidence":"high","sources":["https://www.proceso.com.mx/opinion/2018/12/18/el-fantasma-de-llano-de-la-vibora-morales-lechuga-217311.html","https://www.siempre.mx/2016/02/tlalixcoyan-zona-de-muerte/","https://www.cndh.org.mx/sites/default/files/doc/Recomendaciones/1991/REC_1991_126.pdf"]},{"id":"1992-caro-quintero-sonora-arrest-release","date":"1992-01-01","precision":"year","title":"Miguel Caro Quintero arrested, then freed by Hermosillo judge","summary":"Miguel Ángel Caro Quintero, who ran the Sonora Cartel built from Guadalajara Cartel remnants after his brother Rafael's 1985 arrest, was detained in 1992 on tax-evasion charges in a joint US–Mexican prosecution effort. A federal judge in Hermosillo threw out the case, which the DEA attributed to threats and bribes, and he went back to moving marijuana and Cali cocaine through ranches around Agua Prieta and Hermosillo with his brothers Jorge and Genaro.","impact":"The release showed how judicial corruption shielded the Caro Quintero clan through the decade; Miguel remained a fugitive under multiple US indictments until his capture in Los Mochis in December 2001.","state":"SON","city":"Hermosillo","lat":29.0729,"lng":-110.9559,"cartels":["sonora"],"figures":["Miguel Ángel Caro Quintero","Rafael Caro Quintero"],"type":"capture","importance":3,"confidence":"medium","sources":["https://www.pbs.org/wgbh/pages/frontline/shows/mexico/etc/caro.html","https://en.wikipedia.org/wiki/Miguel_Caro_Quintero","https://en.wikipedia.org/wiki/Sonora_Cartel"]},{"id":"1992-alvarez-machain-supreme-court","date":"1992-06-15","precision":"day","title":"US Supreme Court upholds DEA abduction in Alvarez-Machain","summary":"On June 15, 1992, the US Supreme Court ruled 6–3 in United States v. Alvarez-Machain that the forcible abduction of a Mexican citizen did not bar his trial in US courts because the extradition treaty did not expressly prohibit it. Mexico condemned the ruling and demanded a renegotiation of the treaty.","impact":"The decision inflamed Mexican nationalism, led to new restrictions on DEA agents operating in Mexico, and shaped the cautious extradition politics of the rest of the decade.","state":"US","city":"Washington, D.C.","lat":38.9072,"lng":-77.0369,"cartels":["us_government","government"],"figures":["Humberto Álvarez Machaín"],"type":"trial","importance":3,"confidence":"high","sources":["https://www.law.cornell.edu/supremecourt/text/504/655","https://supreme.justia.com/cases/federal/us/504/655/","https://www.abajournal.com/magazine/article/supreme-court-upholds-deas-kidnapping-of-mexican-doctor"]},{"id":"1992-christine-disco-shootout","date":"1992-11-08","precision":"day","title":"Christine discotheque shootout in Puerto Vallarta","summary":"Before dawn on November 8, 1992, some 35 gunmen sent by Joaquín 'El Chapo' Guzmán and Héctor 'El Güero' Palma, several in police uniforms, stormed the Christine disco in Puerto Vallarta where Ramón and Francisco Javier Arellano Félix were partying. Six people were killed and several wounded; the Arellano Félix brothers escaped through a bathroom. Six police officers were later arrested in connection with the attack.","impact":"The raid turned the Sinaloa–Tijuana feud into open war and set up the Arellano Félix retaliation that culminated at the Guadalajara airport in May 1993.","state":"JAL","city":"Puerto Vallarta","lat":20.6534,"lng":-105.2253,"cartels":["sinaloa","tijuana"],"figures":["Joaquín 'El Chapo' Guzmán","Héctor 'El Güero' Palma","Ramón Arellano Félix","Francisco Javier Arellano Félix"],"type":"attack","importance":4,"confidence":"high","sources":["https://www.upi.com/Archives/1992/11/09/Six-killed-in-Mexico-disco-shootout/5689721285200/","https://www.upi.com/Archives/1992/11/20/Six-policemen-arrested-after-disco-slayings/7165722235600/","https://www.vice.com/en/article/explosive-testimony-at-el-chapos-trial-tells-new-history-of-the-sinaloa-cartel/"]},{"id":"1993-aguilar-guajardo-killed-cancun","date":"1993-04-12","precision":"day","title":"Juárez boss Rafael Aguilar Guajardo shot dead in Cancún","summary":"On April 12, 1993, Rafael Aguilar Guajardo, the former Federal Security Directorate (DFS) commander who had led the Juárez trafficking organization since the late 1980s, was gunned down outside the Gypsys restaurant on Cancún's hotel strip as he returned from a submarine tour with his family; an American tourist, Georgina Knafel, was also killed and his wife and 11-year-old son were wounded. His lieutenant Amado Carrillo Fuentes, widely suspected of ordering the hit, took over the organization.","impact":"The killing handed the Ciudad Juárez corridor to Carrillo Fuentes, who would turn it into the most powerful cartel in Mexico by the mid-1990s.","state":"ROO","city":"Cancún","lat":21.1619,"lng":-86.8515,"cartels":["juarez"],"figures":["Rafael Aguilar Guajardo","Amado Carrillo Fuentes"],"type":"killing","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Rafael_Aguilar_Guajardo","https://insightcrime.org/mexico-organized-crime-news/juarez-cartel-profile/"]},{"id":"1993-posadas-ocampo-killed-guadalajara-airport","date":"1993-05-24","precision":"day","title":"Cardinal Posadas Ocampo killed at Guadalajara airport","summary":"On May 24, 1993, Cardinal Juan Jesús Posadas Ocampo, Archbishop of Guadalajara, was shot 14 times in his car in the parking lot of Guadalajara's international airport; six other people died. The government concluded that Arellano Félix gunmen, in the city to kill Joaquín 'El Chapo' Guzmán, mistook the cardinal's white Grand Marquis for Guzmán's while Guzmán's men fired back; the Church and many investigators have never accepted that account.","impact":"The killing stunned Mexico, made 'El Chapo' a household name, triggered the manhunt that caught him in Guatemala two weeks later, and its unresolved contradictions fed lasting distrust of the federal investigation.","state":"JAL","city":"Guadalajara","lat":20.5218,"lng":-103.3111,"cartels":["tijuana","sinaloa","government"],"figures":["Juan Jesús Posadas Ocampo","Joaquín 'El Chapo' Guzmán","Ramón Arellano Félix","Benjamín Arellano Félix"],"type":"killing","importance":5,"confidence":"high","sources":["https://www.catholicnewsagency.com/news/29788/mexicans-continue-to-seek-truth-behind-cardinals-murder","https://commdocs.house.gov/committees/intlrel/hfa26906.000/hfa26906_0.htm","https://theguadalajarareporter.net/index.php/news/news/guadalajara/59859-cardinal-s-1993-slaying-at-airport-still-a-mystery"]},{"id":"1993-chapo-arrested-guatemala","date":"1993-06-09","precision":"day","title":"El Chapo captured in Guatemala and handed over at Talismán bridge","summary":"On June 9, 1993, Guatemalan soldiers detained Joaquín 'El Chapo' Guzmán near the Mexican border in San Marcos department, where he had fled after the Posadas killing, and delivered him to Mexican officials at the Talismán international bridge over the Suchiate River in Chiapas; Attorney General Jorge Carpizo announced the capture. He was flown to Mexico City and jailed at the Almoloya de Juárez maximum-security prison.","impact":"Guzmán's first imprisonment left Héctor Palma and Ismael 'El Mayo' Zambada running Sinaloa operations, while Guzmán retained influence from prison until his 2001 escape.","state":"CHP","city":"Talismán","lat":14.9646,"lng":-92.1477,"cartels":["sinaloa","government"],"figures":["Joaquín 'El Chapo' Guzmán","Jorge Carpizo McGregor"],"type":"capture","importance":5,"confidence":"high","sources":["https://www.prensalibre.com/hemeroteca/joaquin-el-chapo-guzman-es-capturado-en-guatemala/","https://www.proceso.com.mx/reportajes/2014/2/22/junio-de-1993-una-primera-captura-bajo-sospecha-129459.html","https://www.milenio.com/internacional/las-tres-capturas-de-el-chapo"]},{"id":"1993-bali-hai-attack-amado-carrillo","date":"1993-11-24","precision":"day","title":"Arellano Félix gunmen try to kill Amado Carrillo at Bali Hai","summary":"On November 24, 1993, gunmen sent by Ramón and Benjamín Arellano Félix opened fire on Amado Carrillo Fuentes as he dined with his family at the Ochoa Bali Hai seafood restaurant on Avenida Insurgentes Sur in Mexico City; two people were killed in the exchange. Carrillo and his family escaped through the back of the restaurant after his bodyguard Alcides Ramón Magaña, 'El Metro', held off the attackers.","impact":"The failed hit ended any pretense of peace between the Tijuana organization and the Juárez–Sinaloa camp and pushed Carrillo Fuentes to deepen his political and military protection in the capital.","state":"CMX","city":"Ciudad de México","lat":19.3719,"lng":-99.1798,"cartels":["tijuana","juarez"],"figures":["Amado Carrillo Fuentes","Ramón Arellano Félix","Benjamín Arellano Félix","Alcides Ramón Magaña"],"type":"attack","importance":3,"confidence":"medium","sources":["https://www.elfinanciero.com.mx/food-and-drink/2023/02/08/el-senor-de-los-cielos-asi-era-ochoa-bali-hai-el-restaurante-de-insurgentes-cdmx-donde-comia/","https://www.infobae.com/mexico/2024/01/23/asi-era-el-restaurante-de-la-cdmx-donde-los-arellano-felix-casi-matan-a-el-senor-de-los-cielos/","https://es.wikipedia.org/wiki/C%C3%A1rtel_de_los_Arellano_F%C3%A9lix"]},{"id":"1993-francisco-rafael-arellano-arrested","date":"1993-12-04","precision":"day","title":"Francisco Rafael Arellano Félix arrested in Tijuana","summary":"On December 4, 1993, federal judicial police arrested Francisco Rafael Arellano Félix, the eldest of the Arellano Félix brothers, in Tijuana in the aftermath of the Posadas killing. He was held at the Almoloya maximum-security prison and given a ten-year sentence, but remained in Mexican custody until his extradition to the United States in September 2006, where he pleaded guilty and was released in March 2008.","impact":"The first capture of an Arellano Félix brother was the government's main visible result against the Tijuana Cartel after the cardinal's murder, though Benjamín and Ramón remained free and in command for nearly a decade.","state":"BCN","city":"Tijuana","lat":32.5149,"lng":-117.0382,"cartels":["tijuana","government"],"figures":["Francisco Rafael Arellano Félix"],"type":"capture","importance":3,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Francisco_Rafael_Arellano_F%C3%A9lix","https://insightcrime.org/mexico-organized-crime-news/tijuana-cartel-profile/","https://www.foxnews.com/story/second-brother-in-mexican-drug-cartel-facing-charges-in-u-s"]},{"id":"1994-colosio-assassination-tijuana","date":"1994-03-23","precision":"day","title":"PRI candidate Luis Donaldo Colosio assassinated in Tijuana","summary":"On March 23, 1994, PRI presidential candidate Luis Donaldo Colosio was shot in the head at a campaign rally in the Lomas Taurinas neighborhood of Tijuana; Mario Aburto Martínez was arrested at the scene and convicted as the lone gunman. Investigators examined and officially discarded hypotheses that drug traffickers, in a city then dominated by the Arellano Félix organization, ordered the killing.","impact":"The murder shook Mexico's political system and brought Ernesto Zedillo to the presidency; together with the Posadas case and the Ruiz Massieu murder it fixed the perception of a narco-politics nexus that framed the drug war of the late 1990s.","state":"BCN","city":"Tijuana","lat":32.5085,"lng":-117.0622,"cartels":["government"],"figures":["Luis Donaldo Colosio","Mario Aburto Martínez","Ernesto Zedillo"],"type":"killing","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Luis_Donaldo_Colosio","https://es.wikipedia.org/wiki/Asesinato_de_Luis_Donaldo_Colosio"]},{"id":"1994-benitez-lopez-tijuana-police-chief-killed","date":"1994-04-28","precision":"day","title":"Tijuana police chief Federico Benítez López ambushed and killed","summary":"On the night of April 28, 1994, Tijuana municipal police chief Federico Benítez López and an aide were killed by gunmen who pulled alongside his vehicle in Tijuana after he had been drawn out toward the airport road by a false bomb threat. Benítez, a PAN appointee who had confronted the Arellano Félix organization and was pursuing his own inquiry into the Colosio killing, was the highest-ranking official murdered in the city that year.","impact":"The assassination showed the Tijuana Cartel's readiness to kill uncooperative officials and reinforced public suspicion surrounding the Colosio investigation.","state":"BCN","city":"Tijuana","lat":32.5149,"lng":-117.0382,"cartels":["tijuana"],"figures":["Federico Benítez López"],"type":"killing","importance":3,"confidence":"medium","sources":["https://www.upi.com/Archives/1994/04/29/Tijuana-police-chief-gunned-down/9307932679005/","https://www.washingtonpost.com/archive/politics/1994/04/30/police-chiefs-death-rocks-tijuana/6ce59aa5-84cc-4c3a-9894-5fa2816c2846/"]},{"id":"1995-colombian-cartels-fall-power-shift","date":"1995-01-01","precision":"year","title":"Fall of Medellín and Cali cartels shifts cocaine power to Mexico","summary":"Between Pablo Escobar's death in Medellín on December 2, 1993 and the capture of Cali bosses Gilberto (June 9, 1995) and Miguel Rodríguez Orejuela (August 6, 1995), the Colombian syndicates that had paid Mexican smugglers in cash fragmented. Mexican organizations, above all Amado Carrillo Fuentes' Juárez Cartel and the Sinaloa, Gulf and Tijuana groups, increasingly took payment in cocaine and assumed control of wholesale distribution inside the United States.","impact":"This transfer of the most profitable stage of the cocaine business to Mexico underwrote the wealth, firepower and corruption capacity of the Mexican cartels for the next two decades.","state":"MULTI","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["juarez","sinaloa","gulf","tijuana"],"figures":["Amado Carrillo Fuentes","Gilberto Rodríguez Orejuela","Pablo Escobar"],"type":"other","importance":5,"confidence":"high","sources":["https://www.washingtonpost.com/archive/politics/1995/06/10/colombia-arrests-leader-of-top-drug-cartel/634b618f-a50f-4068-8106-2d227adca697/","https://www.deseret.com/1995/6/10/19176445/colombia-captures-chief-of-cali-cartel/","https://insightcrime.org/mexico-organized-crime-news/juarez-cartel-profile/"]},{"id":"1995-raul-salinas-arrested","date":"1995-02-28","precision":"day","title":"Raúl Salinas arrested; Swiss probe ties his fortune to cartels","summary":"On February 28, 1995, Raúl Salinas de Gortari, brother of former president Carlos Salinas, was arrested in Mexico City and charged with masterminding the September 28, 1994 murder of PRI secretary general José Francisco Ruiz Massieu. In November 1995 his wife Paulina Castañón was detained in Geneva trying to withdraw about $84 million from an account held under an alias; Swiss investigators concluded much of his more than $100 million abroad was protection money from drug traffickers, though no laundering charge was ever proven and Switzerland later returned most of the funds to Mexico.","impact":"The case placed the presidential family at the center of Mexico's narco-corruption debate and became the reference point for suspicions of cartel penetration at the top of the Salinas government.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["gulf","government"],"figures":["Raúl Salinas de Gortari","José Francisco Ruiz Massieu","Carlos Salinas de Gortari"],"type":"corruption","importance":4,"confidence":"high","sources":["https://www.washingtonpost.com/archive/politics/1995/03/01/salinass-brother-accused-of-murder/57857090-252a-40bd-8129-395a0454d6c7/","https://www.pbs.org/wgbh/pages/frontline/shows/mexico/family/raulsalinas.html","https://en.wikipedia.org/wiki/Ra%C3%BAl_Salinas"]},{"id":"1995-mario-ruiz-massieu-arrested-newark","date":"1995-03-03","precision":"day","title":"Ex-deputy attorney general Mario Ruiz Massieu detained at Newark","summary":"On March 3, 1995, US Customs detained former Mexican deputy attorney general Mario Ruiz Massieu at Newark airport for failing to declare cash as he fled Mexico, where he was accused of obstructing the investigation into his brother's murder. US authorities froze about $9 million in his Texas bank accounts, and a Houston civil jury in 1997 found the money came from bribes paid by drug traffickers, chiefly the Gulf Cartel, for protection.","impact":"The case showed that Mexico's top anti-drug prosecutor of 1993–94 had been on cartel payrolls and deepened US congressional distrust of Mexican institutions; Ruiz Massieu killed himself in New Jersey in September 1999 before he could be tried.","state":"US","city":"Newark, New Jersey","lat":40.6895,"lng":-74.1745,"cartels":["gulf","government","us_government"],"figures":["Mario Ruiz Massieu","Juan García Ábrego"],"type":"corruption","importance":3,"confidence":"high","sources":["https://www.washingtonpost.com/archive/politics/1995/03/05/us-arrests-mexico-city-probe-figure/3fa18d3b-2742-4052-a093-c784c8a67e6f/","https://law.justia.com/cases/federal/district-courts/FSupp/915/681/1618129/","https://www-tc.pbs.org/wgbh/pages/frontline/shows/mexico/family/marioruizmassieu.html"]},{"id":"1995-garcia-abrego-fbi-ten-most-wanted","date":"1995-03-09","precision":"day","title":"García Ábrego becomes first drug lord on FBI Ten Most Wanted list","summary":"On March 9, 1995, the FBI placed Gulf Cartel leader Juan García Ábrego on its Ten Most Wanted Fugitives list, the first international drug trafficker ever so listed, citing a 1993 Houston indictment for moving Cali cartel cocaine into the United States and authorizing murders.","impact":"The listing signaled Washington's pressure on the new Zedillo government to deliver a major capo and set up the joint effort that captured García Ábrego ten months later.","state":"US","city":"Washington, D.C.","lat":38.9072,"lng":-77.0369,"cartels":["gulf","us_government"],"figures":["Juan García Ábrego"],"type":"policy","importance":3,"confidence":"high","sources":["https://www.justice.gov/archive/opa/pr/Pre_96/March95/133c.txt.html","https://www.justice.gov/archive/opa/pr/1996/January96/003.txt"]},{"id":"1995-guero-palma-arrested-guadalajara","date":"1995-06-23","precision":"day","title":"El Güero Palma captured after jet crash-lands in Nayarit","summary":"A Learjet carrying Héctor Luis 'El Güero' Palma Salazar from Ciudad Obregón to a wedding in Guadalajara crash-landed near Tepic, Nayarit, and on June 23, 1995 soldiers arrested the injured Sinaloa boss at a house in the Guadalajara area belonging to a Federal Judicial Police commander, where he was being sheltered by federal agents. Palma, El Chapo's partner in the war against the Arellano Félix brothers, had been travelling with PJF credentials and armed police escorts.","impact":"The capture decapitated Guzmán's faction two years after his own arrest, exposed the wholesale corruption of the federal police in Jalisco, and left Ismael 'El Mayo' Zambada and the Carrillo Fuentes–Beltrán Leyva network as the dominant Sinaloan players.","state":"JAL","city":"Guadalajara","lat":20.6597,"lng":-103.3496,"cartels":["sinaloa","government"],"figures":["Héctor Luis 'El Güero' Palma Salazar"],"type":"capture","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/H%C3%A9ctor_Luis_Palma_Salazar","https://www.elfinanciero.com.mx/nacional/2023/05/10/hector-el-guero-palma-asi-fue-el-avionazo-por-el-que-lo-arrestaron-en-1995/","https://fox5sandiego.com/news/border-report/druglord-el-guero-palma-narcos-mexico-character-and-co-founder-of-chapos-sinaloa-cartel-to-be-released-from-prison/"]},{"id":"1995-chapo-transferred-puente-grande","date":"1995-11-22","precision":"day","title":"El Chapo transferred to Puente Grande prison in Jalisco","summary":"In the early hours of November 22, 1995, Joaquín 'El Chapo' Guzmán was moved from the Almoloya de Juárez maximum-security prison in the State of Mexico to the Federal Social Readaptation Center No. 2 at Puente Grande, Jalisco. There he progressively bought control of guards and administrators, ran his business by telephone and lived in comfort.","impact":"The transfer created the conditions for his January 2001 escape and for the reconstitution of the Sinaloa Federation in the 2000s.","state":"JAL","city":"Puente Grande","lat":20.5333,"lng":-103.1667,"cartels":["sinaloa","government"],"figures":["Joaquín 'El Chapo' Guzmán"],"type":"other","importance":2,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Manhunt_of_Joaqu%C3%ADn_%22El_Chapo%22_Guzm%C3%A1n","https://www.infobae.com/mexico/2024/02/27/asi-fue-la-mudanza-de-el-chapo-guzman-del-altiplano-a-puente-grande/","https://time.com/4173454/el-chapo-capture-escape-timeline/"]},{"id":"1996-garcia-abrego-captured-monterrey","date":"1996-01-14","precision":"day","title":"Gulf Cartel chief Juan García Ábrego captured near Monterrey","summary":"On January 14, 1996, federal agents in Operation Leyenda stormed a walled ranch house in Villa Juárez, just southeast of Monterrey, Nuevo León, and seized Gulf Cartel leader Juan García Ábrego without a shot as he tried to jump a fence. The next day President Ernesto Zedillo expelled him to the United States as a US citizen and he was flown to Houston.","impact":"The first delivery of a top Mexican capo to US justice broke the Gulf Cartel's leadership, opened a succession fight won by Osiel Cárdenas in 1999, and became the model for later expulsions and extraditions.","state":"NLE","city":"Juárez (Villa Juárez)","lat":25.6468,"lng":-100.0956,"cartels":["gulf","government","us_government"],"figures":["Juan García Ábrego","Ernesto Zedillo"],"type":"capture","importance":5,"confidence":"high","sources":["https://time.com/archive/6728478/the-capture-of-americas-most-wanted/","https://www.eluniversal.com.mx/articulo/estados/2016/01/14/la-captura-garcia-abrego-20-anos-despues/","https://www.justice.gov/archive/opa/pr/1996/January96/003.txt"]},{"id":"1996-ibarra-santes-killed-mexico-city","date":"1996-09-14","precision":"day","title":"Federal police commander Ernesto Ibarra Santés killed in Mexico City","summary":"On September 14, 1996, Ernesto Ibarra Santés, the recently appointed Federal Judicial Police (PGR) commander for Baja California who had publicly vowed to dismantle the Arellano Félix organization, was shot dead in a taxi minutes after leaving Mexico City's airport for PGR headquarters, along with two agents and the driver. US court filings later stated that Baja California state prosecutors had tipped the cartel to his travel plans.","impact":"The killing demonstrated the Tijuana Cartel's reach into the capital and its penetration of Baja California's justice system, and it opened the wave of attacks on officials and journalists in Tijuana in 1997–98.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["tijuana","government"],"figures":["Ernesto Ibarra Santés"],"type":"killing","importance":3,"confidence":"high","sources":["https://www.deseret.com/1997/6/21/19318920/extradition-case-gives-look-at-vicious-cocaine-group/","https://law.resource.org/pub/us/case/reporter/F3/164/164.F3d.1199.98-55069.98-55067.html","https://afntijuana.info/informacion_general/94447_el_asesinato_de_ibarra_santes"]},{"id":"1996-garcia-abrego-convicted-houston","date":"1996-10-16","precision":"day","title":"García Ábrego convicted in Houston, later given 11 life terms","summary":"On October 16, 1996, a federal jury in Houston convicted Juan García Ábrego on 22 counts of drug trafficking, money laundering and running a continuing criminal enterprise after a four-week trial in which former lieutenants testified against him. On January 31, 1997 Judge Ewing Werlein sentenced him to eleven consecutive life terms and ordered the forfeiture of some $350 million.","impact":"The verdict proved that a Mexican kingpin could be tried and buried in the US prison system, strengthening Washington's push for extraditions of cartel leaders.","state":"US","city":"Houston, Texas","lat":29.7604,"lng":-95.3698,"cartels":["gulf","us_government"],"figures":["Juan García Ábrego"],"type":"trial","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Juan_Garc%C3%ADa_Abrego","https://content.time.com/time/specials/packages/article/0,28804,1971762_1971761_1971728,00.html"]},{"id":"1996-ley-federal-delincuencia-organizada","date":"1996-11-07","precision":"day","title":"Ley Federal contra la Delincuencia Organizada enacted","summary":"On November 7, 1996, the Federal Law against Organized Crime was published in the Diario Oficial de la Federación, creating for the first time a specific offense of organized-crime membership and authorizing wiretaps, protected witnesses, asset seizure, extended pre-charge detention (arraigo) and sentence reductions for cooperators. It was the legal centerpiece of President Zedillo's response to cartel power.","impact":"The law became the framework for every major cartel prosecution that followed and, with the 1997 creation of the FEADS prosecutor's office and the 1999 Federal Preventive Police, defined Mexico's federal anti-crime architecture for the next decade.","state":"MULTI","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["government"],"figures":["Ernesto Zedillo","Antonio Lozano Gracia"],"type":"policy","importance":4,"confidence":"high","sources":["https://www.diputados.gob.mx/LeyesBiblio/pdf/LFCDO.pdf","https://www.refworld.org/es/leg/legis/pleg/1996/es/125920","https://cdigital.uv.mx/server/api/core/bitstreams/b28bf693-5718-4928-9383-0c8d97023803/content"]},{"id":"1997-gutierrez-rebollo-drug-czar-arrested","date":"1997-02-06","precision":"day","title":"Drug czar Gen. Gutiérrez Rebollo arrested for serving Juárez Cartel","summary":"On the night of February 6, 1997, Gen. Jesús Gutiérrez Rebollo, named head of the National Institute to Combat Drugs (INCD) only in December 1996 and publicly praised by US officials, was arrested by the army high command in Mexico City; the government announced it on February 18. He was found to be living in an apartment provided by Amado Carrillo Fuentes and passing intelligence to the Juárez Cartel, and was eventually sentenced to a combined 71 years (reduced to 40 in 2011).","impact":"Breaking weeks before the US certification decision, the scandal destroyed the INCD, which was replaced by the FEADS prosecutor's office, and became the defining proof that cartels had bought the very top of Mexico's drug enforcement.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["juarez","government"],"figures":["Jesús Gutiérrez Rebollo","Amado Carrillo Fuentes"],"type":"corruption","importance":5,"confidence":"high","sources":["https://www.tni.org/en/article/mexico-the-narco-general-case","http://www.cnn.com/WORLD/9702/25/mexico.drugs/","https://www.pbs.org/wgbh/pages/frontline/shows/mexico/family/genrebollo.html"]},{"id":"1997-malherbe-arrested-mexico-city","date":"1997-02-26","precision":"day","title":"Gulf Cartel successor Óscar Malherbe arrested in Mexico City","summary":"On February 26, 1997, federal agents arrested Óscar Malherbe de León, who had run the Gulf Cartel's trafficking operations since García Ábrego's capture, at a shopping center in the Mixcoac area of Mexico City; he reportedly offered $2 million to be released.","impact":"His removal left the Gulf organization to a violent succession contest in Tamaulipas among Salvador 'El Chava' Gómez, Osiel Cárdenas and other lieutenants.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["gulf","government"],"figures":["Óscar Malherbe de León"],"type":"capture","importance":3,"confidence":"high","sources":["https://www.upi.com/Archives/1997/02/28/Mexico-captures-reputed-druglord/3237857106000/","https://en.wikipedia.org/wiki/%C3%93scar_Malherbe_de_Le%C3%B3n"]},{"id":"1997-vicente-carrillo-takes-juarez-cartel","date":"1997-07-01","precision":"month","title":"Vicente Carrillo Fuentes takes command of the Juárez Cartel","summary":"In the weeks after Amado's death in July 1997, his brother Vicente Carrillo Fuentes, 'El Viceroy', moved to take control of the Juárez Cartel against rivals, notably Rafael Muñoz Talavera, whose body was found in Ciudad Juárez in September 1998. A wave of executions in Ciudad Juárez in August 1997, including a machine-gun attack on the Max Fim restaurant, marked the fight. Vicente consolidated power alongside Juan José 'El Azul' Esparragoza, his brother Rodolfo and the Beltrán Leyva brothers.","impact":"The succession preserved the Juárez organization as a major national player into the 2000s and set up its later, far bloodier split with the Sinaloa Federation.","state":"CHH","city":"Ciudad Juárez","lat":31.6904,"lng":-106.4245,"cartels":["juarez","sinaloa"],"figures":["Vicente Carrillo Fuentes","Rafael Muñoz Talavera","Juan José 'El Azul' Esparragoza"],"type":"other","importance":4,"confidence":"medium","sources":["https://insightcrime.org/mexico-organized-crime-news/juarez-cartel-profile/","https://en.wikipedia.org/wiki/Vicente_Carrillo_Fuentes"]},{"id":"1997-amado-carrillo-fuentes-dies","date":"1997-07-04","precision":"day","title":"Amado Carrillo Fuentes dies after plastic surgery in Mexico City","summary":"Amado Carrillo Fuentes, 'El Señor de los Cielos', leader of the Juárez Cartel and Mexico's most powerful trafficker, checked into the Santa Mónica hospital in Mexico City's Polanco district under an alias and died on July 4, 1997 (some accounts place it in the early hours of July 5) after hours of facial surgery and liposuction intended to disguise him. The body was identified by fingerprints days later.","impact":"His death removed the organizer of the Mexican cocaine transport system at its peak, triggered a succession war in Ciudad Juárez, and cut the political-protection network exposed months earlier by the Gutiérrez Rebollo case.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["juarez"],"figures":["Amado Carrillo Fuentes"],"type":"other","importance":5,"confidence":"high","sources":["https://www.deseret.com/1997/7/7/19322002/extensive-plastic-surgery-blamed-for-drug-lord-s-death/","https://www.pbs.org/wgbh/pages/frontline/shows/mexico/family/juarezcartel.html","https://en.wikipedia.org/wiki/Amado_Carrillo_Fuentes"]},{"id":"1997-ramon-arellano-fbi-ten-most-wanted","date":"1997-09-18","precision":"day","title":"Ramón Arellano Félix placed on FBI Ten Most Wanted list","summary":"On September 18, 1997, the FBI added Ramón Eduardo Arellano Félix, enforcement chief of the Tijuana Cartel, to its Ten Most Wanted Fugitives list as the 451st fugitive, under a sealed San Diego indictment for conspiring to import cocaine and marijuana, with a reward offered for his capture.","impact":"The listing internationalized the hunt for the Arellano Félix brothers and marked the Tijuana Cartel, alongside Juárez, as Washington's top Mexican target for the rest of the decade.","state":"US","city":"Washington, D.C.","lat":38.9072,"lng":-77.0369,"cartels":["tijuana","us_government"],"figures":["Ramón Arellano Félix"],"type":"policy","importance":3,"confidence":"high","sources":["https://www.dea.gov/sites/default/files/pubs/pressrel/pr970918.htm","https://www.washingtonpost.com/archive/politics/1997/09/25/us-names-mexican-trafficker-to-fbis-wanted-list/2f7a1d12-1318-4f2f-919f-216ebfd30cd0/"]},{"id":"1997-amado-surgeons-bodies-found","date":"1997-11-01","precision":"month","title":"Amado Carrillo's plastic surgeons found dead in cement-filled drums","summary":"In the first days of November 1997, the bodies of Jaime Godoy Singh, Carlos Ávila and the Colombian Ricardo Reyes Rincón, three of the doctors who had taken part in Amado Carrillo Fuentes' fatal surgery, were found tortured and encased in concrete inside steel drums dumped along the Mexico City–Acapulco highway; the remains were taken to the forensic service in Iguala, Guerrero. Contemporary reports differ on the exact day of discovery.","impact":"The killings were read as the Juárez Cartel's punishment for Amado's death and dramatized the organization's brutality under its new leadership.","state":"GRO","city":"Iguala","lat":18.3453,"lng":-99.5384,"cartels":["juarez"],"figures":["Jaime Godoy Singh","Amado Carrillo Fuentes"],"type":"killing","importance":3,"confidence":"medium","sources":["https://www.spokesman.com/stories/1997/nov/10/mystery-in-mexico-drug-baron-may-have-been/","https://www.borderlandbeat.com/2022/12/this-is-how-plastic-surgeons-of-amado.html","https://www.pbs.org/wgbh/pages/frontline/shows/mexico/family/juarezcartel.html"]},{"id":"1997-blancornelas-ambush-tijuana","date":"1997-11-27","precision":"day","title":"Zeta editor Jesús Blancornelas ambushed by Tijuana Cartel gunmen","summary":"On the morning of November 27, 1997, gunmen led by Arellano Félix enforcer David Barrón Corona ambushed the car of Jesús Blancornelas, co-founder of the Tijuana weekly Zeta, after the magazine published a photo of Ramón Arellano Félix and named cartel hitmen. Blancornelas was hit four times but survived; his bodyguard Luis Valero Elizalde was killed, as was Barrón, struck by a comrade's bullet.","impact":"The attack made Blancornelas an international symbol of the press under cartel siege and exposed the San Diego Logan Heights gang pipeline through which the Tijuana Cartel recruited killers.","state":"BCN","city":"Tijuana","lat":32.5149,"lng":-117.0382,"cartels":["tijuana"],"figures":["Jesús Blancornelas","David Barrón Corona","Luis Valero Elizalde"],"type":"attack","importance":4,"confidence":"high","sources":["https://ifex.org/journalist-j-jesus-blancornelas-shot/","https://cpj.org/reports/2004/11/tijuana/","https://en.wikipedia.org/wiki/Jes%C3%BAs_Blancornelas"]},{"id":"1998-carrillo-olea-morelos-resigns","date":"1998-05-15","precision":"day","title":"Morelos governor Carrillo Olea quits amid narco-police scandal","summary":"On May 15, 1998, Jorge Carrillo Olea, a retired general and former national security chief, requested indefinite leave as governor of Morelos, ending his term as the opposition-controlled state congress moved toward impeachment. The crisis erupted after his anti-kidnapping police chief Armando Martínez Salgado was caught dumping a victim's body on a Veracruz highway and his top justice officials were implicated in kidnapping, torture and protection of Juárez Cartel traffickers who had made Cuernavaca a refuge; PRI leader Jorge Morales Barud became substitute governor.","impact":"It was the first time in the decade that public pressure over organized-crime ties forced a sitting governor from office, and it showed how the Juárez Cartel had colonized a state security apparatus far from the border.","state":"MOR","city":"Cuernavaca","lat":18.9242,"lng":-99.2216,"cartels":["juarez","government"],"figures":["Jorge Carrillo Olea","Armando Martínez Salgado"],"type":"corruption","importance":3,"confidence":"high","sources":["https://www.washingtonpost.com/archive/politics/1998/03/29/corrupt-from-the-top/5d70e8a2-54ef-4604-99dc-bab11afde817/","https://www.jornada.com.mx/1998/05/17/morelos.html","https://en.wikipedia.org/wiki/Jorge_Carrillo_Olea"]},{"id":"1998-operation-casablanca","date":"1998-05-18","precision":"day","title":"Operation Casablanca exposes cartel laundering through Mexican banks","summary":"On May 18, 1998, the US Treasury and Justice departments announced Operation Casablanca, a Customs undercover sting begun in November 1995 and run from Los Angeles that lured Mexican bankers to the US. It produced more than 140 arrests (112 earlier plus 30 that weekend, including 14 Mexican bankers and Juárez and Cali cartel money managers), about $35 million seized with some $110 million more targeted in accounts, 26 bankers charged, and indictments of three Mexican banks (Bancomer, Serfin and Confía), with officials of 12 of Mexico's 19 largest banks implicated. Mexico had not been informed and protested the covert operation on its soil.","impact":"The largest money-laundering case to date proved the Mexican financial system's role in cartel finances and caused a diplomatic crisis over US unilateralism that shaped later cooperation rules.","state":"US","city":"Los Angeles, California","lat":34.0522,"lng":-118.2437,"cartels":["juarez","us_government","other"],"figures":["Robert Rubin","Janet Reno"],"type":"policy","importance":4,"confidence":"high","sources":["https://home.treasury.gov/news/press-releases/rr2452","https://1997-2001.state.gov/global/narcotics_law/1998_narc_report/major/Mexico.html","https://irp.fas.org/news/1998/05/wwwhm526.html"]},{"id":"1998-amezcua-brothers-arrested","date":"1998-06-01","precision":"day","title":"Amezcua brothers, 'kings of methamphetamine', arrested in Guadalajara","summary":"On June 1, 1998, FEADS agents arrested Jesús and Luis Amezcua Contreras in Guadalajara; their brother Adán had been detained in Colima in November 1997. The Colima Cartel they ran was described by the DEA as the largest methamphetamine and precursor-chemical trafficking organization in the world, importing ephedrine from Asia and supplying labs in California.","impact":"The arrests ended the first generation of Mexican methamphetamine cartels, but the trade passed to Sinaloa and Michoacán groups that industrialized it in the 2000s.","state":"JAL","city":"Guadalajara","lat":20.6597,"lng":-103.3496,"cartels":["colima","government"],"figures":["Jesús Amezcua Contreras","Luis Amezcua Contreras","Adán Amezcua Contreras"],"type":"capture","importance":4,"confidence":"high","sources":["https://www.deseret.com/1998/6/3/19383721/mexico-arrests-drug-ring-brothers-wanted-in-u-s/","https://en.wikipedia.org/wiki/Luis_Amezcua_Contreras","https://www.pbs.org/wgbh/pages/frontline/shows/mexico/etc/amezcua.html"]},{"id":"1998-ensenada-el-sauzal-massacre","date":"1998-09-17","precision":"day","title":"El Sauzal massacre: 19 killed near Ensenada","summary":"Around 4:30 a.m. on September 17, 1998, gunmen entered a ranch in El Sauzal de Rodríguez, outside Ensenada, pulled members of three families from their beds, lined them up against a wall and shot 19 people dead, among them children and a pregnant woman; two children survived by playing dead. The target, local trafficker Fermín Castro, was gravely wounded. Authorities attributed the killing to the Arellano Félix organization over drug debts.","impact":"The worst cartel massacre in Mexico to that date broke the informal taboo on killing families and children and became the emblem of Tijuana Cartel savagery.","state":"BCN","city":"El Sauzal, Ensenada","lat":31.8923,"lng":-116.6889,"cartels":["tijuana"],"figures":["Fermín Castro","Ramón Arellano Félix"],"type":"massacre","importance":5,"confidence":"high","sources":["https://www.cbsnews.com/news/19-dead-in-mexico-massacre","https://www.foxnews.com/story/baja-california-village-remembers-massacre-by-drug-kingpins","https://www.jornada.com.mx/1998/09/27/mas-masacre.html"]},{"id":"1999-los-zetas-founded","date":"1999-01-01","precision":"year","title":"Osiel Cárdenas founds Los Zetas with army deserter Guzmán Decena","summary":"During 1999, Osiel Cárdenas Guillén organized a personal guard of army deserters led by Lt. Arturo Guzmán Decena, 'Z-1', who had left the elite GAFE special forces in 1997 and recruited some 30 comrades trained in counterinsurgency tactics. The group, named for Guzmán Decena's federal police radio code, became the Gulf Cartel's armed wing; some accounts date its beginnings to 1997.","impact":"Los Zetas introduced military tactics, weaponry and terror into Mexican trafficking, transformed the Gulf Cartel into a territorial army, and later split off to become one of the most violent cartels in the country.","state":"TAM","city":"Matamoros","lat":25.869,"lng":-97.5027,"cartels":["zetas","gulf"],"figures":["Osiel Cárdenas Guillén","Arturo Guzmán Decena"],"type":"formation","importance":5,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Los_Zetas","https://insightcrime.org/mexico-organized-crime-news/osiel-cardenas-guillen/"]},{"id":"1999-villanueva-quintana-roo-governor-flees","date":"1999-03-28","precision":"day","title":"Quintana Roo governor Mario Villanueva flees drug charges","summary":"On the night of March 27–28, 1999, Mario Villanueva Madrid, governor of Quintana Roo, vanished from Chetumal about a week before his term and immunity ended on April 5, after federal prosecutors accused him of using state police to protect Juárez Cartel cocaine shipments through Cancún run by Alcides Ramón Magaña, 'El Metro'. He was captured near Cancún on May 24, 2001 and extradited to the United States on May 8, 2010, where he pleaded guilty in 2012 to laundering cartel bribes.","impact":"The first sitting governor to become a drug fugitive confirmed the Caribbean route's importance after the Colombian shift and showed how a cartel could capture an entire state government.","state":"ROO","city":"Chetumal","lat":18.5001,"lng":-88.2961,"cartels":["juarez","government"],"figures":["Mario Villanueva Madrid","Alcides Ramón Magaña"],"type":"corruption","importance":4,"confidence":"medium","sources":["https://www.deseret.com/2001/5/25/19588052/mexico-arrests-an-ex-governor-in-drug-probe/","https://www.infobae.com/mexico-2/2019/09/20/mario-villanueva-madrid-el-primer-narcogobernador-que-enfrento-a-la-justicia/","https://www.justice.gov/archive/usao/nys/pressreleases/August12/villanuevamadridplea.html"]},{"id":"1999-osiel-cardenas-kills-chava-gomez","date":"1999-07-01","precision":"month","title":"Osiel Cárdenas has ally 'El Chava' Gómez killed, takes Gulf Cartel","summary":"In mid-1999, most accounts say July, Salvador Gómez Herrera, 'El Chava', who had shared control of the Gulf Cartel with Osiel Cárdenas Guillén since the arrests of García Ábrego and Malherbe, was shot dead after being lured to a meeting in the Matamoros area, reportedly by Arturo Guzmán Decena on Cárdenas' orders shortly after Gómez had served as godfather at the baptism of Cárdenas' daughter. The killing earned Cárdenas the nickname 'El Mata Amigos'.","impact":"Cárdenas emerged as sole leader of the Gulf Cartel, ending the three-year succession struggle and inaugurating the militarized era of the organization.","state":"TAM","city":"Matamoros","lat":25.869,"lng":-97.5027,"cartels":["gulf","zetas"],"figures":["Osiel Cárdenas Guillén","Salvador 'El Chava' Gómez Herrera","Arturo Guzmán Decena"],"type":"killing","importance":4,"confidence":"medium","sources":["https://insightcrime.org/mexico-organized-crime-news/osiel-cardenas-guillen/","https://en.wikipedia.org/wiki/Osiel_C%C3%A1rdenas_Guill%C3%A9n","https://en.wikipedia.org/wiki/Arturo_Guzm%C3%A1n_Decena"]},{"id":"1999-matamoros-standoff-dea-fbi","date":"1999-11-09","precision":"day","title":"Osiel Cárdenas holds DEA and FBI agents at gunpoint in Matamoros","summary":"On November 9, 1999, Osiel Cárdenas Guillén and about 15 gunmen in eight vehicles surrounded a Ford Bronco with diplomatic plates carrying DEA agent Joe DuBois, FBI agent Daniel Fuentes and a Mexican informant in Matamoros, demanding they hand over the informant. After a tense standoff in which the agents warned him of the consequences of killing US officers, Cárdenas let them go and told them never to return to his territory.","impact":"The confrontation made Cárdenas a priority US target with a $2 million reward, led to his 2000 indictment in Brownsville, and set in motion the campaign that ended with his 2003 capture and 2007 extradition.","state":"TAM","city":"Matamoros","lat":25.869,"lng":-97.5027,"cartels":["gulf","zetas","us_government"],"figures":["Osiel Cárdenas Guillén","Joe DuBois","Daniel Fuentes"],"type":"other","importance":4,"confidence":"high","sources":["https://www.dallasnews.com/news/2010/03/14/dea-agent-tells-details-of-now-infamous-1999-confrontation-with-mexican-drug-kingpin/","https://www.chron.com/news/houston-texas/article/DEA-agent-breaks-silence-on-standoff-with-cartel-1713234.php","https://en.wikipedia.org/wiki/1999_Matamoros_standoff"]},{"id":"1999-ciudad-juarez-narco-graves-fbi","date":"1999-11-29","precision":"day","title":"FBI and PGR dig for Juárez Cartel mass graves at La Campana ranch","summary":"On November 29, 1999, dozens of FBI agents joined Mexican federal police and soldiers excavating Rancho La Campana and other properties southwest of Ciudad Juárez after an informant claimed up to 100 victims of the Carrillo Fuentes organization, including 22 US citizens, were buried there. The joint dig, the largest US law-enforcement deployment on Mexican soil to that date, recovered nine bodies.","impact":"The operation publicized the scale of disappearances under the Juárez Cartel and tested a new level of binational cooperation, while its modest results and the political backlash foreshadowed later controversies over US agents in Mexico.","state":"CHH","city":"Ciudad Juárez","lat":31.6904,"lng":-106.4245,"cartels":["juarez","us_government","government"],"figures":["Vicente Carrillo Fuentes","Louis Freeh"],"type":"discovery","importance":4,"confidence":"high","sources":["https://www.washingtonpost.com/wp-srv/pmextra/nov99/30/graves.htm","https://www.cbsnews.com/news/fbi-director-tours-mass-graves/","https://www.npr.org/1999/11/30/1067244/mass-grave-site-excavation"]},{"id":"2000-kingpin-act-first-designations","date":"2000-06-01","precision":"day","title":"First Kingpin Act sanctions hit Arellano Félix, Carrillo Fuentes, Amezcua","summary":"President Bill Clinton made the first twelve designations under the Foreign Narcotics Kingpin Designation Act (signed December 3, 1999). Six of the twelve were Mexican: Benjamín and Ramón Arellano Félix (Tijuana), Vicente Carrillo Fuentes (Juárez), José de Jesús and Luis Ignacio Amezcua Contreras (Colima) and the imprisoned Rafael Caro Quintero; the designations froze their US assets and barred US persons from dealing with them.","impact":"Established the Treasury sanctions tool that would be used against every major Mexican organization for the next quarter century, and signalled which groups Washington saw as dominant at the start of the Fox era.","state":"US","city":"Washington, D.C.","lat":38.9072,"lng":-77.0369,"cartels":["us_government","tijuana","juarez","colima","guadalajara"],"figures":["Bill Clinton","Benjamín Arellano Félix","Ramón Arellano Félix","Vicente Carrillo Fuentes","José de Jesús Amezcua Contreras","Luis Ignacio Amezcua Contreras","Rafael Caro Quintero"],"type":"policy","importance":3,"confidence":"high","sources":["https://clintonwhitehouse3.archives.gov/WH/New/Europe-0005/factsheets/implementation-of-the-foreign-narcotics-kingpin-designation-act.html","https://en.wikipedia.org/wiki/Foreign_Narcotics_Kingpin_Designation_Act"]},{"id":"2000-fox-wins-presidency-ends-pri-rule","date":"2000-07-02","precision":"day","title":"Vicente Fox wins presidency, ending 71 years of PRI rule","summary":"PAN candidate Vicente Fox Quesada defeated the PRI's Francisco Labastida (about 42.5% to 36.1%) in the first opposition presidential victory since the Revolution. Fox took office on December 1, 2000, promising to modernize policing and attack corruption.","impact":"The end of one-party rule dismantled the centralized, PRI-mediated arrangements that had long regulated trafficking, contributing to the fragmentation and open competition among cartels that defined 2000-2006.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["government"],"figures":["Vicente Fox Quesada","Francisco Labastida Ochoa"],"type":"policy","importance":5,"confidence":"high","sources":["https://www.britannica.com/biography/Vicente-Fox","https://en.wikipedia.org/wiki/Presidency_of_Vicente_Fox"]},{"id":"2001-el-chapo-escapes-puente-grande","date":"2001-01-19","precision":"day","title":"El Chapo escapes Puente Grande maximum-security prison","summary":"Joaquín 'El Chapo' Guzmán walked out of the Puente Grande federal prison in Jalisco, officially hidden in a laundry cart pushed by guard Francisco Javier 'El Chito' Camberos Rivera, seven weeks into the Fox administration. Dozens of guards and officials were later charged or dismissed over a bribery scheme said to have cost millions of dollars.","impact":"Freed the man who would rebuild the Sinaloa Cartel into the Federation and exposed the depth of corruption inside Mexico's new maximum-security system; it became the founding scandal of the Fox security record.","state":"JAL","city":"Puente Grande (El Salto)","lat":20.5167,"lng":-103.1667,"cartels":["sinaloa"],"figures":["Joaquín 'El Chapo' Guzmán","Francisco Javier 'El Chito' Camberos Rivera"],"type":"escape","importance":5,"confidence":"high","sources":["https://www.pbs.org/wgbh/frontline/article/drug-kingpin-el-chapo-guzman-escapes-prison-for-a-second-time","https://www.cnn.com/world/joaqun-el-chapo-guzmn-fast-facts","https://en.wikipedia.org/wiki/Manhunt_of_Joaqu%C3%ADn_%22El_Chapo%22_Guzm%C3%A1n"]},{"id":"2001-mario-villanueva-arrested-cancun","date":"2001-05-24","precision":"day","title":"Fugitive ex-governor Mario Villanueva arrested near Cancún","summary":"Federal police arrested Mario Villanueva Madrid, governor of Quintana Roo from 1993 to 1999, at a vehicle checkpoint near Cancún after more than two years on the run (he had vanished on March 28, 1999). He was accused of taking payments of roughly $400,000-$500,000 per cocaine shipment to let the Juárez Cartel move drugs through the state; he was extradited to the US in May 2010, pleaded guilty to money laundering and was sentenced in June 2013 to 131 months (about 11 years).","impact":"The first former governor jailed for cartel protection, the case laid bare how the Juárez Cartel had captured the Caribbean corridor's state government and set a precedent for prosecuting high-level political complicity.","state":"ROO","city":"Cancún","lat":21.1619,"lng":-86.8515,"cartels":["juarez","government"],"figures":["Mario Villanueva Madrid"],"type":"corruption","importance":3,"confidence":"high","sources":["https://www.deseret.com/2001/5/25/19588052/mexico-arrests-an-ex-governor-in-drug-probe/","https://www.justice.gov/usao-sdny/pr/former-governor-mexican-state-sentenced-manhattan-federal-court-131-months-prison-money","https://www.justice.gov/archive/usao/nys/pressreleases/August12/villanuevamadridplea.html"]},{"id":"2001-el-metro-alcides-ramon-magana-arrested-villahermosa","date":"2001-06-12","precision":"day","title":"Juárez Cartel southeast boss 'El Metro' arrested in Villahermosa","summary":"Alcides Ramón Magaña, 'El Metro', a former federal police officer and onetime bodyguard of Amado Carrillo Fuentes who ran the Juárez Cartel's Cancún-based southeastern cell, was arrested by soldiers and federal agents in Villahermosa, Tabasco, after a six-month intelligence operation; he had been a fugitive for eight years and had undergone plastic surgery. Prosecutors said he had operated under the protection of Governor Mario Villanueva; he was sentenced in 2007 to 47 years.","impact":"Dismantled the Juárez Cartel's Caribbean cocaine hub built with state protection, opening Quintana Roo and the Gulf coast to the Gulf Cartel and the Zetas over the following years.","state":"TAB","city":"Villahermosa","lat":17.9892,"lng":-92.9475,"cartels":["juarez","government"],"figures":["Alcides Ramón Magaña","Mario Villanueva Madrid"],"type":"capture","importance":3,"confidence":"high","sources":["https://www.jornada.com.mx/2001/06/14/metro.html","https://archivo.eluniversal.com.mx/primera/6290.html","https://www.proceso.com.mx/nacional/2007/6/21/sentencia-de-47-anos-de-prision-ramon-alcides-magana-el-metro-47520.html"]},{"id":"2001-afi-created-replaces-federal-judicial-police","date":"2001-11-01","precision":"day","title":"Fox creates the AFI to replace the corrupt Federal Judicial Police","summary":"By presidential decree published in the Diario Oficial on November 1, 2001, the Agencia Federal de Investigación (AFI) was created inside the PGR to replace the Policía Judicial Federal, long compromised by cartel payoffs. Modeled on the FBI, the AFI was meant to professionalize federal investigations and vetting.","impact":"The Fox administration's flagship police reform; the AFI took part in key captures (Rosales Mendoza, Z-2) but was itself penetrated by the cartels, and was replaced by the Policía Federal Ministerial under a 2009 law, ceasing operations in 2012.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["government"],"figures":["Vicente Fox Quesada","Rafael Macedo de la Concha"],"type":"policy","importance":2,"confidence":"high","sources":["https://www.globalsecurity.org/intell/world/mexico/pjf.htm","https://es.wikipedia.org/wiki/Agencia_Federal_de_Investigaci%C3%B3n"]},{"id":"2001-miguel-caro-quintero-arrested-los-mochis","date":"2001-12-01","precision":"month","title":"Sonora Cartel chief Miguel Caro Quintero arrested in Los Mochis","summary":"Miguel Ángel Caro Quintero, who ran the Sonora Cartel's marijuana empire after his brother Rafael's 1985 imprisonment, was arrested by federal agents in Los Mochis, Sinaloa, in December 2001 (reports place the arrest around December 20). He served a Mexican sentence and was extradited to the United States only on February 25, 2009; he pleaded guilty in Denver in October 2009 and was sentenced in February 2010 to 17 years.","impact":"Removed the last major figure of the Caro Quintero family from active trafficking and ended the Sonora Cartel as an independent force; the seven-year wait for extradition illustrated the legal obstacles the 2005 Supreme Court ruling would later clear.","state":"SIN","city":"Los Mochis","lat":25.7903,"lng":-108.9859,"cartels":["sonora","government","us_government"],"figures":["Miguel Caro Quintero"],"type":"capture","importance":3,"confidence":"medium","sources":["https://www.justice.gov/archive/usao/co/news/2009/October09/10_23_09.html","https://en.wikipedia.org/wiki/Miguel_Caro_Quintero"]},{"id":"2002-sinaloa-federation-alianza-de-sangre-formed","date":"2002-01-01","precision":"year","title":"Sinaloa Federation forms: Chapo, Mayo, Beltrán Leyva, Coronel, El Azul","summary":"After his 2001 escape, Joaquín 'El Chapo' Guzmán held a series of meetings through 2002 with Ismael 'El Mayo' Zambada, Juan José 'El Azul' Esparragoza, the Beltrán Leyva brothers and Ignacio 'Nacho' Coronel that forged the alliance known as the Federation or 'Alianza de Sangre'. The Carrillo Fuentes organization of Juárez was part of the pact, and the alliance was cemented by intermarriage.","impact":"Created the most powerful trafficking coalition in Mexico, giving Sinaloa the manpower (the Beltrán Leyvas built its security apparatus) to launch offensives against the Gulf Cartel in Nuevo Laredo, the Arellano Félix organization in Tijuana and, from 2004, its former Juárez partners.","state":"SIN","city":"Culiacán","lat":24.8091,"lng":-107.394,"cartels":["sinaloa","beltran_leyva","juarez"],"figures":["Joaquín 'El Chapo' Guzmán","Ismael 'El Mayo' Zambada","Arturo Beltrán Leyva","Juan José 'El Azul' Esparragoza","Ignacio 'Nacho' Coronel","Vicente Carrillo Fuentes"],"type":"alliance","importance":5,"confidence":"medium","sources":["https://insightcrime.org/mexico-organized-crime-news/beltran-leyva-organization-profile/","https://insightcrime.org/investigations/how-the-beltran-leyva-sinaloa-cartel-feud-bloodied-mexico/"]},{"id":"2002-ramon-arellano-felix-killed-mazatlan","date":"2002-02-10","precision":"day","title":"Ramón Arellano Félix killed by police in Mazatlán during Carnival","summary":"Ramón Arellano Félix, enforcer-in-chief of the Tijuana Cartel and an FBI Ten Most Wanted fugitive since 1997, was shot dead after a traffic stop by Mazatlán municipal officer Ángel Antonio Arias Torres, whom he also killed, while reportedly in Sinaloa to hunt Ismael 'El Mayo' Zambada. A relative claimed and cremated the body before identification; DNA tests later confirmed it was Ramón.","impact":"Removed the Arellano Félix organization's most feared killer and, together with Benjamín's arrest a month later, broke the cartel's leadership at its peak, beginning the long decline of Tijuana and the rise of Sinaloa on the Baja frontier.","state":"SIN","city":"Mazatlán","lat":23.2494,"lng":-106.4111,"cartels":["tijuana","sinaloa","government"],"figures":["Ramón Arellano Félix","Ismael 'El Mayo' Zambada"],"type":"killing","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Ram%C3%B3n_Arellano_F%C3%A9lix","https://www.npr.org/2002/02/28/1138964/drug-lord"]},{"id":"2002-benjamin-arellano-felix-arrested-puebla","date":"2002-03-09","precision":"day","title":"Benjamín Arellano Félix, head of the Tijuana Cartel, arrested in Puebla","summary":"Mexican Army special forces, working with DEA and FBI intelligence that tracked his family, arrested Benjamín Arellano Félix at a house in the city of Puebla. He was the strategic boss of the Arellano Félix organization; he was extradited to the US in 2011 and sentenced in 2012 to 25 years.","impact":"The most important capture of the Fox era to that point, it decapitated the Tijuana Cartel a month after Ramón's death and left the organization to younger brothers Eduardo and Javier, inviting Sinaloa incursions into Baja California.","state":"PUE","city":"Puebla","lat":19.0414,"lng":-98.2063,"cartels":["tijuana","government","us_government"],"figures":["Benjamín Arellano Félix"],"type":"capture","importance":4,"confidence":"high","sources":["https://www.dea.gov/sites/default/files/pubs/pressrel/pr030902.html","https://www.justice.gov/archive/opa/pr/2002/March/02_ag_135.htm"]},{"id":"2002-el-chacho-abducted-killed-zetas-nuevo-laredo","date":"2002-05-13","precision":"day","title":"Zetas abduct and kill Nuevo Laredo boss 'El Chacho', taking the plaza","summary":"About twenty Zetas led by Víctor Manuel Vázquez Mireles, acting on a tip from police chief Arturo Pedroza Aguirre, seized Dionisio Román García Sánchez, 'El Chacho', leader of the Nuevo Laredo smuggling group Los Chachos, at his home in Monterrey together with four of his gunmen, one of whom was killed. He was taken to Tamaulipas and found tortured and killed the same day in Río Bravo; Zetas founder Raúl Alberto Trejo Benavides, 'El Alvin', was mortally wounded in the operation and his death was staged as a suicide in a Matamoros hotel.","impact":"Consolidated Gulf Cartel and Zetas control over Nuevo Laredo, the busiest US-Mexico commercial crossing, and demonstrated the paramilitary methods that would make the Zetas the model for cartel enforcement wings.","state":"NLE","city":"Monterrey","lat":25.6866,"lng":-100.3161,"cartels":["zetas","gulf","other"],"figures":["Dionisio Román García Sánchez","Osiel Cárdenas Guillén","Raúl Alberto Trejo Benavides","Víctor Manuel Vázquez Mireles"],"type":"killing","importance":3,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Victor_Manuel_Vasquez_Mireles","https://www.borderlandbeat.com/2019/10/el-alvin-zetas-founder-whose-death-was.html"]},{"id":"2002-z1-arturo-guzman-decena-killed-matamoros","date":"2002-11-21","precision":"day","title":"Zetas founder Arturo Guzmán Decena 'Z-1' killed by army in Matamoros","summary":"Arturo Guzmán Decena, the former GAFE special forces lieutenant who founded Los Zetas as Osiel Cárdenas's bodyguard corps and whose radio call sign gave the group its name, was shot dead by soldiers in a Matamoros restaurant after a neighbor reported his gunmen blocking the streets. Command passed to Rogelio González Pizaña 'Z-2' and later Heriberto Lazcano 'Z-3'.","impact":"The first leadership loss for the Zetas; rather than weakening them, it accelerated the group's transformation from bodyguards into an autonomous paramilitary force that would soon expand across eastern Mexico.","state":"TAM","city":"Matamoros","lat":25.869,"lng":-97.5027,"cartels":["zetas","gulf","government"],"figures":["Arturo Guzmán Decena","Osiel Cárdenas Guillén"],"type":"killing","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Arturo_Guzm%C3%A1n_Decena","https://www.borderlandbeat.com/2024/01/throwback-series-newly-uncovered.html"]},{"id":"2003-zetas-expand-beyond-tamaulipas-michoacan-veracruz-guerrero","date":"2003-01-01","precision":"year","title":"Zetas expand beyond Tamaulipas into Michoacán, Veracruz and Guerrero","summary":"Allied with Carlos Rosales Mendoza against the Valencia cartel, the Zetas became the dominant power in Michoacán by 2003, prized for the Pacific port of Lázaro Cárdenas, and pushed the Gulf Cartel's reach down the Gulf coast (Veracruz, Tabasco, Yucatán, Quintana Roo) and into Guerrero and Oaxaca through 2004-2006, running training camps and recruiting ex-Kaibiles. Local resentment of their extortion and methamphetamine trade later fueled La Familia's rebellion.","impact":"Turned a regional border cartel into a national one and exported military-style violence to states that had been peripheral to trafficking, setting up the Acapulco and Michoacán conflicts and the Zetas' eventual break with the Gulf Cartel.","state":"MIC","city":"Lázaro Cárdenas","lat":17.9583,"lng":-102.2,"cartels":["zetas","gulf","milenio","familia_michoacana"],"figures":["Heriberto Lazcano Lazcano","Carlos Rosales Mendoza","Osiel Cárdenas Guillén"],"type":"other","importance":4,"confidence":"medium","sources":["https://www.fpri.org/article/2008/05/los-zetas-the-ruthless-army-spawned-by-a-mexican-drug-cartel/","https://insightcrime.org/mexico-organized-crime-news/familia-michoacana-mexico-profile/"]},{"id":"2003-osiel-cardenas-captured-matamoros","date":"2003-03-14","precision":"day","title":"Gulf Cartel boss Osiel Cárdenas captured after Matamoros firefight","summary":"In a secret months-long army operation known only to President Fox, the defense secretary and the attorney general, special forces raided several Matamoros residences and captured Osiel Cárdenas Guillén after a gun battle with Gulf Cartel and Zetas gunmen. Wanted by the FBI and DEA with a $2 million US reward since his 1999 confrontation with US agents, he was held at La Palma, from where he continued to direct the cartel until his January 2007 extradition.","impact":"The arrest left the Gulf Cartel under a weakened, prison-bound leadership and prompted the Sinaloa Federation to move on Nuevo Laredo, igniting the border war; it also elevated the Zetas within the organization.","state":"TAM","city":"Matamoros","lat":25.869,"lng":-97.5027,"cartels":["gulf","zetas","government"],"figures":["Osiel Cárdenas Guillén","Vicente Fox Quesada","Rafael Macedo de la Concha"],"type":"capture","importance":5,"confidence":"high","sources":["https://www.washingtonpost.com/archive/politics/2003/03/15/mexico-seizes-reputed-drug-lord/79684e2b-67b1-42ad-8204-00ba9509a88c/","https://insightcrime.org/mexico-organized-crime-news/osiel-cardenas-guillen/","https://www.sfgate.com/news/article/reputed-drug-lord-arrested-after-gunfight-2628653.php"]},{"id":"2003-nuevo-laredo-war-begins-sinaloa-vs-zetas","date":"2003-08-01","precision":"month","title":"Nuevo Laredo war begins: Sinaloa's Los Negros vs Gulf Cartel's Zetas","summary":"Sensing weakness after Osiel Cárdenas's capture, the Sinaloa Federation sent gunmen under Edgar Valdez Villarreal 'La Barbie' (Los Negros, backed by the Beltrán Leyvas) to seize Nuevo Laredo from the Gulf Cartel. A 40-minute street firefight on August 1, 2003 in which the AFI clashed with Los Negros gunmen fighting the Zetas, leaving three dead, is conventionally cited as the open start of a war that ran until 2006-07 with grenade and rocket attacks and hundreds of dead.","impact":"Mexico's first sustained inter-cartel war of the democratic era: it introduced paramilitary tactics, mass police complicity and journalist intimidation to the border, prompted Operativo México Seguro, and ended with the Zetas holding the plaza.","state":"TAM","city":"Nuevo Laredo","lat":27.4763,"lng":-99.5163,"cartels":["sinaloa","beltran_leyva","gulf","zetas"],"figures":["Edgar Valdez Villarreal","Joaquín 'El Chapo' Guzmán","Arturo Beltrán Leyva","Heriberto Lazcano Lazcano"],"type":"battle","importance":5,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Sinaloa_Cartel%E2%80%93Gulf_Cartel_conflict","https://www.npr.org/2009/10/02/113388071/mexicos-ferocious-zetas-cartel-reigns-through-fear","https://www.texasmonthly.com/true-crime/borderline-insanity/"]},{"id":"2003-armando-valencia-milenio-cartel-arrested-guadalajara","date":"2003-08-15","precision":"day","title":"Milenio Cartel founder Armando Valencia Cornelio arrested near Guadalajara","summary":"Army special forces (GAFE) and the PGR captured Armando Valencia Cornelio, 'El Maradona', leader of the Michoacán-rooted Milenio (Valencia) Cartel and a DEA target since 1999, with several associates at a bar in Tlajomulco de Zúñiga in the Guadalajara metropolitan area. He was later sentenced to 47 and a half years; Luis Valencia Valencia and Óscar Nava Valencia took over the organization.","impact":"Weakened the Sinaloa-aligned Valencia network in Michoacán just as the Gulf Cartel and Zetas were pushing in with Carlos Rosales, and set the Milenio Cartel on the path of succession disputes that would later produce the CJNG.","state":"JAL","city":"Tlajomulco de Zúñiga","lat":20.4736,"lng":-103.4431,"cartels":["milenio","government"],"figures":["Armando Valencia Cornelio","Óscar Nava Valencia","Luis Valencia Valencia"],"type":"capture","importance":3,"confidence":"high","sources":["https://www.milenio.com/policia/quien-es-armando-valencia-cornelio-fundador-cartel-milenio","https://justiceinmexico.org/wp-content/uploads/2018/03/180319-Policy_Brief-CJNG.pdf","https://en.wikipedia.org/wiki/Milenio_Cartel"]},{"id":"2004-apatzingan-prison-raid-gulf-zetas-free-25","date":"2004-01-05","precision":"day","title":"Gulf Cartel commando storms Apatzingán prison, frees 25 inmates","summary":"Before dawn some 30 to 40 gunmen in a convoy of 10 to 15 vehicles with flashing lights, wearing police and army uniforms, seized the Apatzingán state prison in Michoacán and freed 25 prisoners in five to seven minutes (early reports said up to 29, several of whom were recaptured); one inmate was shot dead. Authorities blamed the Gulf Cartel and later identified Carlos Rosales Mendoza, Osiel Cárdenas's ally, as the organizer.","impact":"The most brazen jailbreak of the era showed the Zetas-trained Gulf network could overwhelm state institutions in Michoacán's Tierra Caliente and prefigured plots to free Cárdenas himself, prompting the federal takeover of La Palma in 2005.","state":"MIC","city":"Apatzingán","lat":19.0886,"lng":-102.3506,"cartels":["gulf","zetas"],"figures":["Carlos Rosales Mendoza","Osiel Cárdenas Guillén"],"type":"escape","importance":3,"confidence":"medium","sources":["https://www.aljazeera.com/amp/news/2004/1/6/drug-cartel-pulls-off-mexican-jailbreak","https://www.milenio.com/policia/osiel-cardenas-guillen-tisico-planeo-liberacion"]},{"id":"2004-house-of-death-ciudad-juarez-bodies-exhumed","date":"2004-01-23","precision":"day","title":"'House of Death' mass grave uncovered in Ciudad Juárez","summary":"Mexican authorities began digging at 3633 Calle Parsioneros in Ciudad Juárez and eventually recovered a dozen bodies of people tortured and killed between August 2003 and January 2004 by a Juárez Cartel cell under Heriberto Santillán Tabares, a lieutenant of Vicente Carrillo Fuentes. The killings had been witnessed and in part facilitated by Guillermo Ramírez Peyro, 'Lalo', a paid US ICE informant; Santillán had been lured to El Paso and arrested on January 15, 2004, and later took a 25-year plea deal.","impact":"A binational scandal that exposed how US agencies tolerated informant participation in cartel murders, and an early sign of the Juárez Cartel's routine use of clandestine graves in the city that would become the war's epicenter.","state":"CHH","city":"Ciudad Juárez","lat":31.6904,"lng":-106.4245,"cartels":["juarez","us_government"],"figures":["Guillermo Ramírez Peyro","Heriberto Santillán Tabares","Vicente Carrillo Fuentes"],"type":"discovery","importance":3,"confidence":"medium","sources":["https://mg.co.za/news/south-africa/2006-12-03-the-house-of-death/","https://reason.com/2008/09/30/the-house-of-death/"]},{"id":"2004-francisco-ortiz-franco-zeta-editor-killed-tijuana","date":"2004-06-22","precision":"day","title":"Zeta weekly co-founder Francisco Ortiz Franco murdered in Tijuana","summary":"Masked gunmen shot Francisco Javier Ortiz Franco, co-founder and editor of the investigative weekly Zeta, four times in the head and neck as he sat in his car with his two children, two blocks from state police headquarters in Tijuana. Federal investigators attributed the killing to the Arellano Félix organization over his reporting on the cartel, naming Arturo Villarreal Albarrán 'El Nalgón' and Jorge Briceño 'El Cholo' as suspects.","impact":"The highest-profile attack on the press in the Fox years, it confirmed the Tijuana Cartel's persistence after the 2002 leadership losses and became an emblem of impunity cited by CPJ and RSF as violence against journalists escalated.","state":"BCN","city":"Tijuana","lat":32.5149,"lng":-117.0382,"cartels":["tijuana"],"figures":["Francisco Ortiz Franco"],"type":"killing","importance":3,"confidence":"high","sources":["https://www.washingtonpost.com/archive/politics/2004/06/23/gunmen-kill-editor-of-tijuana-newspaper/633f1dc4-640e-4ec6-84de-f30c884dd157/","https://cpj.org/2006/06/cpj-urges-revival-of-probe-into-murder-of-zeta-edi/"]},{"id":"2004-rodolfo-carrillo-fuentes-killed-culiacan","date":"2004-09-11","precision":"day","title":"Rodolfo Carrillo Fuentes killed in Culiacán, starting Sinaloa-Juárez war","summary":"Rodolfo Carrillo Fuentes, 'El Niño de Oro', younger brother of Juárez Cartel boss Vicente Carrillo Fuentes, and his wife Giovanna Quevedo Gastélum were gunned down by a squad of sicarios in the parking lot of the Cinépolis mall in Culiacán despite a state police escort, whose commander was badly wounded. Testimony at the 2018-19 US trial of Joaquín 'El Chapo' Guzmán, by Jesús 'El Rey' Zambada, said Guzmán ordered the hit after a falling-out with Rodolfo.","impact":"Shattered the Federation's pact with the Carrillo Fuentes organization and launched the Sinaloa-Juárez war; Vicente Carrillo retaliated by having Chapo's brother killed in prison, and the feud culminated in the 2008-2012 bloodbath in Ciudad Juárez.","state":"SIN","city":"Culiacán","lat":24.8091,"lng":-107.394,"cartels":["sinaloa","juarez"],"figures":["Rodolfo Carrillo Fuentes","Vicente Carrillo Fuentes","Joaquín 'El Chapo' Guzmán"],"type":"killing","importance":4,"confidence":"high","sources":["https://www.borderlandbeat.com/2018/11/el-chapo-trial-chapo-had-rodolfo.html","https://www.borderlandbeat.com/2013/09/the-juarez-cartel-sinks-into-oblivion.html"]},{"id":"2004-carlos-rosales-el-tisico-captured-morelia","date":"2004-10-24","precision":"day","title":"Gulf Cartel's Michoacán chief Carlos Rosales 'El Tísico' captured","summary":"Some 150 army special forces (GAFE) arrested Carlos Rosales Mendoza, Osiel Cárdenas's compadre and the Gulf Cartel's man in Michoacán, at a residence in Morelia (reports give October 24 or 25, 2004). He was accused of organizing the January Apatzingán jailbreak and of training some 50 gunmen for a similar assault to free Cárdenas from La Palma.","impact":"Removed the local patron who had brought the Zetas into Michoacán; his lieutenants Nazario Moreno and José de Jesús Méndez soon turned the network into La Familia Michoacana and against their Zetas mentors.","state":"MIC","city":"Morelia","lat":19.706,"lng":-101.195,"cartels":["gulf","zetas","familia_michoacana","government"],"figures":["Carlos Rosales Mendoza","Osiel Cárdenas Guillén"],"type":"capture","importance":3,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Carlos_Rosales_Mendoza","https://www.milenio.com/policia/osiel-cardenas-guillen-tisico-planeo-liberacion"]},{"id":"2004-z2-rogelio-gonzalez-pizana-captured-matamoros","date":"2004-10-29","precision":"day","title":"Zetas leader Rogelio González Pizaña 'Z-2' captured after Matamoros battle","summary":"Federal agents and the Policía Federal Preventiva arrested Rogelio 'El Kelín' González Pizaña, successor to Z-1 as head of Los Zetas, in a pre-dawn raid on the La Covacha strip club in Matamoros after a gun battle in which he threw grenades and was shot in the torso; two suspects and one federal agent were reported killed (some accounts date the raid to the night of October 28). Heriberto Lazcano, 'Z-3', took command of the group.","impact":"Put the Zetas under Lazcano, who steered them toward independence from the Gulf Cartel and nationwide expansion, making the arrest a turning point in the group's evolution rather than a setback.","state":"TAM","city":"Matamoros","lat":25.869,"lng":-97.5027,"cartels":["zetas","gulf","government"],"figures":["Rogelio González Pizaña","Heriberto Lazcano Lazcano"],"type":"capture","importance":3,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Rogelio_Gonz%C3%A1lez_Piza%C3%B1a","https://www.borderlandbeat.com/2014/09/wanted-in-usel-kelin-z2reported.html"]},{"id":"2004-cancun-afi-agents-killed-zetas","date":"2004-11-25","precision":"day","title":"Zetas kill three AFI agents in Cancún; PGR delegate arrested for complicity","summary":"On November 25, 2004 nine bodies were found near Cancún's airport, among them AFI agents Luis Octavio Guzmán Ruiz, Roberto Alcántara Pérez and Fernando Pérez Nájera, who had been abducted and executed; with three earlier killings the toll for the week reached twelve, and PGR sources attributed the wave to a Zetas hit squad from Tamaulipas. In a joint army-AFI sweep on December 3 about two dozen people were detained, among them the former PGR regional delegate Miguel Ángel Hernández Castellón and the regional AFI coordinator Armando Villalobos, for protecting traffickers.","impact":"Showed the Gulf Cartel and Zetas had seized the Caribbean corridor vacated by the Juárez Cartel and that the new AFI itself was compromised, foreshadowing the Zetas' entrenchment in Quintana Roo.","state":"ROO","city":"Cancún","lat":21.1619,"lng":-86.8515,"cartels":["zetas","gulf","government"],"figures":["Miguel Ángel Hernández Castellón","Armando Villalobos"],"type":"killing","importance":3,"confidence":"medium","sources":["https://archivo.eluniversal.com.mx/estados/55594.html","https://archivo.eluniversal.com.mx/nacion/118773.html","https://www.proceso.com.mx/nacional/2004/11/26/ejecutan-12-personas-en-cancun-62386.html"]},{"id":"2004-arturo-guzman-loera-el-pollo-killed-la-palma","date":"2004-12-31","precision":"day","title":"El Chapo's brother 'El Pollo' shot dead inside La Palma prison","summary":"Arturo Guzmán Loera, 'El Pollo', brother and financial operator of Joaquín 'El Chapo' Guzmán, was shot seven times with a 9mm pistol in the lawyers' visiting area of the La Palma (Altiplano) maximum-security prison by fellow inmate José Ramírez Villanueva. Investigators tied the hit to the Juárez Cartel's revenge for Rodolfo Carrillo Fuentes; the killer was sentenced to 42 years in 2008.","impact":"Proved that cartel wars now reached inside Mexico's most secure prison, where Osiel Cárdenas and Benjamín Arellano Félix were also held, and triggered the January 2005 military takeover of La Palma.","state":"MEX","city":"Almoloya de Juárez","lat":19.3706,"lng":-99.759,"cartels":["sinaloa","juarez"],"figures":["Arturo Guzmán Loera","José Ramírez Villanueva","Joaquín 'El Chapo' Guzmán"],"type":"killing","importance":4,"confidence":"high","sources":["https://www.proceso.com.mx/nacional/2008/7/3/cuarenta-dos-anos-de-prision-al-asesino-de-el-pollo-guzman-56165.html","https://www.jornada.com.mx/2008/07/03/index.php?section=politica&article=008n2pol","https://www.prisonlegalnews.org/news/2005/dec/15/mexican-prisons-in-crisis-cartels-murder-prisoners-and-guards/"]},{"id":"2005-acapulco-war-beltran-leyva-pelones-vs-zetas","date":"2005-01-01","precision":"year","title":"Acapulco war: Beltrán Leyva's Los Pelones battle the Zetas for Guerrero","summary":"Following incursions that began in 2004, the Beltrán Leyva wing of the Sinaloa Federation, with its Guerrero enforcer gang Los Pelones under Edgar Valdez 'La Barbie', fought the Gulf Cartel's Zetas for Acapulco's docks, tourist drug market and the coastal cocaine landing zones through 2005-2006. Shootouts with federal forces in January 2006, decapitations of police in April 2006 and the first narco-execution videos marked the conflict.","impact":"Brought cartel warfare to Mexico's flagship resort and to Guerrero's poppy-growing hinterland, beginning the state's transformation into one of the country's most violent and fragmented criminal landscapes.","state":"GRO","city":"Acapulco","lat":16.8531,"lng":-99.8237,"cartels":["beltran_leyva","sinaloa","zetas","gulf"],"figures":["Arturo Beltrán Leyva","Edgar Valdez Villarreal","Heriberto Lazcano Lazcano"],"type":"battle","importance":4,"confidence":"medium","sources":["https://www.crisisgroup.org/rpt/latin-america-caribbean/mexico/080-mexicos-everyday-war-guerrero-and-trials-peace","https://www.wola.org/sites/default/files/downloadable/Mexico/past/state_of_siege_06.06.pdf","https://en.wikipedia.org/wiki/Los_Pelones"]},{"id":"2005-army-takes-control-la-palma-prison","date":"2005-01-14","precision":"day","title":"Army seizes control of La Palma prison to break capos' command from inside","summary":"More than 750 soldiers with armored vehicles and a helicopter raided La Palma after the Guzmán Loera killing and intelligence that the Zetas were plotting to free imprisoned bosses. Inmates including Osiel Cárdenas, who had been running the Gulf Cartel from his cell, were isolated or transferred; 105 of 145 guards subsequently failed polygraph and drug tests.","impact":"Marked the Fox government's admission that the federal prison system was under cartel control and began the practice of military intervention in penitentiaries; it also fed the push to extradite kingpins to the United States.","state":"MEX","city":"Almoloya de Juárez","lat":19.3706,"lng":-99.759,"cartels":["government","gulf","zetas","sinaloa"],"figures":["Osiel Cárdenas Guillén","Vicente Fox Quesada"],"type":"policy","importance":3,"confidence":"high","sources":["https://www.prisonlegalnews.org/news/2005/dec/15/mexican-prisons-in-crisis-cartels-murder-prisoners-and-guards/"]},{"id":"2005-matamoros-prison-employees-killed-zetas-reprisal","date":"2005-01-20","precision":"day","title":"Six Matamoros prison workers abducted and executed in Zetas reprisal","summary":"Six days after the La Palma raid, six employees of the CERESO 3 prison in Matamoros who had left work around 6 a.m. were intercepted, abducted, and found the same day blindfolded, bound and shot dead inside a bullet-riddled white Ford Explorer half a mile from the prison. The killings were read as the Gulf Cartel and Zetas' answer to the federal crackdown on cartel control inside prisons.","impact":"An early instance of cartels retaliating directly against the state for security operations, establishing a pattern of intimidation of prison and police personnel that spread nationwide after 2006.","state":"TAM","city":"Matamoros","lat":25.869,"lng":-97.5027,"cartels":["zetas","gulf","government"],"figures":["Osiel Cárdenas Guillén"],"type":"attack","importance":2,"confidence":"high","sources":["https://www.prisonlegalnews.org/news/2005/dec/15/mexican-prisons-in-crisis-cartels-murder-prisoners-and-guards/"]},{"id":"2005-alejandro-dominguez-nuevo-laredo-police-chief-killed","date":"2005-06-08","precision":"day","title":"Nuevo Laredo police chief Alejandro Domínguez killed hours after taking office","summary":"Alejandro Domínguez Coello, a businessman who volunteered for the police chief job nobody else wanted, was sworn in and about six hours later was hit by more than 30 rounds fired from a vehicle as he got into his truck. Hitmen believed to belong to the Zetas were blamed amid the Gulf-Sinaloa war.","impact":"The killing made Nuevo Laredo the symbol of state collapse on the border, prompted Fox to launch Operativo México Seguro within days, and led to the disarming of the entire municipal police force.","state":"TAM","city":"Nuevo Laredo","lat":27.4763,"lng":-99.5163,"cartels":["zetas","gulf","government"],"figures":["Alejandro Domínguez Coello"],"type":"killing","importance":4,"confidence":"high","sources":["https://www.npr.org/2005/06/09/4696658/mexican-police-chief-shot-and-killed","https://www.chron.com/news/houston-texas/article/nuevo-laredo-police-chief-killed-on-street-1688300.php"]},{"id":"2005-operativo-mexico-seguro-launched","date":"2005-06-11","precision":"day","title":"Fox launches Operativo México Seguro, sending federal forces to Nuevo Laredo","summary":"Three days after the Domínguez killing, President Fox's government announced Operativo México Seguro, a joint deployment of the army, navy, federal police and PGR to Nuevo Laredo, Reynosa and Matamoros; hundreds of federal agents arrived in Nuevo Laredo on June 13, where they exchanged fire with local police, and the entire municipal police was suspended for vetting. The operation was later extended to Sinaloa (Culiacán, Navolato, Mazatlán) and Baja California (Tijuana, Mexicali).","impact":"The Fox administration's largest anti-cartel deployment and the direct precursor of Calderón's joint operations; it failed to halt the Nuevo Laredo war, whose death toll rose through 2005-2006.","state":"TAM","city":"Nuevo Laredo","lat":27.4763,"lng":-99.5163,"cartels":["government","zetas","gulf","sinaloa"],"figures":["Vicente Fox Quesada"],"type":"policy","importance":4,"confidence":"high","sources":["https://archivo.eluniversal.com.mx/notas/288181.html","https://www.proceso.com.mx/94872/mexico-seguro-un-ensayo-sangriento"]},{"id":"2005-supreme-court-allows-extradition-life-sentences","date":"2005-11-29","precision":"day","title":"Supreme Court lifts ban on extraditing suspects who face life sentences","summary":"Mexico's Supreme Court ruled that life imprisonment is not an 'unusual penalty' under Article 22 of the Constitution, reversing its 2001 decision that had blocked extradition of fugitives facing life terms in the United States unless Washington guaranteed a lesser sentence.","impact":"Removed the main legal barrier to sending cartel leaders to US courts, enabling the record extraditions of 2007 onward (Osiel Cárdenas among the first) that became a pillar of the Calderón strategy and US-Mexico cooperation.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["government","us_government"],"figures":[],"type":"policy","importance":4,"confidence":"high","sources":["http://opiniojuris.org/2005/12/02/is-life-imprisonment-an-unusual-punishment/","https://foia.state.gov/DOCUMENTS/1-FY2013/F-2009-05322/DOC_0C17576217/C17576217.pdf"]},{"id":"2005-la-barbie-zetas-interrogation-execution-video","date":"2005-12-01","precision":"day","title":"First narco execution video: La Barbie interrogates and kills captured Zetas","summary":"A video sent to The Dallas Morning News on December 1, 2005 showed four bound and beaten Zetas, part of a group of nine seized at a nightclub in Zihuatanejo and taken to Acapulco, being interrogated about the group's structure and police protection before one was shot in the head. Prosecutors, citing a captured Zetas commander's testimony, attributed the recording to Edgar Valdez Villarreal 'La Barbie' of the Beltrán Leyva-Sinaloa side of the Acapulco war.","impact":"Inaugurated the use of filmed torture and execution as cartel propaganda and psychological warfare, a practice that spread to all groups and became a defining feature of the coming war.","state":"GRO","city":"Acapulco","lat":16.8531,"lng":-99.8237,"cartels":["beltran_leyva","sinaloa","zetas"],"figures":["Edgar Valdez Villarreal"],"type":"other","importance":3,"confidence":"high","sources":["https://www.rollingstone.com/culture/culture-news/an-american-drug-lord-in-acapulco-243702/","https://www.borderlandbeat.com/2010/09/they-accused-la-barbie-of-hunting-zetas.html"]},{"id":"2006-el-manana-newspaper-attacked-nuevo-laredo","date":"2006-02-06","precision":"day","title":"Gunmen storm El Mañana newspaper in Nuevo Laredo with rifles and a grenade","summary":"Around 8 p.m. masked attackers fired assault rifles and threw a grenade into the newsroom of El Mañana, Nuevo Laredo's main daily, hitting reporter Jaime Orozco five times and leaving him paralyzed, and wrecking the building. The paper had already lost its editor Roberto Mora, stabbed to death in March 2004, and had largely stopped covering organized crime.","impact":"Pushed the federal government to finally create the special prosecutor for crimes against journalists (FEADP) on February 15, 2006, nine days later, and cemented the border press blackout that let the cartels operate unreported.","state":"TAM","city":"Nuevo Laredo","lat":27.4763,"lng":-99.5163,"cartels":["zetas","gulf","sinaloa"],"figures":["Jaime Orozco"],"type":"attack","importance":3,"confidence":"high","sources":["https://cpj.org/2006/02/reporter-seriously-wounded-border-city-plagued-by/","https://cpj.org/2007/02/attacks-on-the-press-2006-mexico/"]},{"id":"2006-acapulco-police-heads-left-at-government-office","date":"2006-04-20","precision":"day","title":"Heads of two police officers displayed outside Acapulco government offices","summary":"The severed heads of municipal police commander Mario Núñez Magaña and officer Jesús Alberto Ibarra were left in front of the city finance offices in Acapulco's La Garita area with a red cardboard sign reading 'So that you learn to respect'; their bodies were dumped elsewhere. The spot was the site of a January 27, 2006 shootout in which the two officers had fought four gunmen linked to the cartel war, and the killings were read as reprisal.","impact":"The first public display of decapitated police in the modern drug war, months before Uruapan, it announced beheading as a message tactic and marked Acapulco's descent into cartel terror.","state":"GRO","city":"Acapulco","lat":16.8531,"lng":-99.8237,"cartels":["zetas","beltran_leyva","government"],"figures":["Mario Núñez Magaña","Jesús Alberto Ibarra"],"type":"killing","importance":3,"confidence":"high","sources":["https://www.nbcnews.com/news/amp/wbna12412835","https://www.oneindia.com/2006/04/21/two-mexican-cops-beheaded-in-acapulco-1145599920.html"]},{"id":"2006-javier-arellano-felix-captured-at-sea","date":"2006-08-14","precision":"day","title":"Tijuana Cartel leader Javier Arellano Félix captured by US Coast Guard at sea","summary":"Acting on DEA intelligence, the US Coast Guard cutter Monsoon boarded the sport-fishing boat Dock Holiday in international waters off Baja California Sur (described by the DEA as south of Cabo San Lucas) and arrested Francisco Javier Arellano Félix, 'El Tigrillo', who had led the Arellano Félix organization since March 2002, together with ten others. Taken to San Diego, he pleaded guilty in September 2007 and was sentenced to life on November 5, 2007 (later reduced for cooperation).","impact":"The third Arellano Félix brother removed in four years, his capture left the Tijuana Cartel to Eduardo Arellano and nephew Fernando Sánchez Arellano, whose internal split with Teodoro García Simental soon plunged Tijuana into war.","state":"BCS","city":"Cabo San Lucas (offshore)","lat":22.8905,"lng":-109.9167,"cartels":["tijuana","us_government"],"figures":["Francisco Javier Arellano Félix"],"type":"capture","importance":4,"confidence":"high","sources":["https://www.justice.gov/archive/opa/pr/2006/August/06_odag_547.html","https://www.legistorm.com/stormfeed/view_rss/385972/organization/95775/title/afo-leader-francisco-javier-arellano-felix-captured.html","https://www.npr.org/2006/08/17/5662515/suspected-drug-lord-captured-off-west-coast"]},{"id":"2006-uruapan-five-heads-la-familia-debut","date":"2006-09-06","precision":"day","title":"Five severed heads thrown onto Uruapan dance floor: La Familia's debut","summary":"Around 1 a.m. about 20 gunmen entered the Sol y Sombra nightclub in Uruapan, Michoacán, fired into the air and emptied bags containing five human heads onto the dance floor, leaving a sign: 'La Familia doesn't kill for pay, doesn't kill women, doesn't kill innocents; only those who deserve to die will die. Let everyone know: this is divine justice.' The victims had reportedly been abducted the previous day.","impact":"The public birth of La Familia Michoacana as a pseudo-religious, 'vigilante' cartel breaking from its Zetas mentors; the images shocked the nation and were cited by president-elect Calderón in choosing Michoacán for his first military operation.","state":"MIC","city":"Uruapan","lat":19.4208,"lng":-102.0629,"cartels":["familia_michoacana","zetas"],"figures":["Nazario Moreno González","José de Jesús Méndez Vargas"],"type":"massacre","importance":4,"confidence":"high","sources":["https://www.eluniversal.com.mx/estados/cabezas-humanas-en-un-bar-el-dia-que-llego-el-terror-michoacan/","https://www.infobae.com/mexico/2024/10/31/las-cinco-cabezas-en-sol-y-sombra-el-sangriento-episodio-en-uruapan-que-marco-la-antesala-de-la-guerra-contra-el-narco/","https://press.armywarcollege.edu/monographs/590/"]},{"id":"2006-la-familia-michoacana-newspaper-manifesto","date":"2006-11-22","precision":"day","title":"La Familia Michoacana publishes newspaper manifesto declaring itself","summary":"La Familia Michoacana took out half-page paid advertisements in Michoacán dailies including La Voz de Michoacán and El Sol de Morelia presenting itself as an organization of Michoacán natives whose mission was to eradicate kidnapping, extortion and methamphetamine sales by outsiders, while asking the public for understanding of its 'strategies'.","impact":"Formalized La Familia's break with the Zetas and its strategy of social legitimacy and territorial propaganda, a model of cartel public relations later imitated by the Knights Templar and others.","state":"MIC","city":"Morelia","lat":19.706,"lng":-101.195,"cartels":["familia_michoacana","zetas"],"figures":["Nazario Moreno González","José de Jesús Méndez Vargas"],"type":"other","importance":2,"confidence":"medium","sources":["https://press.armywarcollege.edu/monographs/590/","https://insightcrime.org/mexico-organized-crime-news/familia-michoacana-mexico-profile/"]},{"id":"2006-calderon-inaugurated-president","date":"2006-12-01","precision":"day","title":"Felipe Calderón sworn in after disputed election, vows war on cartels","summary":"Felipe Calderón Hinojosa of the PAN took office in a tense, minutes-long ceremony in Congress amid PRD protests over his 0.56-point July 2 victory over Andrés Manuel López Obrador. Having won with about 35.9% of the vote, he moved immediately to make security the centerpiece of his administration.","impact":"Opened the era of the militarized 'war on drugs': within ten days Calderón deployed thousands of troops to Michoacán, beginning a strategy of army-led operations and kingpin captures that reshaped Mexico's criminal landscape.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["government"],"figures":["Felipe Calderón Hinojosa","Andrés Manuel López Obrador"],"type":"policy","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Felipe_Calder%C3%B3n","https://www.aljazeera.com/news/2006/12/13/calderon-tackles-drug-violence"]},{"id":"2006-operativo-conjunto-michoacan-launched","date":"2006-12-11","precision":"day","title":"Operativo Conjunto Michoacán: Calderón sends troops, war on cartels begins","summary":"Interior Secretary Francisco Ramírez Acuña announced the deployment of some 6,500-7,000 soldiers, marines and federal police (the army contingent alone put at about 4,260, with aircraft and vehicles) to Michoacán, which had recorded more than 500 drug-related executions in 2006, among the highest tolls in the country. Troops fanned out into the Tierra Caliente to eradicate crops, dismantle meth labs and hunt La Familia and Zetas cells.","impact":"The first joint operation of the Calderón war, it set the template of military deployments replicated in Baja California, Guerrero, Tamaulipas and Chihuahua and is conventionally dated as the start of Mexico's drug war.","state":"MIC","city":"Morelia","lat":19.706,"lng":-101.195,"cartels":["government","familia_michoacana","zetas","milenio"],"figures":["Felipe Calderón Hinojosa","Francisco Ramírez Acuña","Guillermo Galván Galván"],"type":"policy","importance":5,"confidence":"high","sources":["https://es.wikipedia.org/wiki/Operativo_Conjunto_Michoac%C3%A1n","https://www.excelsior.com.mx/nacional/2016/12/12/1133699","https://www.aljazeera.com/news/2006/12/13/calderon-tackles-drug-violence"]},{"id":"2007-osiel-cardenas-extradited","date":"2007-01-19","precision":"day","title":"Osiel Cárdenas and 14 others extradited to the US","summary":"On the night of 19 January 2007, weeks into Felipe Calderón's term, Mexico flew 15 prisoners to the United States in a single overnight operation, including Gulf Cartel boss Osiel Cárdenas Guillén (jailed since 2003), Héctor 'El Güero' Palma and the Tijuana cartel's brothers Ismael and Gilberto Higuera Guerrero. Cárdenas landed in Houston early on 20 January to face trafficking, money-laundering and assault charges; he was sentenced there to 25 years in February 2010.","impact":"The largest mass extradition in Mexican history signalled Calderón's US-aligned strategy and removed Cárdenas's direct hand over the Gulf Cartel, accelerating the autonomy of its armed wing, Los Zetas.","state":"US","city":"Houston, Texas","lat":29.7604,"lng":-95.3698,"cartels":["gulf","tijuana","government","us_government"],"figures":["Osiel Cárdenas Guillén","Héctor 'El Güero' Palma","Felipe Calderón"],"type":"extradition","importance":4,"confidence":"high","sources":["https://www.justice.gov/archive/opa/pr/2007/January/07_ag_030.html","https://es.wikipedia.org/wiki/Osiel_C%C3%A1rdenas_Guill%C3%A9n"]},{"id":"2007-zhenli-ye-gon-cash-seizure","date":"2007-03-15","precision":"day","title":"Zhenli Ye Gon: $205 million cash seized in Mexico City","summary":"Federal agents raided the Lomas de Chapultepec mansion of Chinese-Mexican pharmaceutical importer Zhenli Ye Gon and found roughly US$205 million in cash plus pesos, euros and gold, the largest drug-cash seizure ever recorded. Prosecutors alleged he imported pseudoephedrine precursors for methamphetamine producers tied to the Sinaloa Cartel. He was arrested in Wheaton, Maryland, in July 2007 and extradited to Mexico in October 2016.","impact":"Exposed the industrial scale of Mexico's meth-precursor trade and led to tighter and then total bans on pseudoephedrine imports (2008-09), pushing cartels toward alternative synthesis routes.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["sinaloa","colima","government"],"figures":["Zhenli Ye Gon"],"type":"discovery","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Zhenli_Ye_Gon","https://www.washingtonpost.com/wp-dyn/content/article/2007/07/24/AR2007072400150.html"]},{"id":"2007-sandra-avila-arrested","date":"2007-09-28","precision":"day","title":"Sandra Ávila, 'La Reina del Pacífico', arrested","summary":"Federal agents arrested Sandra Ávila Beltrán, dubbed 'La Reina del Pacífico', in Mexico City together with her partner Juan Diego Espinosa Ramírez 'El Tigre' of Colombia's Norte del Valle cartel. She was accused of brokering cocaine shipments between Colombian suppliers and the Sinaloa Cartel. She was extradited to the United States in August 2012, returned to Mexico in 2013 and freed in February 2015.","impact":"A rare high-profile female trafficker whose case became emblematic of the Sinaloa-Colombia cocaine pipeline and of the culture surrounding narco power.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["sinaloa","government"],"figures":["Sandra Ávila Beltrán","Juan Diego Espinosa Ramírez"],"type":"capture","importance":2,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Sandra_%C3%81vila_Beltr%C3%A1n","https://www.theguardian.com/international/story/0,,2184870,00.html"]},{"id":"2008-mochomo-arrest-blo-split","date":"2008-01-21","precision":"day","title":"El Mochomo arrested; Beltrán Leyvas break with Sinaloa","summary":"The Mexican Army arrested Alfredo 'El Mochomo' Beltrán Leyva in Culiacán with about US$900,000 in cash, grenades, rifles and body armor. His brothers Arturo and Héctor blamed Joaquín 'El Chapo' Guzmán for betraying him and broke away from the Sinaloa Federation, allying with Los Zetas.","impact":"The Beltrán Leyva-Sinaloa split unleashed one of the war's bloodiest internal conflicts across Sinaloa, Sonora, Durango, Guerrero and Morelos and triggered a wave of assassinations of federal officials in 2008.","state":"SIN","city":"Culiacán","lat":24.8091,"lng":-107.394,"cartels":["beltran_leyva","sinaloa","government"],"figures":["Alfredo 'El Mochomo' Beltrán Leyva","Arturo Beltrán Leyva","Joaquín 'El Chapo' Guzmán"],"type":"split","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Alfredo_Beltr%C3%A1n_Leyva","https://www.justice.gov/opa/pr/alfredo-beltran-leyva-sentenced-life-prison-leading-international-drug-trafficking-conspiracy","https://en.wikipedia.org/wiki/Arturo_Beltr%C3%A1n_Leyva"]},{"id":"2008-operativo-conjunto-chihuahua","date":"2008-03-27","precision":"day","title":"Operativo Conjunto Chihuahua launched as Juárez war erupts","summary":"President Calderón ordered the Operativo Conjunto Chihuahua, sending more than 2,000 soldiers and federal police to Ciudad Juárez (later up to about 10,000) after homicides spiked in early 2008 with the Sinaloa Cartel's push into the Juárez Cartel's plaza. La Línea and its allies Barrio Azteca fought Gente Nueva and the Artistas Asesinos street by street.","impact":"Instead of pacifying the city, the deployment coincided with an explosion of violence: Juárez homicides rose from about 300 in 2007 to roughly 1,600 in 2008, 2,600-2,750 in 2009 and 3,100 in 2010, making it the world's most violent city.","state":"CHH","city":"Ciudad Juárez","lat":31.6904,"lng":-106.4245,"cartels":["government","sinaloa","juarez"],"figures":["Felipe Calderón","Joaquín 'El Chapo' Guzmán","Vicente Carrillo Fuentes"],"type":"policy","importance":4,"confidence":"high","sources":["https://es.wikipedia.org/wiki/Operativo_Conjunto_Chihuahua","https://www.jornada.com.mx/2010/03/28/politica/007n1pol","https://lasillarota.com/especiales-lsr/2018/3/27/chihuahua-las-cicatrices-de-10-anos-de-la-guerra-contra-el-narco-155125.html"]},{"id":"2008-edgar-millan-assassinated","date":"2008-05-08","precision":"day","title":"Federal police chief Édgar Millán assassinated","summary":"Édgar Eusebio Millán Gómez, acting commissioner of the Federal Preventive Police and the highest-ranking police official in the country, was shot nine times just after midnight as he entered his home in Mexico City's Colonia Guerrero and died hours later. Investigators tied the hit to the Beltrán Leyva organization in retaliation for Alfredo Beltrán Leyva's arrest; gunman Alejandro Ramírez Báez was sentenced to 60 years in June 2011.","impact":"The most senior Mexican official killed in the drug war to that point, one of several federal commanders murdered that spring, showing the cartels' reach into the capital and the security apparatus.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["beltran_leyva","government"],"figures":["Édgar Eusebio Millán Gómez","Arturo Beltrán Leyva"],"type":"killing","importance":4,"confidence":"high","sources":["https://www.nytimes.com/2008/05/09/world/americas/09mexico.html","https://www.washingtonpost.com/wp-dyn/content/article/2008/05/08/AR2008050803242.html","https://en.wikipedia.org/wiki/%C3%89dgar_Mill%C3%A1n_G%C3%B3mez"]},{"id":"2008-edgar-guzman-killed-culiacan","date":"2008-05-08","precision":"day","title":"Édgar Guzmán, El Chapo's son, killed in Culiacán","summary":"Édgar Guzmán López, 22-year-old son of Joaquín 'El Chapo' Guzmán, was killed in the parking lot of the City Club shopping center in Culiacán by a large group of gunmen who fired more than 500 rounds; a rocket launcher was found at the scene. Arturo Meza Cázares, son of alleged launderer Blanca Margarita Cázares, died with him. The Beltrán Leyva brothers were blamed.","impact":"Turned the Beltrán Leyva-Sinaloa rift into open war in the cartel's heartland: Culiacán saw more than 100 killings that month, thousands of extra troops were deployed to Sinaloa, and the feud shaped alliances for years.","state":"SIN","city":"Culiacán","lat":24.8091,"lng":-107.394,"cartels":["sinaloa","beltran_leyva"],"figures":["Édgar Guzmán López","Joaquín 'El Chapo' Guzmán","Arturo Beltrán Leyva"],"type":"killing","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Joaqu%C3%ADn_%22El_Chapo%22_Guzm%C3%A1n","https://es.wikipedia.org/wiki/Joaqu%C3%ADn_Guzm%C3%A1n_Loera","https://en.wikipedia.org/wiki/Beltr%C3%A1n-Leyva_Cartel"]},{"id":"2008-merida-initiative-signed","date":"2008-06-30","precision":"day","title":"Mérida Initiative signed into law","summary":"President George W. Bush signed H.R. 2642, the FY2008 supplemental appropriations act, releasing the first US$400 million for Mexico under the Mérida Initiative announced with Calderón on 22 October 2007. The three-year package, about US$1.4 billion for Mexico (US$1.6 billion including Central America), funded helicopters, scanners, training and justice reform, with 15 percent of funds conditioned on human-rights reporting.","impact":"Institutionalized US security cooperation with Mexico for the first time on this scale and framed the drug war as a shared responsibility; it later evolved into 'Beyond Mérida' with a focus on institutions and border communities.","state":"US","city":"Washington, D.C.","lat":38.9072,"lng":-77.0369,"cartels":["government","us_government"],"figures":["George W. Bush","Felipe Calderón"],"type":"policy","importance":4,"confidence":"high","sources":["https://crsreports.congress.gov/product/pdf/IF/IF10578","https://2009-2017.state.gov/j/inl/merida/","https://en.wikipedia.org/wiki/M%C3%A9rida_Initiative"]},{"id":"2008-creel-massacre","date":"2008-08-16","precision":"day","title":"Creel massacre: 13 killed at family gathering","summary":"Gunmen fired more than 200 rounds into a family gathering at a public hall in Creel, in the Sierra Tarahumara municipality of Bocoyna, killing 13 people including a 19-month-old baby. Authorities attributed the attack to La Línea, the Juárez Cartel's armed wing, amid its fight with Los Salazar, a Sinaloa-aligned clan, for the mountain corridor.","impact":"One of the first mass killings of civilians in the Chihuahua war, it showed the conflict spreading from Juárez into the sierra and became a lasting symbol of impunity: for years the case went unpunished, and only isolated convictions followed (one gunman was sentenced to 145 years in 2023).","state":"CHH","city":"Creel","lat":27.7508,"lng":-107.6353,"cartels":["juarez","sinaloa"],"figures":[],"type":"massacre","importance":3,"confidence":"medium","sources":["https://lasillarota.com/estados/2018/8/16/las-victimas-de-creel-el-mas-pequeno-tenia-un-ano-166684.html","https://raichali.com/2022/08/16/catorce-anos-despues-de-la-masacre-de-creel-la-memoria-resiste-con-mas-fuerza-y-con-mas-victimas/","https://es.wikipedia.org/wiki/Masacre_de_Creel"]},{"id":"2008-morelia-grenade-attack","date":"2008-09-15","precision":"day","title":"Morelia Independence Day grenade attack","summary":"Shortly after 11 p.m., as Governor Leonel Godoy led the Grito in Morelia's Plaza Melchor Ocampo, two fragmentation grenades were thrown into the crowd, killing eight people and wounding more than 100. La Familia Michoacana denied responsibility and blamed Los Zetas; three alleged Zetas arrested on 25 September confessed but were freed in May 2015 after a federal judge found evidence of torture and fabricated evidence.","impact":"The first indiscriminate terror-style attack on civilians in the drug war, it shocked the country, hardened Calderón's rhetoric and remains unsolved.","state":"MIC","city":"Morelia","lat":19.706,"lng":-101.195,"cartels":["familia_michoacana","zetas"],"figures":["Leonel Godoy Rangel"],"type":"attack","importance":5,"confidence":"high","sources":["https://www.animalpolitico.com/2018/09/granadazos-morelia-victimas-10-anos","https://www.nytimes.com/2008/09/25/world/americas/25mexico.html","https://en.wikipedia.org/wiki/2008_Morelia_grenade_attacks"]},{"id":"2008-operacion-limpieza-noe-ramirez","date":"2008-11-21","precision":"day","title":"Operación Limpieza: ex-SIEDO chief Noé Ramírez arrested","summary":"The Attorney General's office announced on 21 November 2008 the arrest of Noé Ramírez Mandujano, head of the organized-crime prosecution unit SIEDO from 2006 to August 2008, accused of receiving US$450,000 a month from the Beltrán Leyva organization. The 'Operación Limpieza' purge, built on protected-witness testimony, also netted senior Federal Police, Interpol-Mexico and PGR officials. Ramírez was acquitted in 2013 for lack of evidence.","impact":"Revealed cartel penetration of the very agencies leading Calderón's offensive, undermined confidence in the SIEDO and Federal Police, and later collapsed in court, exposing the weakness of witness-based prosecutions.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["beltran_leyva","government"],"figures":["Noé Ramírez Mandujano","Eduardo Medina Mora"],"type":"corruption","importance":4,"confidence":"medium","sources":["http://edition.cnn.com/2008/WORLD/americas/11/21/mexico.arrest/index.html","https://en.wikipedia.org/wiki/No%C3%A9_Ram%C3%ADrez_Mandujano","https://en.wikipedia.org/wiki/Timeline_of_the_Mexican_drug_war"]},{"id":"2009-tello-quinones-killed-cancun","date":"2009-02-03","precision":"day","title":"Gen. Tello Quiñones murdered in Cancún","summary":"Retired Brigadier General Mauro Enrique Tello Quiñones, who had taken up a post less than a day earlier as Cancún mayor Gregorio Sánchez's anti-crime adviser, was abducted, tortured and shot 11 times; his body was found in a pickup on the Cancún-Mérida highway with those of his aide, Lt. Julio César Román Zúñiga, and his driver Juan Ramírez Sánchez, the mayor's nephew. Los Zetas, then allied with the Beltrán Leyvas in Quintana Roo, were blamed.","impact":"Prompted the federal Operation Quintana Roo, the arrest of Cancún's police chief and later of the mayor himself, exposing Zetas control of the Caribbean tourist corridor.","state":"ROO","city":"Cancún","lat":21.1619,"lng":-86.8515,"cartels":["zetas","beltran_leyva","government"],"figures":["Mauro Enrique Tello Quiñones","Gregorio Sánchez Martínez"],"type":"killing","importance":3,"confidence":"medium","sources":["https://www.proceso.com.mx/nacional/2009/2/5/tello-quinones-victima-de-una-traicion-12678.html","https://en.wikipedia.org/wiki/Operation_Quintana_Roo"]},{"id":"2009-vicente-zambada-niebla-arrested","date":"2009-03-19","precision":"day","title":"Vicente Zambada Niebla arrested in Mexico City","summary":"Soldiers arrested Vicente 'El Vicentillo' Zambada Niebla, son and heir apparent of Sinaloa co-leader Ismael 'El Mayo' Zambada, at a house in the Pedregal area of southern Mexico City, hours after he met DEA agents at a hotel. He was extradited to Chicago in February 2010, claimed he had an informant deal, and later became a cooperating witness.","impact":"The first capture of a top Zambada heir; his cooperation fed US cases against the Sinaloa leadership and made him a star witness at El Chapo's 2018-19 trial.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["sinaloa","government","us_government"],"figures":["Vicente Zambada Niebla","Ismael 'El Mayo' Zambada"],"type":"capture","importance":3,"confidence":"high","sources":["https://www.cnn.com/2009/CRIME/03/19/mexico.drug.arrest/index.html","https://en.wikipedia.org/wiki/Vicente_Zambada_Niebla"]},{"id":"2009-cieneguillas-prison-break","date":"2009-05-16","precision":"day","title":"Cieneguillas prison break frees 53 inmates","summary":"Before dawn, a convoy of some 30 gunmen dressed as federal police, with a helicopter overhead, drove into the Cieneguillas state prison outside Zacatecas city and walked out with 53 inmates in about five minutes without firing a shot. Security video showed guards standing aside; the warden and more than 40 guards were detained. Most escapees were Gulf Cartel and Zetas members.","impact":"The most brazen mass escape of the era demonstrated the Zetas' penetration of state prison systems and became a model for later breakouts that replenished their ranks.","state":"ZAC","city":"Cieneguillas, Zacatecas","lat":22.745,"lng":-102.645,"cartels":["zetas","gulf","government"],"figures":[],"type":"escape","importance":3,"confidence":"high","sources":["https://www.csmonitor.com/World/Americas/2009/0520/p90s01-woam.html","https://www.nbcnews.com/id/wbna30785523","https://en.wikipedia.org/wiki/Cieneguillas_prison_riots"]},{"id":"2009-michoacanazo","date":"2009-05-26","precision":"day","title":"Michoacanazo: 10 mayors and officials arrested","summary":"Federal police and soldiers swept through Michoacán arresting 10 mayors (an 11th later), 16 state and municipal officials and a judge on suspicion of working for La Familia Michoacana, without informing PRD governor Leonel Godoy. The operation came weeks before the July midterm elections. Nearly all detainees were released within a year and none was convicted.","impact":"The largest federal action against elected officials in the war raised hopes of tackling political protection for cartels but collapsed in court, feeding accusations of political motives and weakening Calderón's anti-corruption credibility.","state":"MIC","city":"Morelia","lat":19.706,"lng":-101.195,"cartels":["familia_michoacana","government"],"figures":["Felipe Calderón","Leonel Godoy Rangel"],"type":"corruption","importance":4,"confidence":"high","sources":["https://es.wikipedia.org/wiki/Michoacanazo","https://en.wikipedia.org/wiki/La_Familia_Michoacana"]},{"id":"2009-la-familia-kills-12-federal-agents","date":"2009-07-13","precision":"day","title":"La Familia kills 12 federal agents near La Huacana","summary":"After federal police arrested La Familia's Arnoldo Rueda Medina 'La Minsa' in Morelia on 11 July 2009, the cartel attacked federal police posts in at least eight Michoacán cities over the weekend. Late on Monday 13 July the tortured bodies of 12 federal agents were found dumped on a mountain road near La Huacana with a message challenging the police to come for more.","impact":"The deadliest single attack on federal forces of Calderón's war showed La Familia's capacity for coordinated insurgent-style violence and prompted a massive federal reinforcement of Michoacán.","state":"MIC","city":"La Huacana","lat":18.9628,"lng":-101.8075,"cartels":["familia_michoacana","government"],"figures":["Arnoldo Rueda Medina","Nazario 'El Chayo' Moreno González","Servando 'La Tuta' Gómez Martínez"],"type":"attack","importance":4,"confidence":"medium","sources":["https://www.aljazeera.com/news/2009/7/15/mexico-federal-agents-found-slain","https://www.cbsnews.com/news/mexico-arrests-4-in-murder-of-12-police","https://www.quadratin.com.mx/justicia/dia-del-policia-federal-el-ataque-que-cobro-la-vida-de-12-agentes/"]},{"id":"2009-el-lobo-captured-milenio-splits","date":"2009-10-28","precision":"day","title":"El Lobo captured; Milenio Cartel splits","summary":"Óscar Orlando Nava Valencia 'El Lobo', leader of the Sinaloa-aligned Milenio (Valencia) Cartel, was captured after a gunfight with the Army in Tlajomulco de Zúñiga, on the outskirts of Guadalajara. His organization fractured into La Resistencia, led by Ramiro Pozos 'El Molca', and Los Torcidos, led by Nemesio Oseguera 'El Mencho' and Erick Valencia, whom the Resistencia accused of betraying El Lobo.","impact":"The Milenio split created the nucleus of what became the Cártel Jalisco Nueva Generación and opened a war for Jalisco that escalated after Nacho Coronel's death in 2010.","state":"JAL","city":"Tlajomulco de Zúñiga","lat":20.4736,"lng":-103.4436,"cartels":["milenio","cjng","sinaloa","government"],"figures":["Óscar Orlando Nava Valencia","Nemesio 'El Mencho' Oseguera Cervantes","Ramiro Pozos González"],"type":"split","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Milenio_Cartel","https://insightcrime.org/mexico-organized-crime-news/jalisco-cartel-new-generation/"]},{"id":"2009-arturo-beltran-leyva-killed","date":"2009-12-16","precision":"day","title":"Arturo Beltrán Leyva killed by marines in Cuernavaca","summary":"About 200 Navy marines backed by helicopters stormed the Altitude condominium tower in Cuernavaca's Lomas de la Selva and killed Arturo 'El Barbas' Beltrán Leyva after a 90-minute firefight; several gunmen and marine Melquisedet Angulo Córdova also died. Photos of the corpse covered in money and jewels caused a scandal.","impact":"The first top-tier kingpin killed under Calderón; the Navy emerged as the government's preferred strike force, and the leaderless organization split into warring factions under Héctor Beltrán Leyva and Édgar 'La Barbie' Valdez, spreading violence through Morelos and Guerrero.","state":"MOR","city":"Cuernavaca","lat":18.9242,"lng":-99.2216,"cartels":["beltran_leyva","government"],"figures":["Arturo Beltrán Leyva","Héctor Beltrán Leyva","Édgar 'La Barbie' Valdez Villarreal","Melquisedet Angulo Córdova"],"type":"killing","importance":5,"confidence":"high","sources":["http://www.cnn.com/2009/WORLD/americas/12/17/mexico.cartel.leader.killed/","https://en.wikipedia.org/wiki/Arturo_Beltr%C3%A1n_Leyva"]},{"id":"2009-paraiso-marine-family-murdered","date":"2009-12-22","precision":"day","title":"Marine's family murdered in Paraíso, Tabasco","summary":"Hours after the Navy honored marine Melquisedet Angulo Córdova, killed in the Cuernavaca raid on Arturo Beltrán Leyva, gunmen broke into his family's home in Paraíso, Tabasco, shortly after midnight and killed his mother Irma Córdova Palma, his brother Benito, his sister Jolidabey and an aunt, Josefa Angulo Flores; another sister was seriously wounded. The Beltrán Leyva organization was blamed.","impact":"A chilling act of reprisal against the security forces' families that led the government to shield the identities of personnel involved in kingpin operations.","state":"TAB","city":"Paraíso","lat":18.3958,"lng":-93.2136,"cartels":["beltran_leyva","government"],"figures":["Melquisedet Angulo Córdova","Irma Córdova Palma"],"type":"killing","importance":3,"confidence":"high","sources":["https://www.dallasnews.com/news/2009/12/23/gunmen-kill-family-of-marine-who-died-in-mexican-raid-that-took-down-drug-kingpin/","https://www.deseret.com/2009/12/23/20360465/family-of-mexican-drug-war-hero-who-died-in-raid-is-slain/","https://en.wikipedia.org/wiki/Melquisedet_Angulo_C%C3%B3rdova"]},{"id":"2010-el-teo-captured-la-paz","date":"2010-01-12","precision":"day","title":"El Teo captured in La Paz, ending Tijuana war phase","summary":"Federal police special forces, with US intelligence support, arrested Teodoro 'El Teo' García Simental at the Fidepaz residential complex in La Paz, Baja California Sur. After breaking with the Arellano Félix organization in April 2008 and allying with the Sinaloa Cartel, his faction had waged a war of kidnappings and beheadings that drove Tijuana to record homicide levels in 2008-09.","impact":"His capture, followed by his brother José Manuel's on 7 February 2010, sharply reduced Tijuana's violence and left the weakened Arellano Félix remnant coexisting with Sinaloa's control of the corridor.","state":"BCS","city":"La Paz","lat":24.1426,"lng":-110.3128,"cartels":["tijuana","sinaloa","government"],"figures":["Teodoro 'El Teo' García Simental","Luis Fernando 'El Ingeniero' Sánchez Arellano"],"type":"capture","importance":3,"confidence":"high","sources":["http://www.latimes.com/news/nation-and-world/la-fg-mexico-arrest13-2010jan13","http://www.eluniversal.com.mx/notas/651198.html","https://en.wikipedia.org/wiki/Teodoro_Garc%C3%ADa_Simental"]},{"id":"2010-gulf-zetas-split-reynosa","date":"2010-01-18","precision":"day","title":"Gulf Cartel–Zetas rupture begins in Reynosa","summary":"Gulf Cartel lieutenant Samuel Flores Borrego 'Metro 3' captured and killed Zetas plaza boss Víctor Peña Mendoza 'Concord 3' in Reynosa on 18 January 2010. Miguel Ángel Treviño Morales 'Z-40' demanded the killer be handed over by 25 January; the Gulf leadership refused. By late February convoys marked CDG and XXX were fighting Zetas units across Reynosa, Río Bravo, Matamoros and Nuevo Laredo, and the Gulf Cartel allied with La Familia and Sinaloa.","impact":"The definitive break between the Gulf Cartel and its former armed wing turned Tamaulipas and Nuevo León into a war zone for years and produced atrocities such as San Fernando and the emptying of Ciudad Mier.","state":"TAM","city":"Reynosa","lat":26.0806,"lng":-98.288,"cartels":["gulf","zetas","familia_michoacana","sinaloa"],"figures":["Samuel Flores Borrego","Víctor Peña Mendoza","Miguel Ángel Treviño Morales","Heriberto Lazcano Lazcano","Jorge Eduardo Costilla Sánchez"],"type":"split","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Samuel_Flores_Borrego","https://en.wikipedia.org/wiki/Gulf_Cartel","https://insightcrime.org/mexico-organized-crime-news/zetas-profile/"]},{"id":"2010-villas-de-salvarcar-massacre","date":"2010-01-31","precision":"day","title":"Villas de Salvárcar massacre in Ciudad Juárez","summary":"In the early hours of 31 January 2010, gunmen from La Línea and the Barrio Azteca gang stormed a student birthday party in the Villas de Salvárcar neighborhood of Ciudad Juárez, killing 15 people (16 by some counts) aged 15 to 20 and wounding a dozen. José Antonio Acosta 'El Diego' ordered the attack on the mistaken belief that rival Artistas Asesinos were present. From Japan, President Calderón initially suggested a gang fight, then apologized.","impact":"Public fury, epitomized by Luz María Dávila confronting Calderón, forced the launch of the 'Todos Somos Juárez' social program and the replacement of the Army by federal police in the city.","state":"CHH","city":"Ciudad Juárez","lat":31.6904,"lng":-106.4245,"cartels":["juarez","government"],"figures":["José Antonio Acosta Hernández","Felipe Calderón","Luz María Dávila"],"type":"massacre","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Villas_de_Salv%C3%A1rcar_massacre","https://es.wikipedia.org/wiki/Masacre_de_Villas_de_Salv%C3%A1rcar"]},{"id":"2010-juarez-us-consulate-killings","date":"2010-03-13","precision":"day","title":"US consulate-linked employees killed in Juárez","summary":"Leaving a children's party in Ciudad Juárez, US consulate employee Lesley Enríquez, who was pregnant, and her husband Arthur Redelfs, an El Paso County jail officer, were shot dead in one vehicle, while Jorge Alberto Salcido, husband of another consulate employee, was killed in a second ambush. Barrio Azteca leader Arturo Gallegos Castrellón 'El Farmero' ordered the hits.","impact":"The first killing of US government-linked personnel in the war brought direct White House involvement, authorized departures of consulate families, and a high-level US delegation to Mexico ten days later that reframed the Mérida Initiative.","state":"CHH","city":"Ciudad Juárez","lat":31.6904,"lng":-106.4245,"cartels":["juarez","us_government","government"],"figures":["Lesley Enríquez","Arthur Redelfs","Jorge Alberto Salcido","Arturo Gallegos Castrellón"],"type":"killing","importance":4,"confidence":"high","sources":["https://www.nytimes.com/2010/03/15/world/americas/15juarez.html","https://en.wikipedia.org/wiki/Barrio_Azteca"]},{"id":"2010-monterrey-narcobloqueos-begin","date":"2010-03-18","precision":"day","title":"Zetas narcobloqueos begin in Monterrey","summary":"On 18 March 2010 in García and on 19 March in Monterrey itself, Zetas gunmen hijacked buses and trucks and used them to block highways and avenues in the metropolitan area, the first 'narcobloqueos' reported in Mexico. The tactic recurred all year, peaking on 9 June with 28 simultaneous blockades after the arrest of plaza boss Héctor Raúl Luna 'El Tori', and again in August.","impact":"Blockades turned Mexico's industrial capital into a visible battleground of the Gulf-Zetas war, paralyzed daily life, and became a signature cartel tactic against military operations nationwide.","state":"NLE","city":"Monterrey","lat":25.6866,"lng":-100.3161,"cartels":["zetas","government"],"figures":["Héctor Raúl Luna Luna"],"type":"attack","importance":3,"confidence":"medium","sources":["https://animalpolitico.com/2011/02/narcobloqueos-11-meses-de-miedo","https://www.proceso.com.mx/nacional/2010/6/9/captura-de-lider-de-los-zetas-desata-narcobloqueos-en-monterrey-6489.html","https://www.jornada.com.mx/2010/06/10/politica/007n1pol"]},{"id":"2010-tec-de-monterrey-students-killed","date":"2010-03-19","precision":"day","title":"Soldiers kill two Tec de Monterrey students","summary":"During a pursuit of gunmen, soldiers shot dead graduate students Jorge Antonio Mercado Alonso and Javier Francisco Arredondo Verdugo at the gate of the Tecnológico de Monterrey campus. The Army planted weapons and described them as hitmen; the National Human Rights Commission's Recommendation 45/2010 found the scene had been altered and the unarmed students beaten and shot at close range.","impact":"A landmark case of military abuse and cover-up that galvanized Monterrey's elite against the militarized strategy and became a reference point in debates over army accountability.","state":"NLE","city":"Monterrey","lat":25.6866,"lng":-100.3161,"cartels":["government"],"figures":["Jorge Antonio Mercado Alonso","Javier Francisco Arredondo Verdugo"],"type":"killing","importance":3,"confidence":"high","sources":["https://es.wikipedia.org/wiki/Asesinato_de_Jorge_Mercado_y_Javier_Arredondo","https://www.cndh.org.mx/sites/default/files/doc/Recomendaciones/2010/REC_2010_045.pdf","https://en.wikipedia.org/wiki/2010_in_Mexico"]},{"id":"2010-taxco-mine-shaft-mass-grave","date":"2010-05-31","precision":"day","title":"55 bodies recovered from Taxco mine shaft","summary":"Acting on a tip from a detainee arrested in Iguala, authorities found bodies dumped down the roughly 100-meter shaft of the abandoned La Concha silver mine outside Taxco at the end of May 2010. Recovery work, with teams rappelling into the shaft, concluded in early June with 55 bodies, some mummified, killed at different times; only a handful were identified, among them a kidnapped state prison warden. The killings were attributed to factions of the fractured Beltrán Leyva organization fighting for northern Guerrero.","impact":"The largest clandestine grave found in Mexico to that date, it foreshadowed the era of mass graves and highlighted Guerrero's descent into factional war after Arturo Beltrán Leyva's death.","state":"GRO","city":"Taxco","lat":18.5564,"lng":-99.605,"cartels":["beltran_leyva","government"],"figures":[],"type":"discovery","importance":3,"confidence":"medium","sources":["http://www.washingtonpost.com/wp-dyn/content/article/2010/06/23/AR2010062305176.html","https://www.csmonitor.com/World/Americas/2010/0608/Mexico-mass-grave-highlights-gruesome-drug-war","https://www.voanews.com/a/article-55-bodies-dumped-in-abandoned-mexican-silver-mine-95856524/163929.html"]},{"id":"2010-torre-cantu-assassinated","date":"2010-06-28","precision":"day","title":"Gubernatorial candidate Rodolfo Torre Cantú assassinated","summary":"Rodolfo Torre Cantú, the PRI candidate and heavy favorite for governor of Tamaulipas, was ambushed by gunmen on the highway to Ciudad Victoria's airport six days before the 4 July election; at least four members of his entourage died with him. Los Zetas were initially blamed; federal prosecutors later alleged Gulf Cartel boss Jorge Eduardo Costilla ordered the killing. His brother Egidio replaced him and won.","impact":"The highest-ranking political assassination since 1994 showed cartels' willingness to decide elections by force and marked the peak of organized crime's intimidation of Tamaulipas politics.","state":"TAM","city":"Ciudad Victoria","lat":23.7369,"lng":-99.1411,"cartels":["zetas","gulf","government"],"figures":["Rodolfo Torre Cantú","Egidio Torre Cantú","Jorge Eduardo Costilla Sánchez"],"type":"killing","importance":5,"confidence":"high","sources":["https://www.nytimes.com/2010/06/29/world/americas/29mexico.html","https://en.wikipedia.org/wiki/Rodolfo_Torre_Cant%C3%BA"]},{"id":"2010-tubutama-battle-sonora","date":"2010-07-01","precision":"day","title":"Tubutama battle: 21 killed in Sinaloa–Beltrán Leyva clash","summary":"Before dawn on 1 July 2010 a Sinaloa Cartel convoy of some 20 trucks hunting Beltrán Leyva ally Arnoldo del Cid 'El Gilo' was ambushed at La Reforma, between Tubutama and Sáric in the Sonoran desert, by Beltrán Leyva gunmen reinforced by Zetas. Twenty-one people were killed, all Sinaloa hitmen according to the Army, nine were detained and bullet-riddled vehicles were seized.","impact":"The biggest single battle of the Sinaloa-Beltrán Leyva war and the deadliest gunfight in Sonora's history, it revealed the fight for smuggling corridors into Arizona and the war's spread to the border ranchlands.","state":"SON","city":"Tubutama–Sáric","lat":30.8833,"lng":-111.4667,"cartels":["sinaloa","beltran_leyva","zetas"],"figures":["Joaquín 'El Chapo' Guzmán","Arnoldo del Cid Buelna"],"type":"battle","importance":3,"confidence":"high","sources":["https://www.milenio.com/policia/batalla-tubutama-beltran-leyva-embosco-gente-chapo","https://expansion.mx/nacional/2010/07/02/los-muertos-en-el-enfrentamiento-de-sonora-eran-de-sinaloa-y-tamaulipas","https://es.wikipedia.org/wiki/Batalla_de_Tubutama"]},{"id":"2010-juarez-car-bomb","date":"2010-07-15","precision":"day","title":"First cartel car bomb explodes in Ciudad Juárez","summary":"La Línea lured federal police and paramedics to a downtown Juárez intersection by dumping a wounded man dressed as a police officer, then detonated about 10 kg of C-4 in a parked car by cellphone, killing at least three people including a federal agent and a doctor who rushed to help. A message threatened more bombs unless authorities investigated federal police allegedly protecting the Sinaloa Cartel.","impact":"The first car bomb of the Mexican drug war raised fears of Colombian-style narco-terrorism and prompted a review of Juárez security tactics.","state":"CHH","city":"Ciudad Juárez","lat":31.6904,"lng":-106.4245,"cartels":["juarez","government"],"figures":[],"type":"attack","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Ju%C3%A1rez_Cartel","https://en.wikipedia.org/wiki/Timeline_of_the_Mexican_drug_war"]},{"id":"2010-torreon-quinta-italia-massacre","date":"2010-07-18","precision":"day","title":"Torreón party massacre carried out by furloughed inmates","summary":"Gunmen opened fire on a birthday party at the Quinta Italia Inn in Torreón, Coahuila, killing 17 people (later counts 18) and wounding 18. Federal prosecutors found the shooters were inmates of the Gómez Palacio prison in Durango, let out at night by warden Margarita Rojas with guards' weapons and official vehicles, and that the same rifles had been used in two earlier bar massacres in Torreón.","impact":"Exposed prisons operating as cartel barracks in the Sinaloa-Zetas war for La Laguna and led to federal takeover of the Gómez Palacio prison and charges against its officials.","state":"COA","city":"Torreón","lat":25.5428,"lng":-103.4068,"cartels":["sinaloa","zetas","government"],"figures":["Margarita Rojas Rodríguez"],"type":"massacre","importance":3,"confidence":"high","sources":["https://justiceinmexico.org/prisoners-in-torreon-were-allowed-to-leave-prison-at-night-in-order-to-carry-out-executions/","https://www.jornada.com.mx/2010/07/26/politica/007n1pol","https://www.aljazeera.com/news/2010/7/27/mexico-inmates-let-out-to-kill"]},{"id":"2010-nacho-coronel-killed-cjng-emerges","date":"2010-07-29","precision":"day","title":"Nacho Coronel killed in Zapopan; CJNG emerges","summary":"Army special forces killed Ignacio 'Nacho' Coronel Villarreal, the Sinaloa Federation's boss for Jalisco and the Pacific and its methamphetamine pioneer, in a raid on a house in the Colinas de San Javier area of Zapopan. His death left a vacuum in Jalisco that was filled by Los Torcidos, the Milenio faction led by Nemesio Oseguera 'El Mencho', which soon began calling itself the Cártel Jalisco Nueva Generación.","impact":"The most consequential Sinaloa loss of the Calderón years: it dismantled the federation's western pillar and gave rise to the CJNG, which within a decade became Mexico's most powerful and expansionist cartel.","state":"JAL","city":"Zapopan","lat":20.7214,"lng":-103.3918,"cartels":["sinaloa","cjng","milenio","government"],"figures":["Ignacio 'Nacho' Coronel Villarreal","Nemesio 'El Mencho' Oseguera Cervantes","Joaquín 'El Chapo' Guzmán"],"type":"killing","importance":5,"confidence":"high","sources":["http://edition.cnn.com/2010/CRIME/07/29/mexico.cartel.leader.killed/","https://insightcrime.org/mexico-organized-crime-news/jalisco-cartel-new-generation/","https://en.wikipedia.org/wiki/Ignacio_Coronel_Villarreal"]},{"id":"2010-edelmiro-cavazos-killed","date":"2010-08-15","precision":"day","title":"Santiago mayor Edelmiro Cavazos kidnapped and killed","summary":"Edelmiro Cavazos Leal, the PAN mayor of Santiago, Nuevo León, who had moved to purge his corrupt police, was seized from his home by about 15 gunmen on the night of 15 August 2010. His blindfolded body, hands bound, was found on 18 August on a rural road outside town. At least six municipal police officers, including his own bodyguard, were arrested for delivering him to Los Zetas.","impact":"The killing of a mayor in Monterrey's affluent suburbs, with his own police complicit, epitomized the Zetas' capture of local governments and spurred plans for unified state police commands.","state":"NLE","city":"Santiago","lat":25.4253,"lng":-100.1466,"cartels":["zetas","government"],"figures":["Edelmiro Cavazos Leal"],"type":"killing","importance":3,"confidence":"high","sources":["https://www.bloomberg.com/news/articles/2010-08-18/mexican-mayor-cavazos-is-found-dead-after-being-kidnapped-milenio-reports","https://www.nbcnews.com/id/wbna38755444","https://en.wikipedia.org/wiki/Edelmiro_Cavazos_Leal"]},{"id":"2010-san-fernando-72-migrants","date":"2010-08-24","precision":"day","title":"San Fernando: 72 migrants massacred by Zetas","summary":"Marines following a wounded Ecuadorian survivor, Luis Freddy Lala Pomavilla, found 58 men and 14 women shot dead in a warehouse on a ranch at El Huizachal, San Fernando, Tamaulipas, on 24 August 2010. The victims, migrants from Central and South America, had been killed on 22-23 August by Los Zetas after refusing to work for the cartel or pay ransoms. Dozens of Zetas were later arrested for the killings.","impact":"The war's most notorious atrocity to that point, it exposed the mass victimization of migrants, prompted international condemnation and a federal migrant-protection strategy, and foreshadowed the 2011 San Fernando graves.","state":"TAM","city":"San Fernando","lat":24.8486,"lng":-98.1569,"cartels":["zetas","government"],"figures":["Luis Freddy Lala Pomavilla"],"type":"massacre","importance":5,"confidence":"high","sources":["https://www.bbc.co.uk/news/world-latin-america-11090563","https://www.theguardian.com/world/2010/aug/25/mexican-police-72-bodies-dump","https://en.wikipedia.org/wiki/2010_San_Fernando_massacre"]},{"id":"2010-la-barbie-captured","date":"2010-08-30","precision":"day","title":"La Barbie captured in Estado de México","summary":"Federal police arrested Texas-born Édgar 'La Barbie' Valdez Villarreal at a house in Cañada de Alféres near Salazar, Lerma, in the forested hills west of Mexico City. Once Arturo Beltrán Leyva's chief enforcer, he had fought Héctor Beltrán Leyva's faction for control of the organization since December 2009 in a war that left more than 150 dead in Morelos and Guerrero.","impact":"Ended one side of the Beltrán Leyva succession war but shattered his network: remnants formed the Cártel Independiente de Acapulco and fed the rise of Guerreros Unidos and Los Rojos, deepening Guerrero's fragmentation.","state":"MEX","city":"Salazar (Lerma)","lat":19.305,"lng":-99.386,"cartels":["beltran_leyva","cida","pacifico_sur","government"],"figures":["Édgar 'La Barbie' Valdez Villarreal","Héctor Beltrán Leyva"],"type":"capture","importance":4,"confidence":"high","sources":["https://www.bbc.co.uk/news/world-latin-america-11134727","https://en.wikipedia.org/wiki/Edgar_Valdez_Villarreal"]},{"id":"2010-el-grande-captured-puebla","date":"2010-09-12","precision":"day","title":"El Grande captured by marines in Puebla","summary":"Navy marines arrested Sergio 'El Grande' Villarreal Barragán, Héctor Beltrán Leyva's chief enforcer and one of the organization's last senior commanders, at a residence in the Puebla metropolitan area (reported as Lomas de Angelópolis, San Andrés Cholula) on 12 September 2010, two weeks after La Barbie's capture. The government had offered a 30-million-peso reward. He was extradited to the United States in May 2012 and became a cooperating witness.","impact":"Completed the decapitation of the original Beltrán Leyva leadership within nine months, leaving Héctor Beltrán Leyva's Cártel del Pacífico Sur as a diminished remnant and accelerating the fragmentation of Guerrero and Morelos.","state":"PUE","city":"Puebla","lat":19.0414,"lng":-98.2063,"cartels":["beltran_leyva","pacifico_sur","government"],"figures":["Sergio 'El Grande' Villarreal Barragán","Héctor Beltrán Leyva"],"type":"capture","importance":3,"confidence":"high","sources":["https://www.latimes.com/archives/la-xpm-2010-sep-14-la-fg-mexico-beltran-20100914-story.html","https://www.cnn.com/2010/WORLD/americas/09/12/mexico.arrest/index.html","https://en.wikipedia.org/wiki/Sergio_Villarreal_Barrag%C3%A1n"]},{"id":"2010-ciudad-mier-exodus","date":"2010-11-01","precision":"month","title":"Ciudad Mier exodus: town emptied by Zetas threats","summary":"After months of Gulf-Zetas fighting over the Ribereña highway, and following Tony Tormenta's death on 5 November, Zetas gunmen phoned and drove through Ciudad Mier, Tamaulipas, threatening to kill anyone who stayed. From about 5 November most of the roughly 6,500 residents fled, hundreds to a Lions Club shelter in Miguel Alemán where mayor José Iván Mancías ran the municipality; by mid-November state officials counted fewer than a thousand people left in town.","impact":"Mexico's first cartel-emptied 'ghost town' made forced displacement a visible dimension of the war and prompted a permanent army garrison; residents began returning only in 2011.","state":"TAM","city":"Ciudad Mier","lat":26.4322,"lng":-99.1511,"cartels":["zetas","gulf","government"],"figures":["José Iván Mancías Hinojosa"],"type":"other","importance":3,"confidence":"medium","sources":["https://www.jornada.com.mx/2010/11/11/politica/005n1pol","https://www.jornada.com.mx/2010/11/19/politica/002n1pol","https://vanguardia.com.mx/noticias/nacional/2923792-carteles-convierten-mier-en-pueblo-fantasma-PBVG2923792"]},{"id":"2010-tony-tormenta-killed-matamoros","date":"2010-11-05","precision":"day","title":"Tony Tormenta killed in Matamoros battle","summary":"Gulf Cartel co-leader Antonio Ezequiel 'Tony Tormenta' Cárdenas Guillén, brother of Osiel, died in an eight-hour battle in Matamoros as more than 660 marines with 17 vehicles and three helicopters fought his Escorpiones bodyguard. Officially ten people died: Cárdenas, four gunmen, three marines, a soldier and journalist Carlos Guajardo; local reports put the toll far higher. Leadership passed to Jorge Eduardo Costilla and Mario Cárdenas.","impact":"Removed the Gulf Cartel's last Cárdenas-era strongman during its war with the Zetas, triggered reprisals such as the emptying of Ciudad Mier, and seeded the Metros-Rojos feud that fractured the cartel from 2011.","state":"TAM","city":"Matamoros","lat":25.869,"lng":-97.5027,"cartels":["gulf","government"],"figures":["Antonio 'Tony Tormenta' Cárdenas Guillén","Jorge Eduardo Costilla Sánchez","Carlos Alberto Guajardo Romero"],"type":"battle","importance":4,"confidence":"high","sources":["http://www.jornada.unam.mx/2010/11/06/politica/007n1pol","https://www.theguardian.com/world/2010/nov/07/mexico-drugs-gulf-cartel-antonio-guillen","https://www.bbc.com/mundo/noticias/2010/11/101106_perfil_tormenta"]},{"id":"2010-apatzingan-nazario-moreno-staged-death","date":"2010-12-09","precision":"day","title":"Apatzingán battle; Nazario Moreno's staged death","summary":"About 2,000 federal police fought La Familia Michoacana gunmen for two days around Apatzingán and the village of El Alcalde, amid cartel blockades with dozens of burning vehicles and human shields across the Tierra Caliente. On 10 December the government announced that founder Nazario 'El Chayo' Moreno González had been killed on 9 December, though no body was recovered. He was in fact alive and was killed by the Army and Navy in Tumbiscatío on 9 March 2014.","impact":"The supposed death split La Familia: Servando 'La Tuta' Gómez founded the Caballeros Templarios in March 2011 while Moreno, secretly alive, became a cult figure; the episode badly damaged the credibility of Calderón's kingpin claims.","state":"MIC","city":"Apatzingán","lat":19.0886,"lng":-102.3508,"cartels":["familia_michoacana","templarios","government"],"figures":["Nazario 'El Chayo' Moreno González","Servando 'La Tuta' Gómez Martínez","José de Jesús 'El Chango' Méndez Vargas"],"type":"battle","importance":4,"confidence":"high","sources":["http://www.insightcrime.org/news-analysis/mythical-leader-of-mexico-drug-cartel-dead-for-sure-this-time","https://en.wikipedia.org/wiki/Nazario_Moreno_Gonz%C3%A1lez","https://en.wikipedia.org/wiki/La_Familia_Michoacana"]},{"id":"2010-brian-terry-fast-and-furious","date":"2010-12-14","precision":"day","title":"Agent Brian Terry killed with Fast and Furious guns","summary":"US Border Patrol agent Brian Terry was fatally shot late on 14 December 2010 in a firefight with a bandit 'rip crew' in Peck Canyon near Rio Rico, Arizona, about 11 miles north of the border, dying in the early hours of 15 December. Two AK-pattern rifles recovered at the scene were traced to Operation Fast and Furious, the ATF's Phoenix 'gunwalking' program that since late 2009 had let some 2,000 weapons flow to Sinaloa Cartel-linked buyers.","impact":"Terry's death exposed the gunwalking scandal, triggering congressional investigations, a 2012 Justice Department inspector general report, and a lasting rift over US arms flows fueling Mexico's cartels.","state":"US","city":"Peck Canyon, near Rio Rico, Arizona","lat":31.45,"lng":-111.05,"cartels":["sinaloa","us_government"],"figures":["Brian Terry"],"type":"killing","importance":3,"confidence":"high","sources":["https://www.justice.gov/oig/reports/2012/s1209.pdf","https://en.wikipedia.org/wiki/Brian_Terry","https://en.wikipedia.org/wiki/ATF_gunwalking_scandal"]},{"id":"2010-marisela-escobedo-killed","date":"2010-12-16","precision":"day","title":"Activist Marisela Escobedo shot outside Chihuahua palace","summary":"Marisela Escobedo Ortiz, who had spent two years hunting the killer of her 16-year-old daughter Rubí Frayre after a court acquitted confessed murderer Sergio Barraza, was shot in the head in front of the Chihuahua state Government Palace during her protest sit-in. Barraza, who had joined Los Zetas, was blamed for ordering the killing; he died in a 2012 shootout with the military in Zacatecas.","impact":"Her murder on camera at the seat of state power became the era's starkest symbol of impunity and of the fusion between femicide, organized crime and judicial failure in Chihuahua.","state":"CHH","city":"Chihuahua","lat":28.6353,"lng":-106.0889,"cartels":["zetas","government"],"figures":["Marisela Escobedo Ortiz","Rubí Marisol Frayre Escobedo","Sergio Rafael Barraza Bocanegra"],"type":"killing","importance":3,"confidence":"high","sources":["https://www.eluniversal.com.mx/notas/731179.html","https://en.wikipedia.org/wiki/Marisela_Escobedo_Ortiz"]},{"id":"2011-zetas-vs-sinaloa-gulf-coahuila-zacatecas","date":"2011-01-01","precision":"year","title":"Zetas battle Sinaloa–Gulf coalition across Coahuila and Zacatecas","summary":"Through 2011 and 2012 the Zetas fought the allied Gulf and Sinaloa cartels for the northern corridor linking Zacatecas and Coahuila to the Texas border. Sinaloa's push into the Torreón-Gómez Palacio (La Laguna) area made Torreón one of Mexico's deadliest cities; in Zacatecas federal forces killed 15 Zetas and arrested 17 at Fresnillo on 1 July 2011 and some 80 gunmen, presumed Gulf Cartel, occupied Juchipila for about five hours on 14 September 2011, while the Zetas' grip on Coahuila's border towns rested on captured police and prisons. In 2012 Iván Velázquez 'El Talibán' broke away and allied with the Gulf against Z-40.","impact":"This war produced the era's bloodiest episodes in the region (Allende, Piedras Negras, Cadereyta) and left Zacatecas fragmented among Zetas remnants, Talibanes and Sinaloa cells for the following decade.","state":"COA","city":"Torreón","lat":25.5428,"lng":-103.4068,"cartels":["zetas","sinaloa","gulf","talibanes"],"figures":["Heriberto Lazcano Lazcano 'El Lazca'","Miguel Ángel Treviño Morales 'Z-40'","Joaquín 'El Chapo' Guzmán"],"type":"battle","importance":4,"confidence":"medium","sources":["https://law.utexas.edu/wp-content/uploads/sites/11/2017/11/2017-HRC-coahuilareport-EN.pdf","https://insightcrime.org/mexico-organized-crime-news/zetas-profile/","https://en.wikipedia.org/wiki/Timeline_of_the_Mexican_drug_war"]},{"id":"2011-jaime-zapata-killing","date":"2011-02-15","precision":"day","title":"Zetas ambush ICE agents on Highway 57; Jaime Zapata killed","summary":"Zetas gunmen forced a U.S. government armoured SUV off Federal Highway 57 near Santa María del Río, San Luis Potosí, and opened fire even after the occupants identified themselves as U.S. diplomats. Immigration and Customs Enforcement agent Jaime Zapata was killed and agent Víctor Ávila wounded. Arrests followed within weeks, including cell leader Julián Zapata Espinoza 'El Piolín'; Zetas commander Jesús Enrique Rejón Aguilar 'El Mamito' was captured in July 2011.","impact":"The first killing of a U.S. federal agent in Mexico since Camarena triggered a binational task force and sharpened U.S. pressure on the Zetas. The murder rifle was traced to Texas straw purchaser Otilio Osorio, whom ATF had identified months earlier, feeding the congressional controversy over ATF gun-walking and Fast and Furious.","state":"SLP","city":"Santa María del Río","lat":21.8,"lng":-100.7333,"cartels":["zetas","us_government"],"figures":["Jaime Zapata","Víctor Ávila","Julián Zapata Espinoza 'El Piolín'","Jesús Enrique Rejón Aguilar 'El Mamito'"],"type":"attack","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Jaime_Zapata","https://en.wikipedia.org/wiki/Timeline_of_the_Mexican_drug_war"]},{"id":"2011-knights-templar-founded","date":"2011-03-01","precision":"month","title":"Knights Templar cartel announces itself in Michoacán","summary":"In March 2011 dozens of narcomantas appeared in Morelia, Apatzingán, Zitácuaro and other Michoacán towns announcing that Los Caballeros Templarios would take over the self-proclaimed protective role of La Familia Michoacana. The group was a breakaway led by Nazario Moreno 'El Chayo' (officially declared dead in December 2010 but alive), Servando Gómez 'La Tuta', Enrique Plancarte and Dionisio Loya Plancarte; its internal code dates the order's birth to 8 March 2011.","impact":"Split La Familia in two and created the pseudo-religious organization that dominated Michoacán's extortion, methamphetamine and iron-ore economies until 2014, provoking the autodefensa uprising.","state":"MIC","city":"Morelia","lat":19.706,"lng":-101.195,"cartels":["templarios","familia_michoacana"],"figures":["Nazario Moreno González 'El Chayo'","Servando Gómez Martínez 'La Tuta'","Enrique Plancarte Solís 'Kike'","Dionisio Loya Plancarte 'El Tío'"],"type":"formation","importance":4,"confidence":"high","sources":["https://archivo.eluniversal.com.mx/estados/2014/los-caballeros-templarios-el-cartel-39religioso-39-979354.html","https://insightcrime.org/mexico-organized-crime-news/knights-templar-profile/","https://es.wikipedia.org/wiki/C%C3%A1rtel_de_los_Caballeros_Templarios"]},{"id":"2011-allende-massacre","date":"2011-03-18","precision":"day","title":"Zetas raze Allende, Coahuila, killing dozens over DEA leak","summary":"Starting on the night of 18 March 2011 and continuing for about three days, Zetas under Miguel Ángel and Omar Treviño swept through Allende and neighbouring towns, seizing relatives and associates of Zetas operatives from Mario Alfonso 'Poncho' Cuéllar's cell who had become DEA informants, sacking and burning some 40 houses and seven ranches and incinerating victims at a ranch outside town. Coahuila prosecutors officially counted only 28 victims; ProPublica documented at least 60 killed or disappeared, El Colegio de México estimated more than 100 and possibly near 300, and municipal police were found to have taken part.","impact":"One of the war's largest civilian massacres went almost unreported for years; ProPublica later showed that informant phone data the DEA shared with a vetted Mexican Federal Police unit leaked to the Zetas and triggered it, making Allende a byword for impunity and for the risks of U.S.-Mexico intelligence sharing.","state":"COA","city":"Allende","lat":28.3421,"lng":-100.8517,"cartels":["zetas"],"figures":["Miguel Ángel Treviño Morales 'Z-40'","Omar Treviño Morales 'Z-42'"],"type":"massacre","importance":4,"confidence":"high","sources":["https://nsarchive.gwu.edu/briefing-book/mexico/2021-03-18/allende-massacre-decade-impunity","https://justiceinmexico.org/remembering-allende-massacre/","https://www.propublica.org/article/chilling-new-report-cites-greater-death-toll-in-allende-massacre"]},{"id":"2011-sicilia-son-killed-peace-movement","date":"2011-03-28","precision":"day","title":"Poet Javier Sicilia's son murdered; peace movement born","summary":"On 28 March 2011 the bodies of Juan Francisco Sicilia Ortega, son of poet Javier Sicilia, and six companions were found in a car in Temixco, Morelos; they had been abducted from a bar and suffocated by members of the Cártel del Pacífico Sur, a Beltrán Leyva remnant. Sicilia's public grief launched the Movimiento por la Paz con Justicia y Dignidad, which marched from Cuernavaca to a rally of up to 200,000 people in Mexico City's Zócalo on 8 May 2011.","impact":"Turned the war's victims into a political force, pushed President Calderón into televised dialogues at Chapultepec Castle in June 2011 and led to Mexico's 2013 General Victims Law.","state":"MOR","city":"Temixco","lat":18.8506,"lng":-99.2278,"cartels":["pacifico_sur","beltran_leyva"],"figures":["Javier Sicilia","Juan Francisco Sicilia Ortega","Felipe Calderón Hinojosa"],"type":"killing","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Javier_Sicilia","https://es.wikipedia.org/wiki/Movimiento_por_la_Paz_con_Justicia_y_Dignidad"]},{"id":"2011-san-fernando-mass-graves","date":"2011-04-06","precision":"day","title":"San Fernando mass graves: 193 bodies of bus passengers, migrants","summary":"On 6 April 2011 Mexican forces exhumed the first 59 corpses from clandestine graves at La Joya ranch in San Fernando, Tamaulipas, the municipality where 72 migrants had been massacred in August 2010. Excavations through early June recovered 193 bodies from 47 graves; most victims had been pulled off intercity buses on Highway 101 by Zetas, who killed those who refused to work for them. Sixteen San Fernando municipal police were jailed within days, and documents later showed police handed passengers over to the cartel.","impact":"Confirmed systematic Zetas kidnapping of travellers and migrants with police complicity, prompted mass arrests including San Fernando officers and cell leaders 'El Kilo' and 'El Wache', and became a central case in Mexico's crisis of the disappeared.","state":"TAM","city":"San Fernando","lat":24.8478,"lng":-98.1567,"cartels":["zetas"],"figures":["Édgar Huerta Montiel 'El Wache'","Martín Omar Estrada Luna 'El Kilo'"],"type":"discovery","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/2011_San_Fernando_massacre","https://www.npr.org/2014/12/22/372579429/mexican-police-helped-cartel-massacre-193-migrants-documents-show"]},{"id":"2011-durango-mass-graves","date":"2011-04-11","precision":"day","title":"Mass graves in Durango city yield more than 300 bodies","summary":"Beginning in April 2011 soldiers and police excavated clandestine graves in residential lots across Durango city, including an auto-repair yard that alone held 89 bodies. By February 2012 at least 340 corpses had been recovered from seven sites, then the largest such find in Mexico. Authorities attributed most of the killings to internal feuding within the Sinaloa Cartel's Durango structure and its war with Zetas and Beltrán Leyva cells.","impact":"Showed that Sinaloa Cartel heartland, not only Zetas territory, concealed industrial-scale disappearances, and overwhelmed Durango's forensic capacity, leaving most victims unidentified.","state":"DUR","city":"Durango","lat":24.0277,"lng":-104.6532,"cartels":["sinaloa"],"figures":[],"type":"discovery","importance":3,"confidence":"medium","sources":["https://justiceinmexico.org/clandestine-grave-discovered-in-durango-nearly-300-bodies-found-since-april-2011/","http://edition.cnn.com/2011/WORLD/americas/04/21/mexico.durango.mass.grave/index.html","https://en.wikipedia.org/wiki/Durango_massacres"]},{"id":"2011-chango-mendez-captured","date":"2011-06-21","precision":"day","title":"La Familia boss 'El Chango' Méndez captured in Aguascalientes","summary":"Federal Police arrested José de Jesús Méndez Vargas 'El Chango', leader of La Familia Michoacana, at a highway checkpoint in Aguascalientes on 21 June 2011. Méndez had headed the faction that lost the split with the Knights Templar, and the government declared that his capture 'destroyed' La Familia's command structure.","impact":"Effectively ended the original La Familia Michoacana as a major cartel and left the Knights Templar dominant in Michoacán; a remnant survived in the Estado de México-Guerrero borderlands under the Hurtado brothers.","state":"AGU","city":"Aguascalientes","lat":21.8853,"lng":-102.2916,"cartels":["familia_michoacana","templarios","government"],"figures":["José de Jesús Méndez Vargas 'El Chango'"],"type":"capture","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Jos%C3%A9_de_Jes%C3%BAs_M%C3%A9ndez_Vargas"]},{"id":"2011-el-diego-captured","date":"2011-07-29","precision":"day","title":"La Línea chief 'El Diego', blamed for 1,500 killings, captured","summary":"Federal Police captured José Antonio Acosta Hernández 'El Diego', head of the Juárez Cartel's armed wing La Línea, in Chihuahua city on 29 July 2011. He admitted ordering some 1,500 murders, including the January 2010 Villas de Salvárcar student massacre, the March 2010 killing of U.S. consulate employees and the July 2010 car bomb in Ciudad Juárez. Extradited in March 2012, he was sentenced to multiple life terms in El Paso that April.","impact":"Removed the operational commander of the Juárez war at its height and, together with the Sinaloa Cartel's advance, preceded the steep fall in Ciudad Juárez homicides between 2011 and 2012.","state":"CHH","city":"Chihuahua","lat":28.6353,"lng":-106.0889,"cartels":["juarez","government"],"figures":["José Antonio Acosta Hernández 'El Diego'"],"type":"capture","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/La_L%C3%ADnea_(gang)","http://www.cnn.com/2012/04/06/justice/mexico-drug-gang-leader/index.html"]},{"id":"2011-casino-royale-arson","date":"2011-08-25","precision":"day","title":"Zetas torch Casino Royale in Monterrey, killing 52","summary":"On the afternoon of 25 August 2011 a Zetas commando of eight to twelve gunmen doused the Casino Royale in Monterrey with gasoline and set it ablaze after its owners refused extortion payments; 52 people, most of them women, died trapped inside. President Felipe Calderón called it an act of terror and declared three days of national mourning, and a video later showed the brother of Monterrey mayor Fernando Larrazábal collecting cash at casinos.","impact":"The deadliest single attack on civilians of the Calderón years made Monterrey's collapse a national emergency, triggered a federal surge in Nuevo León and hardened public rejection of the Zetas.","state":"NLE","city":"Monterrey","lat":25.6866,"lng":-100.3161,"cartels":["zetas"],"figures":["Felipe Calderón Hinojosa","Fernando Larrazábal Bretón"],"type":"attack","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/2011_Monterrey_casino_attack"]},{"id":"2011-boca-del-rio-35-bodies-matazetas","date":"2011-09-20","precision":"day","title":"35 bodies dumped in Boca del Río as 'Matazetas' announce CJNG","summary":"At rush hour on 20 September 2011 gunmen abandoned two trucks holding 35 bodies under an overpass beside the Plaza Las Américas mall in Boca del Río, Veracruz, with a message declaring the victims Zetas and the territory under a 'new proprietor'. On 27 September five masked men calling themselves 'Matazetas' released a video vowing to exterminate the Zetas; the group was the Jalisco New Generation Cartel, born from the Milenio Cartel's split after Ignacio Coronel's death in July 2010. More bodies appeared across Veracruz in early October, and the Navy took over policing under 'Veracruz Seguro'.","impact":"CJNG's national debut opened the Veracruz front of the Zetas war and exposed the security collapse of the state under Governor Javier Duarte.","state":"VER","city":"Boca del Río","lat":19.1058,"lng":-96.1076,"cartels":["cjng","zetas","milenio"],"figures":["Nemesio Oseguera Cervantes 'El Mencho'","Javier Duarte de Ochoa"],"type":"massacre","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Jalisco_New_Generation_Cartel","https://insightcrime.org/mexico-organized-crime-news/jalisco-cartel-new-generation/"]},{"id":"2011-guadalajara-arcos-del-milenio-26-bodies","date":"2011-11-24","precision":"day","title":"26 bodies left at Guadalajara's Arcos del Milenio","summary":"On 24 November 2011 three vehicles holding 26 bound and asphyxiated men were found abandoned beside the Arcos del Milenio monument in Guadalajara, two days before the city opened the International Book Fair. Messages signed 'Milenio Zetas', the Zetas and their local allies in the Milenio Cartel's La Resistencia faction, framed the killings as retaliation against the Sinaloa Cartel and CJNG; only a handful of victims had criminal records, the rest being workers such as a cook, a mechanic and a dentist. Sixteen burned bodies had been dumped in Culiacán, Sinaloa, the previous day.","impact":"Brought the Zetas-CJNG/Sinaloa war into Mexico's second city and signalled that Jalisco, long a quiet Sinaloa rear base, was now contested territory.","state":"JAL","city":"Guadalajara","lat":20.6597,"lng":-103.3496,"cartels":["zetas","milenio","cjng","sinaloa"],"figures":[],"type":"massacre","importance":3,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Jalisco_New_Generation_Cartel","https://en.wikipedia.org/wiki/Timeline_of_the_Mexican_drug_war"]},{"id":"2012-apodaca-prison-massacre-escape","date":"2012-02-19","precision":"day","title":"Apodaca prison: Zetas kill 44 Gulf inmates and 37 escape","summary":"Before dawn on 19 February 2012 Zetas inmates at the Apodaca state prison outside Monterrey, let through by guards, stormed a cell block and beat and stabbed to death 44 Gulf Cartel prisoners while 37 Zetas (first reported as 30) walked out under cover of the riot. Investigators found the director and guards had been on the cartel's payroll, receiving monthly bribes; 21 former prison officials were arrested in March 2012.","impact":"Exposed complete cartel control of Nuevo León's prisons and fed the pattern of mass Zetas escapes that continued at Piedras Negras months later.","state":"NLE","city":"Apodaca","lat":25.7817,"lng":-100.1886,"cartels":["zetas","gulf"],"figures":["Rodrigo Medina de la Cruz"],"type":"massacre","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Apodaca_prison_riot","https://www.aljazeera.com/news/americas/2012/02/2012219165349443681.html"]},{"id":"2012-nuevo-laredo-hangings","date":"2012-05-04","precision":"day","title":"Nine bodies hanged from Nuevo Laredo bridge; 14 beheaded","summary":"In the early hours of 4 May 2012 nine bodies, four women and five men, were found hanging from an overpass on Nuevo Laredo's Highway 85D bypass beside a Zetas message calling them Gulf Cartel members; hours later 14 decapitated bodies were left in a vehicle in front of the customs office, their heads in coolers outside city hall, with a message attributed to 'El Chapo' Guzmán. It followed the 17 April dumping of 14 dismembered men by Sinaloa's incoming forces.","impact":"Marked the Sinaloa-Gulf alliance's frontal assault on the Zetas' home plaza and the Interstate 35 corridor, one of the most visible episodes of the 2012 war of mutilated messages.","state":"TAM","city":"Nuevo Laredo","lat":27.4763,"lng":-99.5164,"cartels":["zetas","sinaloa","gulf"],"figures":["Joaquín 'El Chapo' Guzmán","Miguel Ángel Treviño Morales 'Z-40'"],"type":"massacre","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/2012_Nuevo_Laredo_massacres"]},{"id":"2012-cadereyta-49-bodies","date":"2012-05-13","precision":"day","title":"49 mutilated bodies dumped on highway at Cadereyta","summary":"On 13 May 2012 authorities found 43 men and six women, decapitated and with hands and feet removed, beside Federal Highway 40 near San Juan in Cadereyta Jiménez outside Monterrey, under a Zetas banner. A Zetas cell leader captured days later, Jesús Daniel Elizondo Ramírez 'El Loco', said Heriberto Lazcano and Miguel Treviño had ordered the display to sow terror amid the war with the Gulf-Sinaloa alliance; most victims were never identified, and forensic teams later confirmed some as Central American migrants.","impact":"The third mass dumping in a month made the Zetas' terror strategy a global story and deepened the migrant-disappearance crisis in northeastern Mexico.","state":"NLE","city":"Cadereyta Jiménez","lat":25.5897,"lng":-100.0006,"cartels":["zetas","gulf"],"figures":["Heriberto Lazcano Lazcano 'El Lazca'","Miguel Ángel Treviño Morales 'Z-40'","Jesús Daniel Elizondo Ramírez 'El Loco'"],"type":"massacre","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Cadereyta_Jim%C3%A9nez_massacre"]},{"id":"2012-el-coss-captured","date":"2012-09-12","precision":"day","title":"Navy captures Gulf Cartel leader 'El Coss' in Tampico","summary":"Marines arrested Jorge Eduardo Costilla Sánchez 'El Coss', top leader of the Gulf Cartel and head of its Metros faction, without a shot in Tampico's Lomas de Rosales neighbourhood on 12 September 2012, nine days after the Navy detained Mario Cárdenas Guillén 'El Gordo', leader of the rival Rojos faction, in Altamira. Costilla was extradited to the United States in September 2015.","impact":"Decapitated both wings of the Gulf Cartel within ten days, opening the leadership vacuum and Metros-versus-Ciclones infighting that fragmented Tamaulipas through the following decade.","state":"TAM","city":"Tampico","lat":22.2331,"lng":-97.8611,"cartels":["gulf","government"],"figures":["Jorge Eduardo Costilla Sánchez 'El Coss'","Mario Cárdenas Guillén 'El Gordo'"],"type":"capture","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Jorge_Eduardo_Costilla_S%C3%A1nchez","https://insightcrime.org/mexico-organized-crime-news/gulf-cartel-profile/"]},{"id":"2012-piedras-negras-prison-death-camp-escape","date":"2012-09-17","precision":"day","title":"Piedras Negras prison: Zetas death camp and 131-inmate escape","summary":"On 17 September 2012, 131 inmates walked out of the Piedras Negras state prison through a tunnel and the carpentry workshop in a Zetas-organised breakout, the largest of the era. Coahuila investigations made public in 2016, based on testimony from dozens of former prisoners, established that between 2009 and 2012 the Zetas ran the prison as an operations base and extermination site, killing roughly 150 people whose bodies were burned in drums or dissolved in acid; inmates left at night to kidnap victims and manufactured uniforms and body armour inside.","impact":"Became the emblem of state capture in Coahuila under the Moreira governments and a key case in U.S. trials of Zetas commanders and in Mexico's search for the disappeared.","state":"COA","city":"Piedras Negras","lat":28.7003,"lng":-100.5231,"cartels":["zetas"],"figures":["Miguel Ángel Treviño Morales 'Z-40'"],"type":"escape","importance":4,"confidence":"high","sources":["https://insightcrime.org/news/brief/zetas-turned-mexico-prison-mass-grave/","https://www.vice.com/en/article/the-zetas-cartel-turned-a-mexican-prison-into-a-death-camp/","https://law.utexas.edu/wp-content/uploads/sites/11/2017/11/2017-HRC-coahuilareport-EN.pdf"]},{"id":"2012-el-taliban-captured","date":"2012-09-26","precision":"day","title":"Zetas splinter boss 'El Talibán' captured in San Luis Potosí","summary":"Marines acting on U.S. intelligence arrested Iván Velázquez Caballero 'El Talibán' (Z-50) in San Luis Potosí city on 26 September 2012. Since late 2011 he had publicly denounced Miguel Treviño 'Z-40' for betraying comrades, and by mid-2012 he had broken away and allied his Zacatecas-San Luis Potosí faction with the Gulf Cartel; the feud drove a wave of massacres across the north. He was extradited in November 2013, pleaded guilty in Laredo in April 2014 and was sentenced to 30 years in 2017.","impact":"Confirmed the first major internal rupture of the Zetas and seeded Los Talibanes, the group that has contested Zacatecas and San Luis Potosí ever since.","state":"SLP","city":"San Luis Potosí","lat":22.1565,"lng":-100.9855,"cartels":["zetas","talibanes","gulf","government"],"figures":["Iván Velázquez Caballero 'El Talibán'","Miguel Ángel Treviño Morales 'Z-40'"],"type":"capture","importance":3,"confidence":"high","sources":["https://www.aljazeera.com/news/2012/9/27/mexico-says-drug-leader-el-taliban-captured","https://www.justice.gov/usao-sdtx/pr/zeta-commander-taliban-facing-trial-us"]},{"id":"2012-lazcano-killed-progreso","date":"2012-10-07","precision":"day","title":"Zetas founder Heriberto Lazcano killed by marines in Progreso","summary":"Responding to a report of armed men at a baseball field in Progreso, Coahuila, marines killed two gunmen in a firefight on 7 October 2012; fingerprints identified one as Heriberto Lazcano 'El Lazca', the former special-forces soldier who led the Zetas. Before the Navy could announce it, armed men seized the body from a funeral home in nearby Sabinas; it has never been recovered.","impact":"Ended the Zetas' founding generation and left Miguel Treviño 'Z-40' in sole command, accelerating the organisation's fragmentation.","state":"COA","city":"Progreso","lat":27.4283,"lng":-100.9886,"cartels":["zetas","government"],"figures":["Heriberto Lazcano Lazcano 'El Lazca'","Miguel Ángel Treviño Morales 'Z-40'"],"type":"killing","importance":4,"confidence":"high","sources":["https://www.theguardian.com/world/2012/oct/09/zetas-boss-heriberto-lazcano-death-confirmed","https://en.wikipedia.org/wiki/Heriberto_Lazcano_Lazcano"]},{"id":"2012-pena-nieto-inaugurated","date":"2012-12-01","precision":"day","title":"Peña Nieto takes office, pledging to cut violence not chase capos","summary":"Enrique Peña Nieto was sworn in on 1 December 2012 amid riots in central Mexico City, returning the PRI to power after Felipe Calderón's six-year offensive left more than 60,000 dead. He signed the Pacto por México with the opposition the next day and moved public security under the Interior Ministry, promising a 40,000-strong gendarmerie, a focus on reducing homicide, kidnapping and extortion rather than kingpin captures, and a lower public profile for the drug war.","impact":"Reframed the government's security discourse and centralised command, though in practice the kingpin strategy continued (Z-40, El Chapo), the gendarmerie shrank to 5,000 and violence rebounded after 2014.","state":"CMX","city":"Mexico City","lat":19.4326,"lng":-99.1332,"cartels":["government"],"figures":["Enrique Peña Nieto","Miguel Ángel Osorio Chong","Felipe Calderón Hinojosa"],"type":"policy","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Enrique_Pe%C3%B1a_Nieto","https://crsreports.congress.gov/product/pdf/R/R41576"]},{"id":"2012-hsbc-money-laundering-settlement","date":"2012-12-11","precision":"day","title":"HSBC pays record $1.9 billion over Sinaloa Cartel laundering","summary":"On 11 December 2012 HSBC admitted in a deferred prosecution agreement filed in Brooklyn federal court that failed controls had let the Sinaloa Cartel and Colombia's Norte del Valle cartel launder at least $881 million through its Mexican and U.S. units, which moved some $7 billion in bulk cash from Mexico in 2007-2008. The bank forfeited $1.256 billion and paid $665 million in civil penalties, then a record for anti-money-laundering violations, but no executives were charged.","impact":"The largest bank penalty of its kind exposed how cartel proceeds moved through the formal financial system and ignited the 'too big to jail' debate in the United States.","state":"US","city":"Brooklyn, New York","lat":40.6957,"lng":-73.9895,"cartels":["sinaloa","us_government"],"figures":["Lanny A. Breuer","Loretta Lynch"],"type":"corruption","importance":3,"confidence":"high","sources":["https://www.justice.gov/opa/pr/hsbc-holdings-plc-and-hsbc-bank-usa-na-admit-anti-money-laundering-and-sanctions-violations","https://www.hsgac.senate.gov/subcommittees/investigations/hearings/us-vulnerabilities-to-money-laundering-drugs-and-terrorist-financing-hsbc-case-history","https://en.wikipedia.org/wiki/HSBC"]},{"id":"2013-upoeg-guerrero-autodefensas","date":"2013-01-05","precision":"day","title":"UPOEG community police rise in Ayutla, Guerrero's Costa Chica","summary":"On the night of 5-6 January 2013 hundreds of masked, armed villagers from the Unión de Pueblos y Organizaciones del Estado de Guerrero (UPOEG) seized Ayutla de los Libres and Tecoanapa, set up checkpoints and detained dozens of suspected criminals after kidnappings of local community figures, including a village commissioner and the priest of El Mezón. Building on Guerrero's older CRAC community-police tradition, the uprising led by Bruno Plácido spread to dozens of municipalities within weeks.","impact":"Launched the 2013 wave of armed self-defence forces that soon swept Michoacán and forced federal and state governments to negotiate with armed civilians.","state":"GRO","city":"Ayutla de los Libres","lat":16.9659,"lng":-99.0963,"cartels":["autodefensas"],"figures":["Bruno Plácido Valerio"],"type":"formation","importance":3,"confidence":"medium","sources":["https://www.milenio.com/politica/comunidad/movimiento-upoeg-cumple-diez-anos-autodefensa-armada-guerrero","https://expansion.mx/nacional/2013/02/01/ayutla-de-los-libres-el-lugar-donde-los-civiles-ejercen-la-justicia"]},{"id":"2013-michoacan-autodefensas-rise","date":"2013-02-24","precision":"day","title":"Autodefensas rise in Tepalcatepec and La Ruana against Templarios","summary":"On 24 February 2013 ranchers and lime growers in Tepalcatepec, led by physician José Manuel Mireles, and in La Ruana (Buenavista), led by Hipólito Mora, took up arms and expelled the Knights Templar, who had extorted and terrorised the Tierra Caliente for years. Organised later as the Consejo General de Autodefensas, the movement spread town by town and by early 2014 had reached Apatzingán.","impact":"Broke the Templarios' hold on Michoacán's Tierra Caliente and forced the federal takeover of the state in January 2014, but also opened the militias to infiltration by rival cartels.","state":"MIC","city":"Tepalcatepec","lat":19.1921,"lng":-102.8454,"cartels":["autodefensas","templarios"],"figures":["José Manuel Mireles Valverde","Hipólito Mora Chávez","Estanislao Beltrán Torres 'Papá Pitufo'"],"type":"formation","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Grupos_de_autodefensa_comunitaria","https://en.wikipedia.org/wiki/Hip%C3%B3lito_Mora","https://en.wikipedia.org/wiki/Jos%C3%A9_Manuel_Mireles_Valverde"]},{"id":"2013-heaven-bar-mass-kidnapping","date":"2013-05-26","precision":"day","title":"Heaven bar mass kidnapping in Mexico City's Zona Rosa","summary":"On the morning of 26 May 2013 armed men took 13 young people (12 were first reported missing), several of them children of Tepito underworld figures, from the after-hours bar Heaven on Calle Lancaster in the Zona Rosa, steps from Paseo de la Reforma. On 22 August their bodies were found in a mass grave at a ranch in Tlalmanalco, Estado de México. Prosecutors tied the crime to a drug-retail feud between La Unión Insurgentes and Tepito dealers, the milieu from which La Unión Tepito emerged.","impact":"Shattered the capital's image of immunity from cartel-style violence and foreshadowed La Unión Tepito's rise to dominance of Mexico City's criminal market.","state":"CMX","city":"Mexico City (Zona Rosa)","lat":19.427,"lng":-99.1626,"cartels":["union_tepito"],"figures":["Miguel Ángel Mancera"],"type":"massacre","importance":3,"confidence":"medium","sources":["https://insightcrime.org/mexico-organized-crime-news/la-union-tepito/"]},{"id":"2013-z40-trevino-captured","date":"2013-07-15","precision":"day","title":"Marines capture Zetas leader Miguel Treviño 'Z-40' near Nuevo Laredo","summary":"At about 3:45 a.m. on 15 July 2013 a Navy Black Hawk helicopter and ground team intercepted a pickup on a dirt road in Anáhuac municipality, Nuevo León, some 27 km from Nuevo Laredo, and arrested Miguel Ángel Treviño Morales 'Z-40', Zetas commander since Lazcano's death, with two aides, about $2 million in cash and eight weapons, without a shot fired. His brother Omar 'Z-42' succeeded him.","impact":"The Peña Nieto government's first major kingpin capture removed Mexico's most feared trafficker and hastened the Zetas' break-up into the Cártel del Noreste and Vieja Escuela factions.","state":"NLE","city":"Anáhuac","lat":27.2409,"lng":-100.1352,"cartels":["zetas","government"],"figures":["Miguel Ángel Treviño Morales 'Z-40'","Omar Treviño Morales 'Z-42'"],"type":"capture","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Miguel_Trevi%C3%B1o_Morales","https://www.nytimes.com/2013/07/17/world/americas/capture-of-mexican-crime-boss-appears-to-end-a-brutal-chapter.html","https://www.washingtonpost.com/world/the_americas/us-federal-official-leader-of-mexicos-zetas-drug-cartel-captured/2013/07/15/85376a4c-edab-11e2-bb32-725c8351a69e_story.html"]},{"id":"2013-caro-quintero-released","date":"2013-08-09","precision":"day","title":"Court frees Rafael Caro Quintero after 28 years for Camarena murder","summary":"In the early hours of 9 August 2013 Rafael Caro Quintero, co-founder of the Guadalajara Cartel convicted for the 1985 torture-murder of DEA agent Enrique 'Kiki' Camarena, walked out of the Puente Grande prison in Jalisco after a federal appeals panel, the Primer Tribunal Colegiado en Materia Penal del Tercer Circuito, ruled that the Camarena murder should have been tried in state rather than federal court. Washington protested, a federal arrest warrant on U.S. charges was issued on 14 August and the Supreme Court later voided the ruling, but Caro Quintero had vanished.","impact":"Provoked a diplomatic crisis with the United States, exposed judicial corruption and returned a founding capo to the Sonora-Sinaloa drug trade until his recapture in 2022.","state":"JAL","city":"Puente Grande (Tonalá)","lat":20.5692,"lng":-103.1542,"cartels":["guadalajara","sinaloa","government","us_government"],"figures":["Rafael Caro Quintero","Enrique 'Kiki' Camarena"],"type":"trial","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Rafael_Caro_Quintero","https://es.wikipedia.org/wiki/Rafael_Caro_Quintero"]},{"id":"2013-x20-ramirez-trevino-captured","date":"2013-08-17","precision":"day","title":"Army captures Gulf Cartel chief Mario Ramírez Treviño 'X-20'","summary":"On the morning of 17 August 2013 soldiers detained Mario Armando Ramírez Treviño 'X-20', who had run the Gulf Cartel's Reynosa Metros faction since the September 2011 killing of Samuel Flores Borrego 'Metro 3' and claimed overall leadership after the September 2012 arrests of Costilla and Cárdenas, cementing it in the March 2013 Reynosa gun battles that killed rival Miguel 'El Gringo' Villarreal. Official statements placed the arrest in Río Bravo while other accounts said Reynosa. He was flown to Mexico City and later extradited to the United States.","impact":"Left the Gulf Cartel without a recognised overall leader and intensified the Metros-Ciclones split that fuelled the 2014 bloodshed in Tamaulipas.","state":"TAM","city":"Río Bravo","lat":25.9868,"lng":-98.0947,"cartels":["gulf","government"],"figures":["Mario Armando Ramírez Treviño 'X-20'"],"type":"capture","importance":3,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Mario_Ram%C3%ADrez_Trevi%C3%B1o","https://es.wikipedia.org/wiki/Mario_Ram%C3%ADrez_Trevi%C3%B1o","https://insightcrime.org/mexico-organized-crime-news/gulf-cartel-profile/"]},{"id":"2013-lazaro-cardenas-port-takeover","date":"2013-11-04","precision":"day","title":"Navy and army seize control of Lázaro Cárdenas port from Templarios","summary":"On 4 November 2013 federal forces took over security, customs and municipal policing at Lázaro Cárdenas, Mexico's largest Pacific container port, disarming the local police. The Knights Templar had made the port their main revenue source, taxing and exporting illegally mined iron ore to China and importing methamphetamine precursors; the move followed Templarios attacks on CFE power installations that blacked out much of Michoacán on 27 October and the July ambush that killed Vice Admiral Carlos Salazar Ramonet.","impact":"The first step in the federal takeover of Michoacán, it cut the Templarios' iron-ore lifeline and led to seizures of more than 100,000 tonnes of ore in 2014.","state":"MIC","city":"Lázaro Cárdenas","lat":17.9583,"lng":-102.2,"cartels":["government","templarios"],"figures":["Enrique Peña Nieto","Servando Gómez Martínez 'La Tuta'"],"type":"policy","importance":3,"confidence":"high","sources":["https://insightcrime.org/mexico-organized-crime-news/knights-templar-profile/","https://www.economist.com/the-economist-explains/2014/03/09/why-mexican-drug-traffickers-started-smuggling-iron-ore-to-china"]},{"id":"2013-macho-prieto-killed-puerto-penasco","date":"2013-12-18","precision":"day","title":"Sinaloa enforcer 'El Macho Prieto' killed in Puerto Peñasco shootout","summary":"Before dawn on 18 December 2013 marines backed by two Black Hawk helicopters raided a beachfront condominium at the Bella Sirena resort in Puerto Peñasco, Sonora; a battle of at least four hours left Gonzalo Inzunza Inzunza 'El Macho Prieto', chief gunman for Ismael 'El Mayo' Zambada and boss of the Sonora-Mexicali corridor, and four others dead. Tourists sheltered as helicopters fired on fleeing vehicles; gunmen carried off Inzunza's body, and authorities confirmed his death through DNA at the scene.","impact":"Removed one of the Sinaloa Cartel's most violent operators and destabilised its Sonora structure, helping open the state to the Caborca-Chapitos feuds of later years.","state":"SON","city":"Puerto Peñasco","lat":31.3167,"lng":-113.5333,"cartels":["sinaloa","government"],"figures":["Gonzalo Inzunza Inzunza 'El Macho Prieto'","Ismael 'El Mayo' Zambada"],"type":"killing","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Gonzalo_Inzunza_Inzunza"]},{"id":"2014-castillo-michoacan-commissioner","date":"2014-01-15","precision":"day","title":"Peña Nieto names Alfredo Castillo federal commissioner for Michoacán","summary":"By decree of 15 January 2014 President Peña Nieto created the Commission for Security and Integral Development of Michoacán and named Alfredo Castillo Cervantes, until then head of the consumer agency Profeco, to run it, two days after soldiers killed civilians while trying to disarm autodefensas in Antúnez. Castillo effectively displaced Governor Fausto Vallejo, negotiated the militias' legalisation and oversaw the offensive that killed or captured most Templarios leaders.","impact":"An unprecedented federal 'viceroyalty' over a state that sidelined elected authorities and shaped the demobilisation, and later criminalisation, of the autodefensas.","state":"MIC","city":"Morelia","lat":19.706,"lng":-101.195,"cartels":["government","autodefensas","templarios"],"figures":["Alfredo Castillo Cervantes","Miguel Ángel Osorio Chong","Fausto Vallejo Figueroa"],"type":"policy","importance":3,"confidence":"high","sources":["https://www.animalpolitico.com/2014/01/alfredo-castillo-deja-la-profeco-es-el-nuevo-comisionado-de-seguridad-en-michoacan","https://www.proceso.com.mx/nacional/2014/1/21/metaconstitucional-el-nombramiento-de-alfredo-castillo-128101.html"]},{"id":"2014-el-chapo-captured-mazatlan","date":"2014-02-22","precision":"day","title":"El Chapo captured in a Mazatlán beachfront condo","summary":"At about 6:40 a.m. on 22 February 2014 marines, working with DEA and U.S. Marshals intelligence, arrested Joaquín 'El Chapo' Guzmán without a shot in room 401 of the Miramar condominium on Mazatlán's malecón, ending a 13-year manhunt that began with his 2001 escape. Days earlier he had fled a Culiacán safe house through a tunnel beneath a bathtub into the city sewers.","impact":"The biggest capture of the drug war left Ismael 'El Mayo' Zambada in charge of the Sinaloa Cartel and set the stage for Guzmán's second escape from Altiplano in July 2015.","state":"SIN","city":"Mazatlán","lat":23.2494,"lng":-106.4111,"cartels":["sinaloa","government","us_government"],"figures":["Joaquín 'El Chapo' Guzmán","Ismael 'El Mayo' Zambada"],"type":"capture","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Joaqu%C3%ADn_%22El_Chapo%22_Guzm%C3%A1n","https://crsreports.congress.gov/product/pdf/R/R41576"]},{"id":"2014-nazario-moreno-killed","date":"2014-03-09","precision":"day","title":"Nazario 'El Chayo' Moreno killed for real in Tumbiscatío","summary":"Soldiers and marines shot dead Nazario Moreno González, spiritual leader of the Knights Templar, near Tumbiscatío in Michoacán's sierra on 9 March 2014; fingerprints and DNA confirmed the identity of a man the Calderón government had declared killed in Apatzingán in December 2010. Autodefensa leaders had insisted for a year that 'El Chayo' was alive and directing the cartel.","impact":"Ended the myth of the 'saint' of Michoacán, discredited the earlier official account and, with Plancarte's death three weeks later, broke the Templarios' leadership.","state":"MIC","city":"Tumbiscatío","lat":18.5236,"lng":-102.3672,"cartels":["templarios","government","autodefensas"],"figures":["Nazario Moreno González 'El Chayo'"],"type":"killing","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Nazario_Moreno_Gonz%C3%A1lez","https://es.wikipedia.org/wiki/C%C3%A1rtel_de_los_Caballeros_Templarios"]},{"id":"2014-plancarte-killed-colon","date":"2014-03-31","precision":"day","title":"Templarios leader Enrique Plancarte killed in Colón, Querétaro","summary":"Marines killed Enrique Plancarte Solís 'Kike', the Knights Templar's second-in-command and its methamphetamine and finance chief, in a shootout in the town of Colón, Querétaro, on 31 March 2014, far from his Michoacán base. His death came three weeks after Nazario Moreno's and left Servando Gómez 'La Tuta' as the last founding leader at large.","impact":"Completed the collapse of the Templarios' top tier and showed the cartel's leaders scattering into neighbouring states as federal forces and autodefensas closed in.","state":"QUE","city":"Colón","lat":20.7825,"lng":-100.0484,"cartels":["templarios","government"],"figures":["Enrique Plancarte Solís 'Kike'"],"type":"killing","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Enrique_Plancarte_Sol%C3%ADs"]},{"id":"2014-fuerza-rural-autodefensas-legalized","date":"2014-05-10","precision":"day","title":"Michoacán autodefensas registered as state Fuerza Rural","summary":"At a ceremony in Tepalcatepec on 10 May 2014, federal commissioner Alfredo Castillo handed out uniforms and registered weapons as thousands of autodefensa members were incorporated into a new Fuerza Rural under state command, fulfilling the 27 January accord to legalise or demobilise the militias. Leaders such as Estanislao Beltrán 'Papá Pitufo' and Luis Antonio Torres 'El Americano' joined; José Manuel Mireles rejected the terms and was arrested weeks later.","impact":"Formally ended the autonomous self-defence movement but folded fighters with cartel ties into state ranks, sowing the feuds and later criminal groups of Michoacán's Tierra Caliente.","state":"MIC","city":"Tepalcatepec","lat":19.1921,"lng":-102.8454,"cartels":["autodefensas","government","templarios"],"figures":["Alfredo Castillo Cervantes","Estanislao Beltrán Torres 'Papá Pitufo'","José Manuel Mireles Valverde"],"type":"policy","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Grupos_de_autodefensa_comunitaria","https://en.wikipedia.org/wiki/Jos%C3%A9_Manuel_Mireles_Valverde"]},{"id":"2014-sanchez-arellano-captured-tijuana","date":"2014-06-23","precision":"day","title":"Tijuana Cartel heir 'El Ingeniero' arrested watching World Cup","summary":"Soldiers and PGR federal agents arrested Luis Fernando Sánchez Arellano 'El Ingeniero', nephew of the Arellano Félix brothers and leader of the Tijuana Cartel since his uncle Eduardo's arrest in 2008, at a Carl's Jr. restaurant in Tijuana's Mesa de Otay on 23 June 2014 as he watched Mexico play Croatia in the World Cup, wearing a national jersey with his face painted in the team's colours; about $100,000 in cash was seized.","impact":"Removed the last Arellano Félix family boss and left the weakened Tijuana organisation as a junior partner, later absorbed by CJNG as the Cártel de Tijuana Nueva Generación.","state":"BCN","city":"Tijuana","lat":32.5149,"lng":-117.0382,"cartels":["tijuana","government"],"figures":["Luis Fernando Sánchez Arellano 'El Ingeniero'"],"type":"capture","importance":2,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Luis_Fernando_S%C3%A1nchez_Arellano"]},{"id":"2014-mireles-arrested","date":"2014-06-27","precision":"day","title":"Autodefensa leader José Manuel Mireles arrested in La Mira","summary":"Federal police and soldiers detained José Manuel Mireles and dozens of followers on 27 June 2014 in La Mira, in Lázaro Cárdenas municipality, hours after he led an armed group into the town in defiance of the government's registration deadline. Charged with weapons and drug offences, he was flown to a federal prison in Hermosillo, Sonora, and held until May 2017.","impact":"Silenced the movement's most prominent dissident voice and confirmed that the state would tolerate only militias under its own command.","state":"MIC","city":"La Mira","lat":18.035,"lng":-102.3266,"cartels":["autodefensas","government"],"figures":["José Manuel Mireles Valverde","Alfredo Castillo Cervantes"],"type":"capture","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Jos%C3%A9_Manuel_Mireles_Valverde"]},{"id":"2014-tlatlaya-army-killings","date":"2014-06-30","precision":"day","title":"Tlatlaya: soldiers execute suspects after warehouse shootout","summary":"In the early hours of 30 June 2014 soldiers of the 102nd Infantry Battalion killed 22 people at a warehouse in San Pedro Limón, Tlatlaya, Estado de México. The army described a gun battle with kidnappers, but a survivor's testimony and forensic evidence gathered by journalists and the CNDH showed that at least 12 to 15 were shot after surrendering, and a written order to 'take down criminals in hours of darkness' later surfaced.","impact":"The first major extrajudicial-killing scandal of the Peña Nieto era, it eroded the army's credibility weeks before Ayotzinapa and became a test case for military accountability.","state":"MEX","city":"San Pedro Limón, Tlatlaya","lat":18.5828,"lng":-100.3049,"cartels":["government","other"],"figures":["Salvador Cienfuegos Zepeda"],"type":"massacre","importance":4,"confidence":"high","sources":["https://centroprodh.org.mx/2019/06/30/tlatlaya-five-years-of-injustice/?lang=en","https://www.wola.org/2015/07/in-mexicos-tlatlaya-massacre-soldiers-were-ordered-to-take-them-out/"]},{"id":"2014-ayotzinapa-43-iguala","date":"2014-09-26","precision":"day","title":"Ayotzinapa: 43 students disappeared after Iguala police attack","summary":"On the night of 26-27 September 2014 municipal police in Iguala, Guerrero, acting with the Guerreros Unidos gang, attacked buses commandeered by students of the Ayotzinapa rural teachers' college, killing six people and handing 43 students to the gang; they were never seen again. Mayor José Luis Abarca and his wife fled and were arrested in Mexico City on 4 November, and on 7 November Attorney General Jesús Murillo Karam presented the account, later branded the 'historic truth', that the students were burned at the Cocula dump.","impact":"The defining human-rights crisis of the Peña Nieto presidency, it set off nationwide protests, international investigations and years of contested inquiries, and placed Guerrero's Guerreros Unidos-Los Rojos heroin wars at the centre of national attention.","state":"GRO","city":"Iguala","lat":18.3449,"lng":-99.5389,"cartels":["guerreros_unidos","government"],"figures":["José Luis Abarca Velázquez","María de los Ángeles Pineda Villa","Jesús Murillo Karam","Sidronio Casarrubias Salgado"],"type":"massacre","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/2014_Iguala_mass_kidnapping"]},{"id":"2014-hector-beltran-leyva-arrested","date":"2014-10-01","precision":"day","title":"Héctor Beltrán Leyva 'El H' arrested in San Miguel de Allende","summary":"Soldiers arrested Héctor Beltrán Leyva, the last of the brothers still leading the Beltrán Leyva Organization, at a seafood restaurant in San Miguel de Allende, Guanajuato, on 1 October 2014, where he had lived quietly posing as an art dealer and property investor. He was jailed at Altiplano and died of a heart attack in custody in November 2018.","impact":"Ended Beltrán Leyva family leadership; the organisation splintered into regional cells such as Guerreros Unidos, Los Rojos and Los Mazatlecos that drove violence in Guerrero, Morelos and Sinaloa.","state":"GUA","city":"San Miguel de Allende","lat":20.9144,"lng":-100.7452,"cartels":["beltran_leyva","government"],"figures":["Héctor Beltrán Leyva 'El H'"],"type":"capture","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/H%C3%A9ctor_Beltr%C3%A1n_Leyva"]},{"id":"2014-vicente-carrillo-fuentes-arrested","date":"2014-10-09","precision":"day","title":"Juárez Cartel boss Vicente Carrillo Fuentes arrested in Torreón","summary":"Federal police and soldiers arrested Vicente Carrillo Fuentes 'El Viceroy', head of the Juárez Cartel since his brother Amado's death in 1997, at a checkpoint in Torreón, Coahuila, on 9 October 2014; he was carrying false identification and offered no resistance.","impact":"Removed the last old-guard leader of the Carrillo Fuentes organisation, leaving La Línea and Sinaloa-aligned factions to fight over the Juárez corridor and Chihuahua's sierra.","state":"COA","city":"Torreón","lat":25.5428,"lng":-103.4068,"cartels":["juarez","government"],"figures":["Vicente Carrillo Fuentes 'El Viceroy'"],"type":"capture","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Vicente_Carrillo_Fuentes","http://www.milenio.com/policia/Amado_Carrillo-Vicente_Carrillo_Fuentes-capturan_a_El_Viceroy-cartel_de_Juarez_0_387561456.html"]},{"id":"2015-la-tuta-captured-morelia","date":"2015-02-27","precision":"day","title":"La Tuta, Knights Templar leader, captured in Morelia","summary":"Servando 'La Tuta' Gómez Martínez, the former teacher who led the Knights Templar cartel, was arrested without a shot by Federal Police in Morelia, Michoacán, in the early hours of February 27, 2015, after months of tracking the couriers who carried his messages.","impact":"His capture effectively ended the Knights Templar as a coherent cartel and closed the Michoacán crisis that had spawned the autodefensas, leaving a vacuum later contested by CJNG and splinter groups such as Los Viagras.","state":"MIC","city":"Morelia","lat":19.706,"lng":-101.195,"cartels":["templarios","government"],"figures":["Servando 'La Tuta' Gómez Martínez"],"type":"capture","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Servando_G%C3%B3mez_Mart%C3%ADnez"]},{"id":"2015-el-cuini-captured-puerto-vallarta","date":"2015-02-28","precision":"day","title":"'El Cuini', CJNG financier, captured in Puerto Vallarta","summary":"Abigael González Valencia, 'El Cuini', head of the Los Cuinis money-laundering and trafficking network and brother-in-law of El Mencho, was arrested in a restaurant in Puerto Vallarta, Jalisco, on February 28, 2015. Weeks later the US designated him and Los Cuinis under the Kingpin Act; after a decade fighting extradition he was among 26 prisoners Mexico transferred to the US on August 12, 2025.","impact":"The arrest struck CJNG's financial core and, together with the Soyatán ambush and the May 1 helicopter attack, marked the escalation of confrontation between CJNG and the Peña Nieto government in 2015.","state":"JAL","city":"Puerto Vallarta","lat":20.6534,"lng":-105.2253,"cartels":["cjng","government"],"figures":["Abigael 'El Cuini' González Valencia"],"type":"capture","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Abigael_Gonz%C3%A1lez_Valencia","https://home.treasury.gov/news/press-releases/jl10020","https://www.cnn.com/2025/08/12/americas/mexico-26-cartels-trump-intl-latam"]},{"id":"2015-z42-omar-trevino-captured","date":"2015-03-04","precision":"day","title":"Zetas leader Z-42 Omar Treviño captured in San Pedro","summary":"Omar 'Z-42' Treviño Morales, who had led Los Zetas since his brother Z-40's arrest in 2013, was captured around 4 a.m. on March 4, 2015 in a house in the Fuentes del Valle neighborhood of San Pedro Garza García, Nuevo León, by Federal Police and the army without a shot being fired.","impact":"The arrest removed the last leader of the unified Zetas and triggered the succession fight that split the organization into the Cártel del Noreste and Zetas Vieja Escuela.","state":"NLE","city":"San Pedro Garza García","lat":25.6572,"lng":-100.4025,"cartels":["zetas","government"],"figures":["Omar 'Z-42' Treviño Morales"],"type":"capture","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Omar_Trevi%C3%B1o_Morales","https://en.wikipedia.org/wiki/Los_Zetas"]},{"id":"2015-soyatan-ambush-15-police-killed","date":"2015-04-06","precision":"day","title":"CJNG ambush kills 15 Jalisco state police at Soyatán","summary":"On the afternoon of April 6, 2015, CJNG gunmen who had waited for hours in the mountains blocked the Puerto Vallarta-Mascota highway at the turnoff to Soyatán (km 55+700), in the municipality of San Sebastián del Oeste, Jalisco, with a burning vehicle and opened fire on a Fuerza Única state police convoy with rifles and grenade launchers, killing 15 officers and wounding five.","impact":"The deadliest single attack on Mexican police since 2009, it revealed CJNG's willingness to confront the state head-on and prompted the federal 'Operativo Jalisco' that led to the May 1 Black Friday.","state":"JAL","city":"Soyatán, San Sebastián del Oeste","lat":20.8706,"lng":-104.9786,"cartels":["cjng","government"],"figures":["Nemesio 'El Mencho' Oseguera Cervantes"],"type":"attack","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/2015_San_Sebasti%C3%A1n_del_Oeste_ambush","https://www.informador.mx/Jalisco/Confirman-15-policias-muertos-en-emboscada-en-San-Sebastian-20150407-0076.html","https://en.wikipedia.org/wiki/1_May_2015_Jalisco_attacks"]},{"id":"2015-cjng-kingpin-act-designation","date":"2015-04-08","precision":"day","title":"US Treasury designates CJNG and Los Cuinis under Kingpin Act","summary":"On April 8, 2015, the US Treasury's Office of Foreign Assets Control named the Cártel de Jalisco Nueva Generación and its financial arm Los Cuinis as Specially Designated Narcotics Traffickers under the Foreign Narcotics Kingpin Designation Act, together with their leaders Nemesio 'El Mencho' Oseguera Cervantes and Abigael 'El Cuini' González Valencia.","impact":"The designation was Washington's first formal recognition of CJNG as one of Mexico's most powerful cartels, froze US-linked assets and began a years-long sanctions campaign against the CJNG-Cuinis financial network.","state":"US","city":"Washington, D.C.","lat":38.8977,"lng":-77.0365,"cartels":["cjng","us_government"],"figures":["Nemesio 'El Mencho' Oseguera Cervantes","Abigael 'El Cuini' González Valencia"],"type":"policy","importance":3,"confidence":"high","sources":["https://home.treasury.gov/news/press-releases/jl10020"]},{"id":"2015-jalisco-black-friday-helicopter-downed","date":"2015-05-01","precision":"day","title":"Jalisco 'Black Friday': CJNG downs army helicopter","summary":"On May 1, 2015, as federal forces launched 'Operativo Jalisco' to capture Nemesio 'El Mencho' Oseguera, CJNG gunmen near Villa Purificación hit an army EC725 Cougar helicopter with a rocket-propelled grenade, killing eight soldiers and a federal police officer. The cartel simultaneously hijacked 39 vehicles and set up burning blockades in 25 municipalities across Jalisco and four neighboring states, torching gas stations and banks; the day's violence left at least 15 dead in all.","impact":"The first downing of a military aircraft by a cartel in the drug war announced CJNG as Mexico's most aggressive criminal organization and forced the federal government to treat it as a national priority.","state":"JAL","city":"Villa Purificación","lat":19.7168,"lng":-104.6048,"cartels":["cjng","government"],"figures":["Nemesio 'El Mencho' Oseguera Cervantes"],"type":"attack","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/1_May_2015_Jalisco_attacks","https://en.wikipedia.org/wiki/El_Mencho","https://insightcrime.org/mexico-organized-crime-news/jalisco-cartel-new-generation/"]},{"id":"2015-tanhuato-rancho-del-sol-killings","date":"2015-05-22","precision":"day","title":"Tanhuato: 42 civilians killed at Rancho del Sol","summary":"On May 22, 2015, Federal Police backed by a helicopter attacked suspected CJNG gunmen at Rancho El Sol, in the Puerta de Vargas area of Tanhuato, Michoacán, killing 42 civilians while losing one officer. Police claimed a three-hour firefight; the CNDH's August 18, 2016 recommendation concluded at least 22 of the dead were arbitrarily executed and that the scene and weapons had been manipulated.","impact":"The deadliest confrontation of the Peña Nieto years became a landmark case of extrajudicial killing by federal forces, cited alongside Tlatlaya and Apatzingán as evidence of impunity; the Federal Police denied executions and no officer was convicted.","state":"MIC","city":"Tanhuato","lat":20.2843,"lng":-102.3274,"cartels":["cjng","government"],"figures":["Enrique Galindo Ceballos"],"type":"massacre","importance":4,"confidence":"high","sources":["https://es.wikipedia.org/wiki/Enfrentamiento_en_Tanhuato","https://www.hrw.org/world-report/2018/country-chapters/mexico"]},{"id":"2015-el-chapo-altiplano-tunnel-escape","date":"2015-07-11","precision":"day","title":"El Chapo escapes Altiplano prison through 1.5 km tunnel","summary":"On the night of July 11, 2015, Joaquín 'El Chapo' Guzmán slipped through a hole in the shower area of his cell at the Altiplano maximum-security prison (CEFERESO No. 1) in Almoloya de Juárez, Estado de México, and fled along a ventilated, lit tunnel roughly 1.5 km long that surfaced inside a half-built house. It was his second escape from a federal prison after Puente Grande in 2001.","impact":"The escape humiliated the Peña Nieto government, which had resisted US extradition requests, led to the dismissal of prison officials and a nationwide manhunt, and made Guzmán's eventual extradition politically unavoidable.","state":"MEX","city":"Almoloya de Juárez","lat":19.3697,"lng":-99.7594,"cartels":["sinaloa","government"],"figures":["Joaquín 'El Chapo' Guzmán"],"type":"escape","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Joaqu%C3%ADn_%22El_Chapo%22_Guzm%C3%A1n","https://en.wikipedia.org/wiki/2015_in_Mexico"]},{"id":"2015-giei-ayotzinapa-report-rejects-historical-truth","date":"2015-09-06","precision":"day","title":"GIEI report demolishes Ayotzinapa 'historical truth'","summary":"On September 6, 2015, the Inter-American Commission's Interdisciplinary Group of Independent Experts (GIEI) presented its first report on the 43 Ayotzinapa students disappeared by police and Guerreros Unidos in Iguala in 2014, concluding there was no scientific evidence the bodies were burned at the Cocula dump as former attorney general Jesús Murillo Karam's 'verdad histórica' claimed, and documenting torture of detainees and an unexplained fifth bus.","impact":"The report destroyed the official narrative, internationalized scrutiny of Mexican investigations, and kept the Ayotzinapa case open as the defining human-rights scandal of the Peña Nieto administration.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["guerreros_unidos","government"],"figures":["Jesús Murillo Karam"],"type":"other","importance":4,"confidence":"high","sources":["https://es.wikipedia.org/wiki/Desaparici%C3%B3n_forzada_de_Iguala_de_2014","https://en.wikipedia.org/wiki/2014_Iguala_mass_kidnapping"]},{"id":"2016-zetas-split-cdn-vieja-escuela","date":"2016-01-01","precision":"year","title":"Zetas fracture into Cártel del Noreste and Zetas Vieja Escuela","summary":"After Z-42's capture in March 2015, Juan Francisco 'Kiko' Treviño Chávez, a nephew of the Treviño brothers, took over the Nuevo Laredo-based core, which rebranded as the Cártel del Noreste (CDN). Veterans who rejected the Treviño family, led by José Guízar Valencia 'Z-43', formed the Zetas Vieja Escuela in 2016 and allied with Gulf Cartel factions in Tamaulipas and Veracruz. 'Kiko' was arrested in Houston in September 2016 and Juan Gerardo Treviño Chávez 'El Huevo' assumed CDN command.","impact":"The split ended Los Zetas as a national organization and spawned the CDN-Vieja Escuela war that drove violence in Nuevo Laredo, Ciudad Victoria and Zacatecas for years.","state":"TAM","city":"Nuevo Laredo","lat":27.4763,"lng":-99.5164,"cartels":["zetas","cdn","zetas_vieja_escuela","gulf"],"figures":["Juan Francisco 'Kiko' Treviño Chávez","Juan Gerardo 'El Huevo' Treviño Chávez","Omar 'Z-42' Treviño Morales"],"type":"split","importance":4,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/C%C3%A1rtel_del_Noreste","https://en.wikipedia.org/wiki/Zetas_Vieja_Escuela","https://insightcrime.org/mexico-organized-crime-news/zetas-profile/"]},{"id":"2016-colima-highest-homicide-rate","date":"2016-01-01","precision":"year","title":"Colima becomes Mexico's most violent state per capita","summary":"From 2016 to 2018 the small Pacific state of Colima posted Mexico's highest homicide rates, about 71 per 100,000 in 2016, 97 in 2017 and 81 in 2018 by SESNSP counts (INEGI's death-certificate figures run higher), as CJNG fought the Sinaloa Cartel for the port of Manzanillo, the country's main gateway for Asian methamphetamine precursors, with killings concentrated in Manzanillo, Tecomán and Colima city.","impact":"Colima's spike showed how the CJNG-Sinaloa rivalry over precursor-chemical ports turned peripheral states into national murder leaders, a pattern later repeated in Zacatecas and Baja California.","state":"COL","city":"Colima","lat":19.2433,"lng":-103.725,"cartels":["cjng","sinaloa"],"figures":[],"type":"battle","importance":3,"confidence":"high","sources":["https://es.wikipedia.org/wiki/Anexo:Entidades_federativas_de_M%C3%A9xico_por_tasa_de_homicidio","https://en.wikipedia.org/wiki/Colima"]},{"id":"2016-el-chapo-recaptured-los-mochis","date":"2016-01-08","precision":"day","title":"El Chapo recaptured in Los Mochis after Marine raid","summary":"Mexican Marines stormed a safe house in Los Mochis, Sinaloa, before dawn on January 8, 2016; five gunmen died and Guzmán fled through the storm drains before federal police detained him on a highway outside the city. The next day Rolling Stone published Sean Penn's secret interview with Guzmán, arranged through actress Kate del Castillo, contacts that investigators said had helped locate him.","impact":"Six months after his tunnel escape, the recapture ended the manhunt and opened the path to extradition; Guzmán was returned to Altiplano and in May 2016 moved to the federal prison in Ciudad Juárez.","state":"SIN","city":"Los Mochis","lat":25.7903,"lng":-108.9857,"cartels":["sinaloa","government"],"figures":["Joaquín 'El Chapo' Guzmán"],"type":"capture","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Joaqu%C3%ADn_%22El_Chapo%22_Guzm%C3%A1n","https://insightcrime.org/mexico-organized-crime-news/sinaloa-cartel-profile/","https://en.wikipedia.org/wiki/2016_in_Mexico"]},{"id":"2016-topo-chico-prison-riot-49-dead","date":"2016-02-11","precision":"day","title":"Topo Chico prison riot in Monterrey leaves 49 dead","summary":"In the night of February 10-11, 2016, rival Zetas factions led by Juan Pedro Saldívar Farías 'El Z-27' and Jorge Iván Hernández Cantú 'El Credo' fought for control of the Topo Chico prison in Monterrey, Nuevo León, killing 49 inmates with hammers, clubs and knives and setting fires, days before Pope Francis visited the city.","impact":"Mexico's deadliest prison riot in decades exposed cartel self-governance inside state prisons and the Zetas' violent fragmentation; Topo Chico was closed in 2019.","state":"NLE","city":"Monterrey","lat":25.6866,"lng":-100.3161,"cartels":["zetas"],"figures":["Juan Pedro Saldívar Farías 'El Z-27'","Jorge Iván Hernández Cantú 'El Credo'"],"type":"massacre","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Topo_Chico_prison_riot","https://en.wikipedia.org/wiki/2016_in_Mexico"]},{"id":"2016-chapitos-kidnapped-puerto-vallarta","date":"2016-08-15","precision":"day","title":"CJNG kidnaps El Chapo's sons at La Leche, Puerto Vallarta","summary":"In the early hours of August 15, 2016, CJNG gunmen seized Iván Archivaldo and Jesús Alfredo Guzmán Salazar and four companions from the upscale La Leche restaurant in Puerto Vallarta's hotel zone; the brothers' presence was confirmed by the family and the DEA within days. After negotiations reportedly brokered by Ismael 'El Mayo' Zambada, the hostages were released within the week.","impact":"The abduction, carried out while El Chapo awaited extradition, exposed the Sinaloa Cartel's vulnerability and signaled open war between CJNG and the Guzmán faction in Jalisco, Baja California and elsewhere.","state":"JAL","city":"Puerto Vallarta","lat":20.6534,"lng":-105.2253,"cartels":["cjng","chapitos","sinaloa"],"figures":["Iván Archivaldo Guzmán Salazar","Jesús Alfredo Guzmán Salazar","Nemesio 'El Mencho' Oseguera Cervantes"],"type":"attack","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Iv%C3%A1n_Archivaldo_Guzm%C3%A1n_Salazar","https://en.wikipedia.org/wiki/Jalisco_New_Generation_Cartel"]},{"id":"2016-culiacan-ambush-five-soldiers-killed","date":"2016-09-30","precision":"day","title":"Sinaloa gunmen ambush army convoy near Culiacán, 5 soldiers dead","summary":"Around 3:25 a.m. on September 30, 2016, two army Humvees escorting an ambulance carrying a wounded gunman, Julio Óscar Ortiz Vega 'El Kevin', from Badiraguato to Culiacán were attacked with .50-caliber rifles and grenades on the México-Nogales highway near the Espacios Barcelona subdivision on the outskirts of Culiacán, Sinaloa. Five soldiers were killed, ten soldiers and a paramedic were wounded, and the attackers freed the prisoner. Army commanders pointed to gunmen of the faction loyal to El Chapo's sons; 'El Kevin' was found murdered in Navolato in March 2017.","impact":"The boldest attack on the army in Sinaloa in years showed the Guzmán faction's firepower during the post-capture power struggle and foreshadowed the 2019 'Culiacanazo'.","state":"SIN","city":"Culiacán","lat":24.8091,"lng":-107.394,"cartels":["sinaloa","chapitos","government"],"figures":["Julio Óscar Ortiz Vega 'El Kevin'"],"type":"attack","importance":4,"confidence":"medium","sources":["https://www.eluniversal.com.mx/articulo/nacion/seguridad/2016/10/4/difunden-foto-de-el-kevin-cuyo-rescate-provoco-emboscada-de/","https://cnnespanol.cnn.com/2016/09/30/cinco-soldados-mueren-en-emboscada-de-hombres-armados-en-sinaloa","https://www.proceso.com.mx/nacional/2017/3/8/hallan-muerto-el-kevin-rescatado-en-emboscada-militares-en-culiacan-180154.html"]},{"id":"2017-mexico-record-homicide-year","date":"2017-01-01","precision":"year","title":"2017 becomes Mexico's deadliest year on record","summary":"Mexico's 2017 homicide toll surpassed the previous 2011 peak: the SESNSP registered 25,339 intentional-homicide investigations (roughly 29,000 victims), and INEGI counted 31,174 homicides in its preliminary release, later revised to 32,079, a rate of about 25 per 100,000 against 19.4 in 2011. Violence spread beyond traditional hotspots to Colima, Baja California Sur, Guanajuato and Quintana Roo as CJNG expanded and the Sinaloa Cartel fractured.","impact":"The record discredited the Peña Nieto security strategy, fed the passage of the Internal Security Law and became a central issue of the 2018 election; the record was broken again in 2018.","state":"MULTI","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["cjng","sinaloa","government"],"figures":["Enrique Peña Nieto"],"type":"other","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Crime_in_Mexico","https://www.inegi.org.mx/contenidos/saladeprensa/boletines/2018/EstSegPub/homicidios2017_07.pdf"]},{"id":"2017-los-cabos-la-paz-violence-peak","date":"2017-01-01","precision":"year","title":"Los Cabos and La Paz violence peaks; Los Cabos ranked deadliest city","summary":"In 2017 a war between Sinaloa Cartel factions and CJNG for the tourist and retail-drug markets of Baja California Sur produced near-daily executions in Los Cabos and La Paz, with bodies hung from bridges and shootings near resorts; the state's homicide rate jumped to about 69 per 100,000. Los Cabos topped the Citizens' Council (CCSPJP) 2017 ranking of the world's most violent cities with 365 homicides, about 111 per 100,000, and La Paz also entered the top ten.","impact":"The collapse of security in a flagship tourist destination triggered US travel warnings and a federal deployment, and marked CJNG's push into the peninsula that later engulfed Tijuana; violence in BCS fell sharply in 2018.","state":"BCS","city":"Cabo San Lucas","lat":22.8905,"lng":-109.9167,"cartels":["sinaloa","cjng"],"figures":[],"type":"battle","importance":3,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Los_Cabos_Municipality","https://es.wikipedia.org/wiki/Anexo:Entidades_federativas_de_M%C3%A9xico_por_tasa_de_homicidio"]},{"id":"2017-bpm-festival-shooting-playa-del-carmen","date":"2017-01-16","precision":"day","title":"BPM Festival shooting in Playa del Carmen; Cancún attacked next day","summary":"Before dawn on January 16, 2017, a gunman opened fire at the Blue Parrot nightclub during the closing party of the BPM electronic music festival in Playa del Carmen, Quintana Roo, killing five people (four by gunfire, including festival security staff and foreign visitors, and one in the stampede) and wounding 15. The next day gunmen attacked the state prosecutor's office in Cancún, leaving four dead. A narcomanta hung in Playa del Carmen claimed the Blue Parrot attack as a warning to the festival's organizers for not 'falling in line'; press reports attributed the signature to CJNG, though some accounts cite Los Zetas.","impact":"The attacks announced the arrival of CJNG and its rivals in the Riviera Maya, a cocaine-retail and money-laundering hub, and started Cancún's violent 2017-18 spiral.","state":"ROO","city":"Playa del Carmen","lat":20.6296,"lng":-87.0739,"cartels":["cjng","other"],"figures":[],"type":"attack","importance":3,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/The_BPM_Festival","https://en.wikipedia.org/wiki/Elrow"]},{"id":"2017-el-chapo-extradited-to-us","date":"2017-01-19","precision":"day","title":"El Chapo extradited from Ciudad Juárez to New York","summary":"On January 19, 2017, the eve of Donald Trump's inauguration, Mexico flew Joaquín 'El Chapo' Guzmán from the Cefereso in Ciudad Juárez to Long Island MacArthur Airport. He was arraigned the next day in the US District Court for the Eastern District of New York in Brooklyn on a 17-count indictment.","impact":"Removing Guzmán triggered a succession war inside the Sinaloa Cartel between his sons (Los Chapitos) and Dámaso López's faction, and set up the 2018-19 Brooklyn trial that exposed decades of corruption.","state":"CHH","city":"Ciudad Juárez","lat":31.6904,"lng":-106.4245,"cartels":["sinaloa","government","us_government"],"figures":["Joaquín 'El Chapo' Guzmán"],"type":"extradition","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/United_States_v._Guzm%C3%A1n","https://en.wikipedia.org/wiki/Joaqu%C3%ADn_%22El_Chapo%22_Guzm%C3%A1n"]},{"id":"2017-h2-patron-sanchez-killed-tepic","date":"2017-02-09","precision":"day","title":"Marines kill Beltrán Leyva boss 'H2' in Tepic","summary":"On the evening of February 9, 2017 (around 7:30 p.m.), Mexican Navy special forces, supported by a helicopter gunship firing on a house in Tepic, Nayarit, killed Juan Francisco Patrón Sánchez 'H2', head of the Beltrán Leyva remnant that controlled Nayarit, along with seven gunmen. Further clashes on February 10 in nearby communities raised the toll to about 15, and to roughly 20 across the state within three days.","impact":"H2's death exposed the protection he enjoyed from state prosecutor Edgar Veytia, who was arrested weeks later, and opened Nayarit to a takeover contest between CJNG and Sinaloa factions.","state":"NAY","city":"Tepic","lat":21.5041,"lng":-104.8942,"cartels":["beltran_leyva","government"],"figures":["Juan Francisco 'H2' Patrón Sánchez"],"type":"killing","importance":4,"confidence":"high","sources":["https://es.wikipedia.org/wiki/Guerra_contra_el_narcotr%C3%A1fico_en_Nayarit","https://insightcrime.org/mexico-organized-crime-news/beltran-leyva-organization-profile/"]},{"id":"2017-colinas-de-santa-fe-mass-graves-veracruz","date":"2017-03-14","precision":"day","title":"Colinas de Santa Fe: 250+ skulls found in Veracruz mass graves","summary":"On March 14, 2017, Veracruz prosecutor Jorge Winckler announced that more than 250 skulls had been recovered from clandestine graves at Colinas de Santa Fe on the outskirts of the port of Veracruz, a site located in August 2016 by the Solecito collective of mothers searching for disappeared relatives, led by Lucía Díaz Genao. Excavations eventually recovered close to 300 bodies, many dating from the Zetas-dominated years of Governor Javier Duarte.","impact":"Then Mexico's largest clandestine grave, it demonstrated the scale of disappearances in Veracruz and the role of victims' collectives in doing the searches the state would not.","state":"VER","city":"Veracruz","lat":19.1738,"lng":-96.1342,"cartels":["zetas"],"figures":["Jorge Winckler Ortiz","Lucía Díaz Genao"],"type":"discovery","importance":4,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/2017_in_Mexico","https://en.wikipedia.org/wiki/Javier_Duarte_de_Ochoa"]},{"id":"2017-miroslava-breach-murdered-chihuahua","date":"2017-03-23","precision":"day","title":"Journalist Miroslava Breach shot dead in Chihuahua","summary":"La Jornada correspondent Miroslava Breach Velducea was shot eight times in her car as she left her home in Chihuahua city at about 7 a.m. on March 23, 2017. Her reporting had exposed links between candidates for local office and Los Salazar, a Gente Nueva cell of the Sinaloa Cartel in the Sierra Tarahumara. Juan Carlos Moreno Ochoa 'El Larry', arrested in December 2017, was sentenced to 50 years in August 2020.","impact":"Her murder, weeks before Javier Valdez's, helped make 2017 the deadliest year on record for the Mexican press and galvanized the 'Ni silencio ni olvido' campaign, though the intellectual authors were never fully prosecuted.","state":"CHH","city":"Chihuahua","lat":28.6353,"lng":-106.0889,"cartels":["sinaloa"],"figures":["Miroslava Breach Velducea","Juan Carlos Moreno Ochoa 'El Larry'"],"type":"killing","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Miroslava_Breach"]},{"id":"2017-edgar-veytia-arrested-san-diego","date":"2017-03-27","precision":"day","title":"Nayarit attorney general Edgar Veytia arrested at US border","summary":"Edgar Veytia, Nayarit's state attorney general and a close ally of Governor Roberto Sandoval, was arrested by US agents on March 27, 2017 at the Cross Border Xpress terminal in San Diego on an Eastern District of New York indictment for trafficking heroin, cocaine, methamphetamine and marijuana. He later pleaded guilty and was sentenced to 20 years in September 2019.","impact":"The first sitting state prosecutor arrested in the US for drug trafficking laid bare the capture of Nayarit's justice system by the H2 organization and later fed the case against Governor Sandoval.","state":"US","city":"San Diego (Cross Border Xpress)","lat":32.5483,"lng":-116.9742,"cartels":["beltran_leyva","us_government","government"],"figures":["Edgar Veytia","Roberto Sandoval Castañeda"],"type":"corruption","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Edgar_Veytia","https://en.wikipedia.org/wiki/Cross_Border_Xpress"]},{"id":"2017-comandante-toro-killed-reynosa","date":"2017-04-22","precision":"day","title":"Gulf Cartel boss 'Comandante Toro' killed in Reynosa","summary":"On April 22, 2017, Mexican federal forces killed Julián Manuel Loisa Salinas, 'Comandante Toro', leader of the Gulf Cartel's Metros faction in Reynosa, Tamaulipas. His gunmen responded with dozens of burning blockades and attacks across the city; in May the army captured his successor José Antonio Romo López 'La Hamburguesa', and rival Gulf cells then fought for months over the Reynosa plaza.","impact":"Toro's death shattered the last relatively unified Gulf Cartel cell on the border and unleashed the 2017-18 Reynosa war, one of the bloodiest urban conflicts in Tamaulipas.","state":"TAM","city":"Reynosa","lat":26.0806,"lng":-98.2883,"cartels":["gulf","government"],"figures":["Julián Manuel Loisa Salinas 'Comandante Toro'"],"type":"killing","importance":3,"confidence":"medium","sources":["https://insightcrime.org/mexico-organized-crime-news/gulf-cartel-profile/","https://es.wikipedia.org/wiki/C%C3%A1rtel_del_Golfo"]},{"id":"2017-damaso-lopez-licenciado-arrested","date":"2017-05-02","precision":"day","title":"Dámaso López 'El Licenciado' arrested in Mexico City","summary":"Dámaso López Núñez, El Chapo's former right-hand man who was fighting Guzmán's sons and El Mayo Zambada for control of the Sinaloa Cartel, was arrested by the army and federal investigators on May 2, 2017 in an apartment in the Anzures neighborhood of Mexico City. The Chapitos had publicly blamed him for a February 2017 ambush on them and Zambada. He was extradited in 2018, pleaded guilty in September 2018 and became a US witness.","impact":"His capture tilted the Sinaloa succession war toward the Chapitos and El Mayo, and his later testimony at the Brooklyn trial helped convict Guzmán.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["sinaloa","chapitos","government"],"figures":["Dámaso López Núñez 'El Licenciado'"],"type":"capture","importance":4,"confidence":"high","sources":["https://es.wikipedia.org/wiki/D%C3%A1maso_L%C3%B3pez_N%C3%BA%C3%B1ez","https://en.wikipedia.org/wiki/Infighting_in_the_Sinaloa_Cartel"]},{"id":"2017-palmarito-tochapan-huachicol-clash","date":"2017-05-03","precision":"day","title":"Palmarito clash: soldiers and huachicoleros die in Puebla","summary":"On the night of May 3, 2017, soldiers confronting fuel thieves in Palmarito Tochapan, Quecholac, in Puebla's 'Triángulo Rojo' pipeline-theft corridor, were ambushed; four soldiers and six civilians died. Security-camera video later showed a soldier shooting a subdued man on the ground, and the army acknowledged the killing.","impact":"The clash made huachicol a national security issue, exposed the local social base of fuel theft in Puebla and became a reference case for military abuses in the fight against pipeline tapping.","state":"PUE","city":"Palmarito Tochapan, Quecholac","lat":18.9033,"lng":-97.6356,"cartels":["other","government"],"figures":[],"type":"battle","importance":3,"confidence":"medium","sources":["https://es.wikipedia.org/wiki/Palmarito_Tochapan"]},{"id":"2017-javier-valdez-murdered-culiacan","date":"2017-05-15","precision":"day","title":"Ríodoce founder Javier Valdez murdered in Culiacán","summary":"Javier Valdez Cárdenas, co-founder of the weekly Ríodoce and one of Mexico's foremost chroniclers of drug trafficking, was pulled from his car and shot 12 times a few blocks from his office in Culiacán, Sinaloa, around noon on May 15, 2017. Prosecutors later tied the killing to the faction of Dámaso López, angered by an interview Ríodoce published; two gunmen were convicted in 2020 and 2021.","impact":"The murder of an internationally recognized journalist drew global condemnation and became a symbol of impunity for attacks on the press in Mexico.","state":"SIN","city":"Culiacán","lat":24.8091,"lng":-107.394,"cartels":["sinaloa"],"figures":["Javier Valdez Cárdenas","Dámaso López Serrano 'El Mini Lic'"],"type":"killing","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Javier_Valdez_C%C3%A1rdenas"]},{"id":"2017-javier-duarte-extradited-from-guatemala","date":"2017-07-17","precision":"day","title":"Ex-Veracruz governor Javier Duarte extradited from Guatemala","summary":"Javier Duarte de Ochoa, PRI governor of Veracruz from December 2010 to October 2016, whose administration coincided with Zetas dominance, mass graves and the murders of more than a dozen journalists (17 by press-freedom groups' counts), fled in October 2016 and was arrested in Panajachel, Guatemala, on April 15, 2017. He was extradited to Mexico on July 17, 2017, jailed at Reclusorio Norte in Mexico City and sentenced on September 26, 2018 to nine years for money laundering and criminal association.","impact":"Duarte's fall was the emblematic corruption scandal of the Peña Nieto era and confirmed the collusion between state government and organized crime that had made Veracruz one of Mexico's most dangerous states.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["zetas","government"],"figures":["Javier Duarte de Ochoa"],"type":"corruption","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Javier_Duarte_de_Ochoa","https://en.wikipedia.org/wiki/2017_in_Mexico"]},{"id":"2017-el-ojos-killed-tlahuac","date":"2017-07-20","precision":"day","title":"Marines kill 'El Ojos', Cártel de Tláhuac boss, in Mexico City","summary":"On July 20, 2017, Mexican Navy special forces killed Felipe de Jesús Pérez Luna 'El Ojos', leader of the Cártel de Tláhuac, and seven of his gunmen on Simón Álvarez street in the La Conchita Zapotitlán neighborhood of Tláhuac borough, Mexico City, after his escorts opened fire to avoid a checkpoint. Hundreds of mototaxi drivers loyal to the group blocked avenues and burned vehicles in protest.","impact":"The first Marine operation inside the capital forced the city government to admit that organized crime controlled territory in Mexico City, and fragmented the drug trade in Tláhuac, Xochimilco and Iztapalapa.","state":"CMX","city":"La Conchita Zapotitlán, Tláhuac, Ciudad de México","lat":19.299,"lng":-99.036,"cartels":["tlahuac","government"],"figures":["Felipe de Jesús Pérez Luna 'El Ojos'"],"type":"killing","importance":3,"confidence":"high","sources":["https://es.wikipedia.org/wiki/C%C3%A1rtel_de_Tl%C3%A1huac","https://www.eluniversal.com.mx/articulo/metropoli/cdmx/2017/07/28/la-muerte-de-el-ojos-las-horas-antes-y-despues/"]},{"id":"2017-mini-lic-surrenders-calexico","date":"2017-07-27","precision":"day","title":"'Mini Lic' Dámaso López Serrano surrenders at Calexico","summary":"Dámaso López Serrano, 'El Mini Lic', son of El Licenciado and heir to his faction, walked across the Calexico, California port of entry on July 27, 2017 and surrendered to US agents, becoming the highest-ranking Sinaloa Cartel figure to turn himself in. He pleaded guilty in San Diego federal court in 2018 and later cooperated with US authorities.","impact":"His surrender, following his father's arrest, dissolved the Dámaso faction and left the Chapitos and El Mayo as the cartel's dominant wings; Mexican prosecutors later named him as the mastermind of Javier Valdez's murder.","state":"US","city":"Calexico, California","lat":32.6789,"lng":-115.4989,"cartels":["sinaloa","us_government"],"figures":["Dámaso López Serrano 'El Mini Lic'"],"type":"capture","importance":3,"confidence":"medium","sources":["https://es.wikipedia.org/wiki/Los_Ninis","https://insightcrime.org/mexico-organized-crime-news/sinaloa-cartel-profile/"]},{"id":"2017-ley-de-seguridad-interior-enacted","date":"2017-12-21","precision":"day","title":"Internal Security Law formalizes military policing","summary":"After approval by the Chamber of Deputies on November 30 (248-115) and the Senate in the early hours of December 15, 2017 (76-44), the Ley de Seguridad Interior was published in the Diario Oficial on December 21, 2017, giving the armed forces a permanent legal basis to carry out public-security tasks. Human-rights groups, the UN and the CNDH opposed it; the Supreme Court struck it down on November 15, 2018.","impact":"The law was the Peña Nieto government's answer to the 2017 homicide record and entrenched militarized security, a path López Obrador continued through the National Guard despite campaigning against it.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["government"],"figures":["Enrique Peña Nieto"],"type":"policy","importance":4,"confidence":"high","sources":["https://es.wikipedia.org/wiki/Ley_de_Seguridad_Interior_(M%C3%A9xico)","https://www.hrw.org/world-report/2018/country-chapters/mexico","https://www.hrw.org/world-report/2019/country-chapters/mexico"]},{"id":"2018-guanajuato-huachicol-war-csrl-cjng","date":"2018-01-01","precision":"year","title":"Guanajuato huachicol war: Santa Rosa de Lima vs CJNG","summary":"The Cártel de Santa Rosa de Lima, built from 2014 by José Antonio Yépez 'El Marro' in the village of Santa Rosa de Lima, Villagrán, ran a fuel-theft empire around the Salamanca refinery. As CJNG moved into the Celaya-Salamanca-Irapuato corridor, El Marro publicly challenged it in a 2017 video surrounded by gunmen; through 2018 the two groups traded massacres and Guanajuato's homicide victims more than doubled to more than 3,000 (SESNSP: 3,290), the most of any state, with the SESNSP rate rising from 18.6 to 44.6 per 100,000.","impact":"The war turned a once-calm industrial state into Mexico's deadliest and made fuel theft a national security issue, prompting López Obrador's December 2018 pipeline shutdown and the 2019 hunt for El Marro.","state":"GUA","city":"Celaya","lat":20.5235,"lng":-100.8156,"cartels":["santa_rosa_lima","cjng"],"figures":["José Antonio Yépez Ortiz 'El Marro'","Nemesio 'El Mencho' Oseguera Cervantes"],"type":"battle","importance":4,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Santa_Rosa_de_Lima_Cartel","https://www.excelsior.com.mx/nacional/sube-en-guanajuato-400-homicidio-de-2015-a-2018/1277483","https://es.wikipedia.org/wiki/Anexo:Entidades_federativas_de_M%C3%A9xico_por_tasa_de_homicidio"]},{"id":"2018-tijuana-record-homicides","date":"2018-01-01","precision":"year","title":"Tijuana sets homicide record amid CJNG-Sinaloa war","summary":"Tijuana recorded more than 2,500 homicides in 2018 (2,518 by the Baja California prosecutor's count; the CCSPJP counted 2,640, about 138 per 100,000), after 1,744 in 2017, as CJNG allied with remnants of the Arellano Félix organization (the Cártel de Tijuana Nueva Generación) fought Sinaloa Cartel cells for street-level methamphetamine sales and smuggling corridors.","impact":"Tijuana became the world's most violent city by homicide count and rate for 2018, and Baja California's rate rose to about 76 per 100,000, second only to Colima.","state":"BCN","city":"Tijuana","lat":32.5149,"lng":-117.0382,"cartels":["cjng","tijuana","sinaloa"],"figures":[],"type":"battle","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Tijuana","https://es.wikipedia.org/wiki/Anexo:Entidades_federativas_de_M%C3%A9xico_por_tasa_de_homicidio"]},{"id":"2018-election-violence-candidates-killed","date":"2018-01-01","precision":"year","title":"2018 electoral process is Mexico's bloodiest for politicians","summary":"Between the start of the electoral process in September 2017 and the July 1, 2018 vote, consultancy Etellekt counted 152 politicians murdered, including 48 candidates or pre-candidates, most of them running for municipal office in states such as Guerrero, Oaxaca, Puebla, Veracruz and Michoacán. Emblematic cases included Fernando Purón, PRI candidate for federal deputy, shot in the head while posing for a selfie after a debate in Piedras Negras, Coahuila, on the night of June 8, 2018.","impact":"The killings showed criminal groups' determination to choose local authorities, forcing candidates to withdraw in dozens of municipalities and making local political capture a central feature of Mexican organized crime.","state":"MULTI","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["other"],"figures":["Fernando Purón Johnston"],"type":"killing","importance":4,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/2018_Mexican_general_election","https://en.wikipedia.org/wiki/List_of_politicians_killed_in_the_Mexican_drug_war","https://en.wikipedia.org/wiki/Piedras_Negras,_Coahuila"]},{"id":"2018-nuevo-laredo-marines-enforced-disappearances","date":"2018-05-30","precision":"day","title":"UN denounces wave of disappearances by Marines in Nuevo Laredo","summary":"On May 30, 2018, the UN human rights office said at least 23 people, including five minors, had been forcibly disappeared in Nuevo Laredo, Tamaulipas, between February and May 2018, with strong indications that Navy personnel deployed against the Cártel del Noreste were responsible. Families reported victims taken at night by men in Marine uniforms; several bodies were later found, and the CNDH and the FGR later documented dozens more cases attributed to the Navy's UNOPES special-operations unit.","impact":"The case tarnished the Navy, until then the most trusted force in the drug war, led to the confinement and withdrawal of the Marine unit from the city in June 2018 and became a key argument against the Internal Security Law.","state":"TAM","city":"Nuevo Laredo","lat":27.4763,"lng":-99.5164,"cartels":["government","cdn"],"figures":[],"type":"other","importance":3,"confidence":"high","sources":["https://www.hrw.org/world-report/2019/country-chapters/mexico","https://animalpolitico.com/2020/11/grupo-elite-marina-desapariciones-nuevo-laredo-responsables-fgr","https://www.proceso.com.mx/nacional/estados/2026/4/7/ocho-anos-del-operativo-de-la-marina-en-nuevo-laredo-familias-aun-buscan-32-desaparecidos-371705.html"]},{"id":"2018-amlo-wins-presidential-election","date":"2018-07-01","precision":"day","title":"López Obrador wins presidency in a landslide","summary":"Andrés Manuel López Obrador of the Morena-led 'Juntos Haremos Historia' coalition won the July 1, 2018 presidential election with 53.19 percent of the vote (30,113,483 ballots), the first absolute majority since 1988, carrying 31 of 32 states; his coalition also took control of both chambers of Congress.","impact":"The result ended PRI/PAN dominance and brought a president promising to end the militarized 'war on drugs' with social programs, amnesty proposals and a new National Guard, reshaping Mexican security policy from December 2018.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["government"],"figures":["Andrés Manuel López Obrador"],"type":"policy","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/2018_Mexican_general_election","https://es.wikipedia.org/wiki/Elecciones_federales_de_M%C3%A9xico_de_2018"]},{"id":"2018-plaza-garibaldi-mariachi-shooting","date":"2018-09-14","precision":"day","title":"Gunmen dressed as mariachis kill six at Plaza Garibaldi","summary":"On the night of September 14, 2018, three gunmen disguised as mariachis opened fire on a group at Plaza Garibaldi, Mexico City's famed mariachi square, killing five people on the spot (a sixth died later) and wounding several others. Authorities attributed the attack to La Unión Tepito's war with the splinter Fuerza Anti-Unión for extortion and drug sales in the city center, weeks after the August 8 arrest of Unión leader Roberto 'El Betito' Moyado.","impact":"The attack in a tourist landmark shattered the narrative that Mexico City was insulated from cartel violence and pushed the incoming city government to target La Unión Tepito.","state":"CMX","city":"Ciudad de México (Plaza Garibaldi)","lat":19.4406,"lng":-99.1394,"cartels":["union_tepito","anti_union"],"figures":["Roberto Moyado Esparza 'El Betito'"],"type":"attack","importance":3,"confidence":"medium","sources":["https://insightcrime.org/mexico-organized-crime-news/la-union-tepito/","https://en.wikipedia.org/wiki/La_Uni%C3%B3n_Tepito","https://en.wikipedia.org/wiki/2018_in_Mexico"]},{"id":"2018-us-10-million-reward-el-mencho","date":"2018-10-16","precision":"day","title":"US offers $10 million for El Mencho in joint CJNG crackdown","summary":"On October 16, 2018, the US Departments of Justice, State and Treasury announced a coordinated action against CJNG: unsealed indictments in several districts, new Kingpin Act sanctions, and State Department rewards of US$10 million for Nemesio 'El Mencho' Oseguera Cervantes and US$5 million for his son Rubén 'El Menchito' Oseguera González, then jailed in Mexico awaiting extradition.","impact":"The announcement made El Mencho the most wanted trafficker after El Chapo's extradition and formally identified CJNG as a top US enforcement priority for its fentanyl and methamphetamine trafficking.","state":"US","city":"Washington, D.C.","lat":38.8977,"lng":-77.0365,"cartels":["cjng","us_government"],"figures":["Nemesio 'El Mencho' Oseguera Cervantes","Rubén 'El Menchito' Oseguera González"],"type":"policy","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/El_Mencho","https://insightcrime.org/mexico-organized-crime-news/jalisco-cartel-new-generation/"]},{"id":"2018-el-chapo-trial-opens-brooklyn","date":"2018-11-13","precision":"day","title":"El Chapo trial opens in Brooklyn federal court","summary":"After jury selection began on November 5, opening statements in United States v. Guzmán were delivered on November 13, 2018 before Judge Brian Cogan in the Eastern District of New York. Over three months, cooperating witnesses including Jesús 'El Rey' Zambada, Dámaso López Núñez and Vicente Zambada described bribes to officials and decades of trafficking; Guzmán was convicted on all counts on February 12, 2019.","impact":"The trial produced the most detailed public record of Sinaloa Cartel operations and Mexican official corruption, including allegations that reached former presidents, and ended with a life sentence in July 2019.","state":"US","city":"Brooklyn, New York","lat":40.6928,"lng":-73.9906,"cartels":["sinaloa","us_government"],"figures":["Joaquín 'El Chapo' Guzmán","Brian Cogan"],"type":"trial","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/United_States_v._Guzm%C3%A1n"]},{"id":"2018-amlo-inaugurated-abrazos-no-balazos","date":"2018-12-01","precision":"day","title":"AMLO takes office promising 'abrazos, no balazos'","summary":"López Obrador was sworn in on December 1, 2018, pledging a security strategy of 'hugs, not bullets': attacking the social roots of crime, a possible amnesty for low-level offenders and a new militarized National Guard announced in his National Peace and Security Plan of November 14, 2018. On December 27 he launched a crackdown on fuel theft, shutting key Pemex pipelines.","impact":"The inauguration closed the Peña Nieto era, which ended with a new record of more than 33,000 homicide victims in 2018 (SESNSP: 33,341), and began a strategy that de-emphasized kingpin captures while expanding the armed forces' domestic role.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["government"],"figures":["Andrés Manuel López Obrador"],"type":"policy","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Andr%C3%A9s_Manuel_L%C3%B3pez_Obrador","https://en.wikipedia.org/wiki/Crime_in_Mexico"]},{"id":"2019-tlahuelilpan-pipeline-explosion","date":"2019-01-18","precision":"day","title":"Tlahuelilpan pipeline explosion kills 137 amid huachicol crackdown","summary":"On the evening of 18 January 2019 an illegally tapped Pemex pipeline (Tuxpan–Tula) gushed gasoline in Tlahuelilpan, Hidalgo, and hundreds of residents gathered to fill containers. The leak was reported at about 17:04 and the fuel ignited at about 19:10, killing 137 people. The tap occurred weeks into President López Obrador's national offensive against fuel theft ('huachicol'), which had shut pipelines and produced gasoline shortages across central Mexico.","impact":"The deadliest single incident of the fuel-theft era exposed how deeply huachicol economies were embedded in Hidalgo and the Bajío. It hardened the federal anti-fuel-theft campaign, which soon focused on the Santa Rosa de Lima Cartel in neighbouring Guanajuato.","state":"HID","city":"Tlahuelilpan","lat":20.1175,"lng":-99.2194,"cartels":["other","government"],"figures":["Andrés Manuel López Obrador"],"type":"other","importance":4,"confidence":"high","sources":["https://www.bbc.com/news/world-latin-america-46929950","https://www.reuters.com/article/us-mexico-fuel-theft-blast/death-toll-raised-to-79-in-mexico-pipeline-blast-new-focus-on-fuel-theft-idUSKCN1PE08C","https://en.wikipedia.org/wiki/2019_Tlahuelilpan_pipeline_explosion"]},{"id":"2019-el-chapo-convicted-brooklyn","date":"2019-02-12","precision":"day","title":"El Chapo convicted on all counts in Brooklyn federal court","summary":"On 12 February 2019 a federal jury in the Eastern District of New York (Brooklyn) found Joaquín 'El Chapo' Guzmán guilty of all ten counts, including running a continuing criminal enterprise, after a three-month trial before Judge Brian Cogan. Testimony from former Sinaloa Cartel associates detailed bribery of Mexican officials and decades of trafficking.","impact":"The most-watched narco trial in US history closed the chapter on the Sinaloa Cartel's most famous leader and put testimony about high-level Mexican corruption (including Genaro García Luna) on the public record, feeding later prosecutions.","state":"US","city":"Brooklyn, New York","lat":40.6931,"lng":-73.9903,"cartels":["sinaloa","us_government"],"figures":["Joaquín 'El Chapo' Guzmán","Brian Cogan"],"type":"trial","importance":5,"confidence":"high","sources":["https://www.justice.gov/opa/pr/joaquin-el-chapo-guzman-sinaloa-cartel-leader-convicted-running-continuing-criminal-enterprise","https://en.wikipedia.org/wiki/Joaqu%C3%ADn_%22El_Chapo%22_Guzm%C3%A1n","https://en.wikipedia.org/wiki/2019_in_organized_crime"]},{"id":"2019-national-guard-created","date":"2019-03-26","precision":"day","title":"Constitutional reform creates the National Guard","summary":"After Congress approved the reform on 28 February 2019, the decree creating the Guardia Nacional was published in the Diario Oficial on 26 March 2019. Its organic law followed on 27 May and the force was formally inaugurated on 30 June 2019, absorbing military police, naval police and the Federal Police under a nominally civilian command. In September 2022 it was transferred to the Defence Ministry (Sedena).","impact":"The National Guard became the centrepiece of López Obrador's 'abrazos, no balazos' security policy and, in practice, entrenched military control of public security in Mexico for the rest of the decade.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["government"],"figures":["Andrés Manuel López Obrador","Alfonso Durazo Montaño","Luis Rodríguez Bucio"],"type":"policy","importance":5,"confidence":"high","sources":["https://www.nytimes.com/2019/02/28/world/americas/mexico-amlo-national-guard.html","https://en.wikipedia.org/wiki/National_Guard_(Mexico)","https://www.elfinanciero.com.mx/nacional/2022/09/09/pase-de-la-guardia-nacional-a-la-sedena-es-oficial-amlo-publica-decreto-en-el-dof/"]},{"id":"2019-minatitlan-party-massacre","date":"2019-04-19","precision":"day","title":"Gunmen kill 14 at a family party in Minatitlán, Veracruz","summary":"At about 21:00 on 19 April 2019 gunmen burst into a birthday party in the Obrera neighbourhood of Minatitlán, Veracruz, asked for a bar manager known as 'La Becky' and opened fire, killing 13 people at the scene, including a one-year-old boy; a fourteenth victim later died. Investigators linked the attack to the turf war between the CJNG and remnants of Los Zetas over extortion and drug sales in the southern Veracruz oil corridor.","impact":"The massacre made southern Veracruz a symbol of the new administration's failure to contain violence and foreshadowed the Coatzacoalcos bar arson four months later.","state":"VER","city":"Minatitlán","lat":17.9892,"lng":-94.5566,"cartels":["cjng","zetas"],"figures":[],"type":"massacre","importance":3,"confidence":"high","sources":["https://www.milenio.com/policia/masacre-en-minatitlan-esto-fue-lo-que-paso-cronologia","https://www.eluniversal.com.mx/estados/masacre-en-minatitlan-deja-consternacion-y-un-pueblo-polarizado","https://en.wikipedia.org/wiki/Minatitl%C3%A1n_massacre"]},{"id":"2019-el-chapo-sentenced-life","date":"2019-07-17","precision":"day","title":"El Chapo sentenced to life plus 30 years","summary":"On 17 July 2019 Judge Brian Cogan sentenced Joaquín 'El Chapo' Guzmán in Brooklyn to life imprisonment plus 30 years and ordered forfeiture of US$12.6 billion. Guzmán was transferred to the ADX Florence supermax in Colorado.","impact":"Guzmán's permanent removal left the Sinaloa Cartel formally led by Ismael 'El Mayo' Zambada and Guzmán's sons, Los Chapitos, setting up the factional tensions that would explode later in the decade.","state":"US","city":"Brooklyn, New York","lat":40.6931,"lng":-73.9903,"cartels":["sinaloa","us_government"],"figures":["Joaquín 'El Chapo' Guzmán","Brian Cogan"],"type":"trial","importance":4,"confidence":"high","sources":["https://www.justice.gov/opa/pr/joaquin-el-chapo-guzman-sinaloa-cartel-leader-sentenced-life-prison-plus-30-years","https://en.wikipedia.org/wiki/2019_in_organized_crime","https://en.wikipedia.org/wiki/Joaqu%C3%ADn_%22El_Chapo%22_Guzm%C3%A1n"]},{"id":"2019-uruapan-19-bodies-hung","date":"2019-08-08","precision":"day","title":"CJNG dumps 19 bodies in Uruapan, several hung from an overpass","summary":"Before dawn on 8 August 2019 residents of Uruapan, Michoacán, found bodies hanging from an overpass on Bulevar Industrial (nine according to most press reports, six according to some later accounts) and more dismembered or bagged at two nearby sites, 19 in total. Narcomantas signed by the Cártel Jalisco Nueva Generación threatened Los Viagras, the dominant local faction of what would become Cárteles Unidos.","impact":"The display announced the CJNG's push into Michoacán's avocado heartland and opened the phase of open war with the Viagras/Cárteles Unidos bloc that later engulfed Aguililla and Tierra Caliente.","state":"MIC","city":"Uruapan","lat":19.4208,"lng":-102.0628,"cartels":["cjng","carteles_unidos"],"figures":[],"type":"massacre","importance":3,"confidence":"high","sources":["https://www.bbc.com/news/world-latin-america-49289716","https://www.theguardian.com/world/2019/aug/08/mexico-bodies-police-uruapan-drug-cartels","https://en.wikipedia.org/wiki/Uruapan_massacre"]},{"id":"2019-caballo-blanco-bar-arson-coatzacoalcos","date":"2019-08-27","precision":"day","title":"Caballo Blanco bar arson in Coatzacoalcos kills more than 30","summary":"Late on 27 August 2019 armed men blocked the exits of the Caballo Blanco bar in Coatzacoalcos, Veracruz, doused it with fuel and set it ablaze. Some two dozen people died that night and the toll rose over the following weeks to 31–32 dead, with about a dozen injured. Prosecutors blamed a CJNG cell whose extortion demands the owner had refused; one suspect had been detained and released weeks earlier.","impact":"Mexico's deadliest attack on a nightlife venue since the 2011 Casino Royale fire prompted President López Obrador to accuse state prosecutors of collusion and exposed extortion as the CJNG's business model in the southern Gulf coast.","state":"VER","city":"Coatzacoalcos","lat":18.1345,"lng":-94.459,"cartels":["cjng"],"figures":["Cuitláhuac García Jiménez"],"type":"massacre","importance":4,"confidence":"high","sources":["https://www.washingtonpost.com/world/2019/08/28/arson-attack-bar-mexico-leaves-least-dead/","https://www.latimes.com/world-nation/story/2019-08-30/mexico-bar-killings-families-funerals","https://en.wikipedia.org/wiki/Coatzacoalcos_nightclub_fire"]},{"id":"2019-el-aguaje-police-ambush","date":"2019-10-14","precision":"day","title":"CJNG ambush kills 13 state police at El Aguaje, Aguililla","summary":"On 14 October 2019 more than 30 gunmen ambushed a Michoacán state police convoy of 42 officers sent to enforce a court order at El Aguaje, in the municipality of Aguililla, killing 13 officers and wounding nine. Vehicles were burned and narcomantas at the scene pointed to the Cártel Jalisco Nueva Generación, whose leader Nemesio Oseguera was born in Aguililla.","impact":"The deadliest attack on Mexican police in years marked the start of the CJNG's multi-year siege of Aguililla against Cárteles Unidos, and came three days before the Culiacanazo made October 2019 a turning point for the new government.","state":"MIC","city":"El Aguaje, Aguililla","lat":18.9917,"lng":-102.7108,"cartels":["cjng","government","carteles_unidos"],"figures":["Nemesio 'El Mencho' Oseguera Cervantes","Silvano Aureoles Conejo"],"type":"attack","importance":4,"confidence":"high","sources":["https://www.bbc.com/news/world-latin-america-50049142","https://www.courthousenews.com/gunmen-ambush-police-convoy-in-mexico-kill-13-and-wound-9/","https://www.aljazeera.com/news/2019/10/mexican-policemen-killed-cartel-ambush-191015055631257.html"]},{"id":"2019-culiacanazo-ovidio-release","date":"2019-10-17","precision":"day","title":"Culiacanazo: Ovidio Guzmán captured and released under cartel siege","summary":"At about 15:00 on 17 October 2019 a small army unit detained Ovidio Guzmán López, son of El Chapo, at a house in the Tres Ríos district of Culiacán. Hundreds of Sinaloa Cartel gunmen answered with blockades, burning vehicles and attacks across the city, seized soldiers as hostages, threatened military families in their housing complex, and dozens of inmates escaped from the Aguaruto prison. The security cabinet, with President López Obrador's endorsement, ordered Ovidio released; the official toll was 14 dead.","impact":"The 'Culiacanazo' became the defining image of the 'hugs not bullets' era, demonstrating the Sinaloa Cartel's capacity to hold a state capital hostage and shaping US and domestic debate about the government's will to confront the cartels.","state":"SIN","city":"Culiacán","lat":24.8091,"lng":-107.394,"cartels":["chapitos","sinaloa","government"],"figures":["Ovidio Guzmán López","Andrés Manuel López Obrador","Alfonso Durazo Montaño","Luis Cresencio Sandoval"],"type":"battle","importance":5,"confidence":"high","sources":["https://www.bbc.com/news/world-latin-america-50101739","https://en.wikipedia.org/wiki/Battle_of_Culiac%C3%A1n"]},{"id":"2019-lebaron-massacre-bavispe","date":"2019-11-04","precision":"day","title":"LeBarón massacre: nine dual-national women and children killed","summary":"On 4 November 2019 gunmen attacked three SUVs carrying members of the LeBarón and Langford families on a dirt road running east from La Mora (Bavispe, Sonora) toward the Chihuahua state line and Colonia LeBarón. Three women and six children, all US–Mexican dual nationals, were shot and one vehicle was burned; the remaining children survived, several of them wounded. Investigators attributed the attack to La Línea, the Juárez Cartel's armed wing, fighting Sinaloa-aligned Los Salazar over the Sonora–Chihuahua border corridor.","impact":"The killings drew a threat from President Trump to designate cartels as terrorist organisations and became the emblematic case for the LeBarón family's national campaign against impunity, straining US–Mexico security relations.","state":"SON","city":"Bavispe (La Mora)","lat":30.59,"lng":-108.95,"cartels":["juarez","sinaloa"],"figures":["Rhonita Miller","Dawna Langford","Christina Langford Johnson","Julián LeBarón"],"type":"massacre","importance":5,"confidence":"high","sources":["https://www.bbc.com/news/world-latin-america-50299562","https://www.cnn.com/2019/11/07/americas/mormons-attacked-us-mexico-border-thursday/index.html","https://en.wikipedia.org/wiki/LeBar%C3%B3n_and_Langford_families_massacre"]},{"id":"2019-villa-union-cdn-assault","date":"2019-11-30","precision":"day","title":"Cártel del Noreste convoy storms Villa Unión, Coahuila","summary":"Around midday on 30 November 2019 a convoy of Cártel del Noreste gunmen in armoured trucks attacked the town hall and police station of Villa Unión, Coahuila, about 60 km from the Texas border, in a firefight that lasted more than an hour. State forces pursued the attackers into the following day; at least 22 people died, including four police officers, two abducted civilians and at least 16 gunmen, and later official counts rose to as many as 25.","impact":"The assault showed the Zetas-successor CDN projecting force out of Nuevo Laredo into a state that had claimed to pacify its border, and prompted a lasting militarised deployment along Coahuila's frontier with Tamaulipas and Nuevo León.","state":"COA","city":"Villa Unión","lat":28.2203,"lng":-100.7244,"cartels":["cdn","government"],"figures":["Miguel Ángel Riquelme Solís"],"type":"battle","importance":4,"confidence":"high","sources":["https://www.bbc.com/news/world-latin-america-50628720","https://www.cbsnews.com/news/villa-union-coahuila-shootout-mexico-death-toll-dead-cartel-cdn-siege-near-texas-border-2019-12-02/","https://en.wikipedia.org/wiki/2019_Villa_Uni%C3%B3n_shootout"]},{"id":"2019-garcia-luna-arrested-dallas","date":"2019-12-09","precision":"day","title":"Ex-security chief Genaro García Luna arrested in Dallas","summary":"On 9 December 2019 US agents arrested Genaro García Luna, Mexico's Secretary of Public Security under Felipe Calderón (2006–2012), in the Dallas area (Grapevine, Texas) on Eastern District of New York charges of taking millions of dollars in bribes from the Sinaloa Cartel and lying to US immigration authorities. He was convicted in Brooklyn on 21 February 2023 and sentenced to 38 years in October 2024.","impact":"The highest-ranking Mexican official ever tried in the US for cartel collusion, his case discredited the architecture of the Calderón-era drug war and became a political weapon for López Obrador against his predecessors.","state":"US","city":"Dallas, Texas","lat":32.7767,"lng":-96.797,"cartels":["sinaloa","us_government","government"],"figures":["Genaro García Luna","Felipe Calderón Hinojosa"],"type":"corruption","importance":5,"confidence":"high","sources":["https://www.justice.gov/usao-edny/pr/former-mexican-secretary-public-security-arrested-drug-trafficking-conspiracy-and","https://www.nytimes.com/2023/02/21/nyregion/genaro-garcia-luna-guilty.html"]},{"id":"2020-record-homicides-2019-reported","date":"2020-01-20","precision":"day","title":"2019 confirmed as Mexico's most violent year on record","summary":"On 20 January 2020 the SESNSP published year-end data showing 34,582 victims of intentional homicide plus 1,006 femicide victims in 2019 (35,588 in total), the highest figure since records began and above 2018's previous record. INEGI's later mortality count put 2019 homicides at 36,661. Guanajuato, Baja California, Estado de México, Chihuahua and Jalisco led the tally.","impact":"The record undercut López Obrador's promise that his non-confrontational strategy would quickly reduce violence and set the plateau of roughly 34,000–35,000 annual homicide victims that persisted through 2020–2021.","state":"MULTI","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["government"],"figures":["Andrés Manuel López Obrador","Alfonso Durazo Montaño"],"type":"other","importance":4,"confidence":"high","sources":["https://www.elfinanciero.com.mx/nacional/se-registran-34-mil-582-homicidios-dolosos-en-mexico-durante-2019/","https://www.noroeste.com.mx/nacional/2019-ano-mas-violento-de-la-historia-reciente-34-mil-582-homicidios-LTNO1185259","https://diario.mx/nacional/2020/jan/20/fue-2019-el-ano-mas-violento-de-mexico-520194.html"]},{"id":"2020-el-menchito-extradited","date":"2020-02-20","precision":"day","title":"Rubén 'El Menchito' Oseguera extradited to the United States","summary":"On 20 February 2020 Mexico extradited Rubén Oseguera González, 'El Menchito', son of CJNG leader Nemesio Oseguera and the cartel's former second-in-command, to the United States, where he landed at Dulles airport and was arraigned in Washington, DC, the next day on trafficking and firearms charges. He was convicted in September 2024 and sentenced to life plus 30 years on 7 March 2025.","impact":"The extradition, after years of legal delays in Mexico, was the first major US judicial blow to El Mencho's inner circle and preceded the arrest of his daughter Jessica in Washington days later.","state":"US","city":"Washington, DC","lat":38.9072,"lng":-77.0369,"cartels":["cjng","us_government","government"],"figures":["Rubén 'El Menchito' Oseguera González","Nemesio 'El Mencho' Oseguera Cervantes"],"type":"extradition","importance":4,"confidence":"high","sources":["https://www.upi.com/Top_News/US/2020/02/21/Mexican-cartel-leader-El-Menchito-extradited-to-US/4441582309211/","https://abcnews.go.com/International/wireStory/mexico-extradites-son-jalisco-cartel-face-us-charges-69125126","https://www.justice.gov/opa/pr/notorious-violent-mexican-cartel-leader-sentenced-life-plus-30-years-prison-international"]},{"id":"2020-harfuch-assassination-attempt","date":"2020-06-26","precision":"day","title":"CJNG hit squad ambushes Mexico City police chief García Harfuch","summary":"At 06:38 on 26 June 2020 some two dozen gunmen with .50-calibre rifles and grenades ambushed the armoured vehicle of Mexico City security secretary Omar García Harfuch on Paseo de la Reforma in Lomas de Chapultepec, firing more than 400 rounds in about three minutes. Two bodyguards and a passing woman were killed; Harfuch was hit three times and survived. He blamed the CJNG; at least a dozen attackers were arrested that day, and in March 2024 twelve were convicted with combined sentences of more than 316 years.","impact":"The first cartel attempt on a senior official in the capital's wealthiest district signalled the CJNG's willingness to strike the state directly and elevated Harfuch as the face of a tougher security line.","state":"CMX","city":"Lomas de Chapultepec, Ciudad de México","lat":19.4275,"lng":-99.2125,"cartels":["cjng","government"],"figures":["Omar García Harfuch","Claudia Sheinbaum","Nemesio 'El Mencho' Oseguera Cervantes"],"type":"attack","importance":4,"confidence":"high","sources":["https://www.reuters.com/article/us-mexico-violence/mexico-city-police-chief-shot-and-injured-in-assassination-attempt-idUSKBN23X1T8","https://mexiconewsdaily.com/news/mexico-city-police-chief-wounded-in-armed-attack-3-people-killed/","https://en.wikipedia.org/wiki/Omar_Garc%C3%ADa_Harfuch"]},{"id":"2020-irapuato-rehab-centre-massacre","date":"2020-07-01","precision":"day","title":"27 killed at an Irapuato drug rehabilitation centre","summary":"At about 17:45 on 1 July 2020 gunmen entered the unregistered 'Buscando el Camino a mi Recuperación' rehabilitation centre in Irapuato, Guanajuato, forced the residents to the floor and shot them, killing 24 at the scene; the toll reached 27, with five wounded. A separate attack on another Irapuato rehab centre had killed ten on 6 June. Authorities attributed the massacre to a local cell allied with the Santa Rosa de Lima Cartel, acting on El Marro's orders in its war with the CJNG for control of the Bajío.","impact":"The deadliest shooting massacre of the López Obrador presidency to that point crystallised Guanajuato's status as Mexico's most violent state and increased pressure that led to El Marro's capture a month later.","state":"GUA","city":"Irapuato","lat":20.6767,"lng":-101.3564,"cartels":["santa_rosa_lima","cjng"],"figures":["José Antonio 'El Marro' Yépez Ortiz"],"type":"massacre","importance":4,"confidence":"high","sources":["https://www.reuters.com/article/us-mexico-violence/24-people-killed-in-attack-in-central-mexico-media-reports-idUSKBN2427M4","https://www.jornada.com.mx/ultimas/estados/2020/07/02/irapuato-asesinan-a-28-en-un-centro-de-rehabilitacion-3459.html","https://en.wikipedia.org/wiki/2020_Irapuato_massacres"]},{"id":"2020-cjng-armored-convoy-video","date":"2020-07-17","precision":"day","title":"CJNG releases video of armoured convoy chanting for El Mencho","summary":"On 17 July 2020, El Mencho's birthday, a video circulated showing a long column of CJNG fighters in matching camouflage and body armour beside dozens of armoured trucks, chanting 'pura gente del señor Mencho'. The Defence Ministry said it was analysing the footage, filmed at an undisclosed location believed to be in Jalisco; a second video followed days later.","impact":"The most widely seen display of cartel paramilitary capacity to date, it fixed the image of the CJNG as Mexico's most militarised criminal group and was cited in US and Mexican debates over the government's passive strategy.","state":"JAL","city":"Undisclosed location, Jalisco (mapped to Guadalajara)","lat":20.6597,"lng":-103.3496,"cartels":["cjng"],"figures":["Nemesio 'El Mencho' Oseguera Cervantes"],"type":"other","importance":3,"confidence":"medium","sources":["https://mexiconewsdaily.com/news/cartel-demonstrates-its-firepower/","https://www.courier-journal.com/story/news/crime/2020/07/23/video-armored-cjng-cartel-soldiers-praising-el-mencho-goes-viral/"]},{"id":"2020-el-marro-arrested","date":"2020-08-02","precision":"day","title":"El Marro, Santa Rosa de Lima Cartel boss, captured in Guanajuato","summary":"Before dawn on 2 August 2020 army and Guanajuato state forces captured José Antonio Yépez Ortiz, 'El Marro', leader of the Santa Rosa de Lima Cartel, at a safe house in the municipality of Santa Cruz de Juventino Rosas, along with five associates, and freed a kidnapped businesswoman. He was sentenced to 60 years for aggravated kidnapping on 14 January 2022.","impact":"The fall of the fuel-theft kingpin ended the Santa Rosa de Lima Cartel as a coherent rival, but the CJNG's advance and fragmented local cells kept Guanajuato the country's homicide leader.","state":"GUA","city":"Santa Cruz de Juventino Rosas","lat":20.644,"lng":-100.992,"cartels":["santa_rosa_lima","cjng","government"],"figures":["José Antonio 'El Marro' Yépez Ortiz","Diego Sinhue Rodríguez Vallejo","Alfonso Durazo Montaño"],"type":"capture","importance":4,"confidence":"high","sources":["https://www.cnn.com/2020/08/02/americas/mexico-cartel-el-marro-arrest/index.html","https://www.reuters.com/world/americas/mexican-cartel-boss-fuel-theft-king-sentenced-60-years-prison-2022-01-15/","https://en.wikipedia.org/wiki/Jos%C3%A9_Antonio_Y%C3%A9pez_Ortiz"]},{"id":"2020-cienfuegos-arrested-los-angeles","date":"2020-10-15","precision":"day","title":"Gen. Cienfuegos arrested at LAX, freed and later cleared by Mexico","summary":"On 15 October 2020 US agents arrested General Salvador Cienfuegos, Mexico's defence secretary from 2012 to 2018, at Los Angeles airport on Brooklyn charges of protecting the H-2 cartel, a Beltrán Leyva remnant in Nayarit. After intense Mexican pressure the US dropped the charges and returned him on 18 November 2020; Mexico's Congress passed a law restricting foreign agents in December, and the FGR exonerated him on 14 January 2021.","impact":"The episode triggered the deepest rupture in US–Mexico security cooperation in decades, curtailed DEA operations in Mexico and showed the limits of the armed forces' accountability during the López Obrador years.","state":"US","city":"Los Angeles, California","lat":33.9416,"lng":-118.4085,"cartels":["beltran_leyva","us_government","government"],"figures":["Salvador Cienfuegos Zepeda","Alejandro Gertz Manero","Andrés Manuel López Obrador","Marcelo Ebrard","William Barr"],"type":"corruption","importance":5,"confidence":"high","sources":["https://www.nytimes.com/2020/10/16/us/mexico-general-cienfuegos-dea.html","https://www.bbc.com/news/world-latin-america-55331535","https://en.wikipedia.org/wiki/Salvador_Cienfuegos_Zepeda"]},{"id":"2021-camargo-migrant-massacre","date":"2021-01-22","precision":"day","title":"Camargo massacre: 19 migrants and others shot and burned by state police","summary":"On 22 January 2021, in the ejido of Santa Anita in Camargo, Tamaulipas, near the Rio Grande, the charred bodies of 19 people were found inside two vehicles: 16 Guatemalan migrants, two Mexicans and one Salvadoran, the latter linked to the smuggling network. The truck bore 113 bullet holes but almost no casings were found, because the shooters had collected them. Twelve officers of the Tamaulipas state police special-operations group (GOPES) were charged; in late 2023 eleven were sentenced to 50 years and a twelfth, who cooperated, to 19 years.","impact":"The worst migrant massacre in Tamaulipas since San Fernando revealed a state police unit acting as a death squad in a corridor disputed by the Gulf Cartel and the Cártel del Noreste, and prompted Guatemala and human-rights bodies to demand accountability.","state":"TAM","city":"Santa Anita, Camargo","lat":26.3156,"lng":-98.8333,"cartels":["government","gulf","cdn"],"figures":[],"type":"massacre","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Camargo_massacre","https://www.cbsnews.com/news/mexico-police-officers-sentenced-2021-killings-of-migrants-tamaulipas","https://insightcrime.org/news/us-trained-police-mexico-migrant-massacre/"]},{"id":"2021-coatepec-harinas-police-ambush","date":"2021-03-18","precision":"day","title":"Familia Michoacana ambush kills 13 police in Coatepec Harinas","summary":"On 18 March 2021 gunmen ambushed a joint convoy of Estado de México state police and state prosecutors' agents near Llano Grande, Coatepec Harinas, killing 13 officers (eight state police and five prosecution agents) in the deadliest attack on Mexican police since the 2019 El Aguaje ambush. Authorities blamed La Familia Michoacana, led by the Hurtado Olascoaga brothers, which controls the mountainous south of the state.","impact":"The attack exposed the Hurtado brothers' Familia Michoacana as a major regional power straddling Estado de México and Guerrero and prompted a large federal deployment to the southern Estado de México.","state":"MEX","city":"Llano Grande, Coatepec Harinas","lat":18.9236,"lng":-99.7686,"cartels":["nueva_familia_michoacana","government"],"figures":["Johnny Hurtado Olascoaga","Alfredo del Mazo Maza"],"type":"attack","importance":4,"confidence":"high","sources":["https://www.reuters.com/world/americas/gunmen-kill-13-police-ambush-central-mexico-2021-03-19/","https://www.nytimes.com/2021/03/18/world/americas/mexico-police-ambush.html","https://justiceinmexico.org/13-edomex-killed-ambush/"]},{"id":"2021-aguililla-siege-drone-attacks","date":"2021-04-20","precision":"day","title":"Aguililla siege: CJNG explosive drones attack police at El Aguaje","summary":"In the early hours of 20 April 2021 CJNG gunmen attacked state police stationed in El Aguaje, Aguililla, with grenades, gunfire and drones rigged with explosives, wounding two officers, the first confirmed cartel drone attack to injure Mexican security forces. It came amid an April 2021 battle in which the CJNG, using trenches and roadblocks against Cárteles Unidos, isolated Aguililla; the town had been largely cut off since late 2020 and the papal nuncio Franco Coppola visited on 23 April. The army and National Guard retook El Aguaje and Aguililla on 10 February 2022.","impact":"Aguililla became the emblem of state absence under 'hugs not bullets' and of the CJNG–Cárteles Unidos war, and the drone attacks opened a new era of improvised aerial weapons in Mexican cartel conflict.","state":"MIC","city":"Aguililla","lat":18.7377,"lng":-102.79,"cartels":["cjng","carteles_unidos","government"],"figures":["Nemesio 'El Mencho' Oseguera Cervantes","Juan José 'El Abuelo' Farías","Franco Coppola"],"type":"battle","importance":4,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Capture_of_Aguililla","https://news.yahoo.com/mexico-cartel-attacks-police-exploding-014112132.html","https://en.wikipedia.org/wiki/Aguililla"]},{"id":"2021-midterm-election-violence","date":"2021-06-06","precision":"day","title":"2021 midterms: Mexico's bloodiest election since 2000","summary":"Mexico's 6 June 2021 midterm elections, the largest ever, followed a campaign in which the consultancy Etellekt counted 102 politicians murdered during the 2020–2021 electoral process, 36 of them candidates or aspirants, with hundreds more threatened or attacked. Emblematic killings included former Sonora prosecutor and Cajeme mayoral candidate Abel Murrieta (13 May) and Moroleón candidate Alma Rosa Barragán (25 May), shot at a campaign rally.","impact":"The violence showed cartels systematically selecting municipal power in disputed states such as Guanajuato, Michoacán, Veracruz and Sonora, and made local political capture a central feature of the era.","state":"MULTI","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["other"],"figures":["Abel Murrieta Gutiérrez","Alma Rosa Barragán Santiago"],"type":"other","importance":4,"confidence":"high","sources":["https://aristeguinoticias.com/2206/mexico/fueron-102-los-politicos-asesinados-durante-el-proceso-electoral-2020-2021-etellekt/","https://www.razon.com.mx/mexico/2021/06/05/elecciones-2021-suman-91-politicos-asesinados-en-el-proceso-electoral/","https://www.jornada.com.mx/noticia/2021/06/22/politica/fueron-asesinados-102-politicos-en-pasado-proceso-electoral-consultora-2472"]},{"id":"2021-reynosa-civilian-massacre","date":"2021-06-19","precision":"day","title":"Gulf Cartel gunmen kill 15 civilians in Reynosa","summary":"On the afternoon of 19 June 2021 armed commandos drove through several eastern neighbourhoods of Reynosa, Tamaulipas, shooting bystanders at random, taxi drivers, workers and a nursing student among them. Fifteen civilians were killed and four gunmen died in subsequent clashes with state forces, 19 dead in all. Authorities attributed the attack to the Matamoros-based Escorpiones/Ciclones faction of the Gulf Cartel moving against the Metros faction that controls Reynosa.","impact":"One of the clearest cases of cartel terror deliberately aimed at civilians, it laid bare the Gulf Cartel's internal war and led to dozens of arrests but no lasting pacification of the border city.","state":"TAM","city":"Reynosa","lat":26.0922,"lng":-98.2775,"cartels":["gulf"],"figures":[],"type":"massacre","importance":4,"confidence":"high","sources":["https://www.theguardian.com/world/2021/jun/21/mexico-reynosa-gang-violence","https://apnews.com/article/caribbean-mexico-arrests-shootings-73b2ad8f96a26aee43a072ad4a6fe36e","https://www.ksat.com/news/world/2021/06/23/infighting-in-gulf-cartel-blamed-for-shooting-that-killed-19-on-mexico-border/"]},{"id":"2021-bicentennial-framework-replaces-merida","date":"2021-10-08","precision":"day","title":"US–Mexico Bicentennial Framework replaces the Mérida Initiative","summary":"On 8 October 2021 the US–Mexico High-Level Security Dialogue in Mexico City, led by Secretary of State Antony Blinken, Attorney General Merrick Garland, Homeland Security Secretary Alejandro Mayorkas and Foreign Minister Marcelo Ebrard, launched the Bicentennial Framework for Security, Public Health and Safe Communities, formally ending the 2008 Mérida Initiative. The framework emphasises public health, addiction, arms trafficking and prosecutions over military assistance.","impact":"The agreement reset bilateral security cooperation after the Cienfuegos crisis on Mexico's terms of 'sovereignty', shifting rhetoric from kingpin removal to root causes and arms flows while fentanyl deaths in the US surged.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["us_government","government"],"figures":["Antony Blinken","Marcelo Ebrard","Merrick Garland","Alejandro Mayorkas","Rosa Icela Rodríguez"],"type":"policy","importance":4,"confidence":"high","sources":["https://bidenwhitehouse.archives.gov/briefing-room/statements-releases/2021/10/08/fact-sheet-u-s-mexico-high-level-security-dialogue/","https://www.state.gov/summary-of-the-action-plan-for-u-s-mexico-bicentennial-framework-for-security-public-health-and-safe-communities/","https://mx.usembassy.gov/joint-statement-u-s-mexico-high-level-security-dialogue/"]},{"id":"2021-tulum-tourists-shot","date":"2021-10-20","precision":"day","title":"Two foreign tourists killed in Tulum crossfire","summary":"On the night of 20 October 2021 gunmen from rival local drug-dealing cells exchanged fire at the La Malquerida restaurant-bar in downtown Tulum, Quintana Roo. Anjali Ryot, an Indian-born travel blogger living in California, and German tourist Jennifer Henzold were killed and three other foreigners were wounded. Prosecutors blamed a dispute between gangs fighting for retail drug sales in the resort.","impact":"The killings, followed weeks later by a shootout at a Puerto Morelos hotel, put the Riviera Maya's gang wars on the international agenda and prompted the deployment of a roughly 1,500-strong 'tourist battalion' of the National Guard.","state":"ROO","city":"Tulum","lat":20.2114,"lng":-87.4654,"cartels":["other"],"figures":["Anjali Ryot","Jennifer Henzold","Carlos Joaquín González"],"type":"attack","importance":3,"confidence":"high","sources":["https://www.theguardian.com/world/2021/oct/21/mexico-tulum-shootout-foreign-women-killed","https://mexiconewsdaily.com/news/2-foreign-tourists-killed-while-caught-in-the-crossfire-of-tulum-shootout/"]},{"id":"2021-chiapas-frontera-comalapa-war-begins","date":"2021-11-10","precision":"day","title":"Sinaloa–CJNG war erupts around Frontera Comalapa, Chiapas","summary":"After CJNG-linked gunmen killed Gilberto Rivera Maravilla, 'El Junior', son and successor of the Sinaloa Cartel's long-time Chiapas boss Gilberto 'El Tío Gil' Rivera Amarillas, in Tuxtla Gutiérrez on 7 July 2021, the CJNG pushed into the Sierra Madre border corridor. According to El Universal the conflict broke into the open on 10 November 2021 with the execution of local Sinaloa operator José Fernando Cruz Montejo, 'El Poni', and two bodyguards in Quespala, Frontera Comalapa (other accounts date that killing to 27 December 2020), followed by shootouts, blockades and forced displacement across Frontera Comalapa, Chicomuselo and Motozintla.","impact":"The war turned Mexico's southern border, previously a Sinaloa-controlled transit zone for migrants and cocaine, into a battlefield, displaced thousands and led to the emergence of the CJNG-aligned Cártel de Chiapas y Guatemala.","state":"CHP","city":"Frontera Comalapa","lat":15.66,"lng":-92.14,"cartels":["sinaloa","cjng","chiapas_guatemala"],"figures":["Gilberto 'El Junior' Rivera Maravilla","Gilberto 'El Tío Gil' Rivera Amarillas","José Fernando 'El Poni' Cruz Montejo"],"type":"battle","importance":4,"confidence":"low","sources":["https://insightcrime.org/news/chiapas-bleeds-cjng-sinaloa-cartel-guatemala-trafficking-routes/","https://www.eluniversal.com.mx/estados/mas-de-tres-anos-de-terror-en-frontera-comalapa/","https://zetatijuana.com/2021/07/cjng-asesina-a-el-junior-hijo-de-el-tio-gil-lugarteniente-del-cartel-de-sinaloa-en-chiapas/"]},{"id":"2021-zacatecas-bodies-hung-cuauhtemoc","date":"2021-11-18","precision":"day","title":"Zacatecas war peaks: ten bodies hung and dumped in Cuauhtémoc","summary":"At dawn on 18 November 2021 nine bodies were found hanging from a highway overpass on Federal Highway 45 in Cuauhtémoc, Zacatecas, with a tenth on the road below, the most graphic episode of the war between the CJNG and the Sinaloa Cartel (with local allies such as Los Talibanes) for the state's trafficking corridors. Days later the federal government launched 'Plan de Apoyo a Zacatecas II', sending thousands more soldiers and Guardsmen. Zacatecas ended 2021 with Mexico's highest homicide rate.","impact":"The war, which had escalated since 2020, turned a previously peripheral state into the country's deadliest per capita, produced mass displacement from rural municipalities and became the leading test of the new Monreal administration and federal strategy.","state":"ZAC","city":"Cuauhtémoc","lat":22.449,"lng":-102.349,"cartels":["cjng","sinaloa","talibanes","government"],"figures":["David Monreal Ávila","Andrés Manuel López Obrador"],"type":"battle","importance":4,"confidence":"medium","sources":["https://www.washingtonpost.com/world/2022/01/07/mexico-zacatecas-violence-murders/","https://es.wikipedia.org/wiki/Los_Talibanes"]},{"id":"2022-zacatecas-ten-bodies-governors-palace","date":"2022-01-06","precision":"day","title":"SUV with ten bodies left outside Zacatecas governor's palace","summary":"At about 05:30 on 6 January 2022 a silver Mazda SUV containing ten bodies, eight men and two women, most of them strangled and showing signs of having been bound, was abandoned in the Plaza de Armas beside the Christmas tree in front of the Palacio de Gobierno in Zacatecas city. Governor David Monreal filmed the scene himself. Prosecutors said most victims were from Sinaloa and linked to a cartel there, tied the driver to the CJNG, and arrested suspects within days.","impact":"The body dump at the seat of state power became the international symbol of Zacatecas's collapse and prompted President López Obrador to visit the state and expand the federal deployment.","state":"ZAC","city":"Zacatecas","lat":22.7709,"lng":-102.5833,"cartels":["cjng","sinaloa"],"figures":["David Monreal Ávila","Andrés Manuel López Obrador"],"type":"massacre","importance":4,"confidence":"high","sources":["https://www.reuters.com/world/americas/ten-bodies-left-car-outside-mexican-state-governors-office-2022-01-06/","https://animalpolitico.com/2022/01/abandonan-camioneta-seis-cuerpos-palacio-gobierno-zacatecas","https://www.sinembargo.mx/4098309/fiscalia-identifica-5-de-los-10-cuerpos-encontrados-en-plaza-de-armas-de-zacatecas/"]},{"id":"2022-mezcales-split-from-cjng-colima","date":"2022-02-01","precision":"month","title":"Los Mezcales break with the CJNG, igniting Colima's war","summary":"In late January 2022 José Bernabé Brizuela Meraz, 'La Vaca', head of the CJNG's Colima armed cell known as Los Mezcales, broke with the Jalisco cartel. A riot at the Colima state prison on 25 January killed nine inmates, and from 7–8 February gunfights, kidnappings and arson spread through Colima, Villa de Álvarez and Manzanillo, with 17 confirmed dead by 12 February and 47 by 24 February. Los Mezcales reportedly sought backing from Sinaloa Cartel networks, which the Sinaloa Cartel publicly disavowed in March.","impact":"The split made Colima, home to the port of Manzanillo, Mexico's highest-homicide-rate state in 2022 and showed the CJNG's vulnerability to fractures within its own franchises.","state":"COL","city":"Colima","lat":19.2433,"lng":-103.725,"cartels":["mezcales","cjng"],"figures":["José Bernabé 'La Vaca' Brizuela Meraz","Indira Vizcaíno Silva"],"type":"split","importance":4,"confidence":"medium","sources":["https://www.publimetro.com.mx/noticias/2022/02/15/la-bestia-un-personaje-clave-en-la-crisis-de-violencia-que-atraviesa-colima/","https://www.infobae.com/america/mexico/2022/01/26/cjng-esta-implicado-en-motin-del-penal-de-colima-titular-de-la-ssp-estatal/","https://es.wikipedia.org/wiki/Enfrentamientos_en_Colima"]},{"id":"2022-san-jose-de-gracia-wake-massacre","date":"2022-02-27","precision":"day","title":"Gunmen execute 17 mourners at a wake in San José de Gracia","summary":"On the afternoon of 27 February 2022 armed men arrived at a wake in San José de Gracia, Marcos Castellanos municipality, Michoacán, near the Jalisco border, lined the mourners against a wall and shot them. Video showed at least 17 people killed; the gunmen then removed the bodies and cleaned the scene before police arrived hours later, leaving prosecutors with only shell casings and blood. Officials described a vendetta between two rival CJNG-linked bosses, 'El Pelón' and 'El Toro', over the funeral of the former's mother.","impact":"The filmed execution and vanished bodies became a symbol of impunity in Michoacán and of the wave of violence that was driving an exodus from the state's Jalisco border and Tierra Caliente regions.","state":"MIC","city":"San José de Gracia, Marcos Castellanos","lat":19.99,"lng":-103.0217,"cartels":["cjng","other"],"figures":["Alfredo Ramírez Bedolla"],"type":"massacre","importance":4,"confidence":"high","sources":["https://insightcrime.org/news/funeral-massacre-latest-example-of-extreme-violence-causing-michoacan-exodus/","https://www.infobae.com/en/2022/03/14/massacre-in-san-jose-de-gracia-six-alleged-perpetrators-identified-michoacan-prosecutors-office-offers-reward/"]},{"id":"2022-el-huevo-trevino-captured-nuevo-laredo","date":"2022-03-13","precision":"day","title":"CDN boss 'El Huevo' Treviño captured; Nuevo Laredo erupts","summary":"On 13 March 2022 the army captured Juan Gerardo Treviño Chávez, 'El Huevo', leader of the Cártel del Noreste and nephew of Zetas founders Miguel Ángel and Omar Treviño Morales, in Nuevo Laredo, Tamaulipas. Gunmen responded with dozens of attacks on military installations, burning vehicles and firing on the US consulate. Treviño, a US citizen, was expelled to the United States rather than extradited the following day.","impact":"The most important blow to the Zetas successor organisation since 2013, it demonstrated the CDN's capacity to paralyse Mexico's busiest trade crossing and marked a rare use of rapid expulsion rather than extradition.","state":"TAM","city":"Nuevo Laredo","lat":27.4763,"lng":-99.5164,"cartels":["cdn","government","us_government"],"figures":["Juan Gerardo 'El Huevo' Treviño Chávez"],"type":"capture","importance":4,"confidence":"medium","sources":["https://www.milenio.com/policia/detienen-huevo-trevino-lider-cartel-noreste-nuevo-laredo","https://www.bbc.com/mundo/noticias-60756422"]},{"id":"2022-zinapecuaro-cockfight-massacre","date":"2022-03-27","precision":"day","title":"Cockfight massacre at Las Tinajas, Zinapécuaro, kills 20","summary":"At about 22:30 on 27 March 2022 gunmen with assault rifles opened fire on a clandestine cockfighting arena in Las Tinajas, Zinapécuaro, Michoacán, killing 20 people, 17 men and 3 women, and wounding five. Prosecutors linked the attack to the fight between the CJNG and La Familia Michoacana for eastern Michoacán; five suspects were arrested in Susupuato on 1 April.","impact":"Michoacán's second mass killing in a month reinforced the sense that the CJNG–Familia Michoacana war in the east of the state was as deadly as the Tierra Caliente front, and drew national attention to the criminal economy around cockfighting.","state":"MIC","city":"Las Tinajas, Zinapécuaro","lat":19.8681,"lng":-100.8175,"cartels":["cjng","nueva_familia_michoacana"],"figures":[],"type":"massacre","importance":4,"confidence":"high","sources":["https://www.bbc.com/news/world-latin-america-60900854","https://www.aljazeera.com/news/2022/3/28/at-least-19-killed-in-central-mexico-shooting-authorities","https://en.wikipedia.org/wiki/Las_Tinajas_massacre"]},{"id":"2022-cerocahui-jesuit-priests-killed","date":"2022-06-20","precision":"day","title":"Two Jesuit priests murdered in their church in Cerocahui","summary":"On 20 June 2022 José Noriel Portillo Gil, 'El Chueco', leader of a Sinaloa Cartel (Gente Nueva) cell in the Sierra Tarahumara, chased tour guide Pedro Palma Gutiérrez (60) into the church of Cerocahui, Urique, Chihuahua, and shot him dead along with Jesuit priests Javier Campos Morales (79) and Joaquín César Mora Salazar (80), who had tried to intervene. He took the bodies, which were recovered two days later. Portillo was found dead in Choix, Sinaloa, on 22 March 2023.","impact":"The killings produced an unprecedented confrontation between the Catholic Church and López Obrador over 'hugs not bullets' and spotlighted the Sinaloa Cartel's grip on Chihuahua's mountain communities.","state":"CHH","city":"Cerocahui, Urique","lat":27.2978,"lng":-108.0553,"cartels":["sinaloa"],"figures":["Javier Campos Morales","Joaquín César Mora Salazar","Pedro Eliodoro Palma Gutiérrez","José Noriel 'El Chueco' Portillo Gil"],"type":"killing","importance":4,"confidence":"high","sources":["https://www.theguardian.com/world/2022/jun/21/two-jesuits-priests-killed-mexico-church","https://www.cbsnews.com/news/priests-man-seeking-refuge-killed-inside-church-mexico/","https://es.wikipedia.org/wiki/Asesinatos_en_Cerocahui_de_2022"]},{"id":"2022-caro-quintero-captured-choix","date":"2022-07-15","precision":"day","title":"Caro Quintero captured in Choix; Black Hawk crash kills 14 marines","summary":"On 15 July 2022 Mexican marines, aided by a search dog named Max, found Rafael Caro Quintero hiding in brush at San Simón, in the municipality of Choix in the Sinaloa highlands, and arrested the Guadalajara Cartel founder wanted for the 1985 murder of DEA agent Enrique Camarena. The same day a Navy Black Hawk supporting the operation crashed near Los Mochis, killing 14 of the 15 marines aboard. Caro Quintero was sent to the Altiplano prison and was transferred to the United States, outside the formal extradition process, with 28 other prisoners on 27 February 2025.","impact":"The capture of the DEA's most wanted fugitive, three days after President López Obrador met Joe Biden at the White House, was the biggest arrest of the López Obrador presidency and struck the Caborca Cartel he had led against Los Chapitos in Sonora.","state":"SIN","city":"San Simón, Choix","lat":26.7086,"lng":-108.3253,"cartels":["caborca","guadalajara","government","us_government"],"figures":["Rafael Caro Quintero"],"type":"capture","importance":5,"confidence":"high","sources":["https://apnews.com/article/drug-lord-rafael-caro-quintero-captured-mexico-dea-7ff3005d4c848697458d73c669a72e6f","https://en.wikipedia.org/wiki/Rafael_Caro_Quintero"]},{"id":"2022-cjng-riots-jalisco-guanajuato","date":"2022-08-09","precision":"day","title":"CJNG torches vehicles and shops across Jalisco and Guanajuato","summary":"On the evening of 9 August 2022, after soldiers clashed with CJNG gunmen at a meeting of cartel commanders on the border of Ixtlahuacán del Río and Cuquío, Jalisco, about 50 km from Guadalajara, in an operation aimed at Ricardo Ruiz Velasco, 'El Doble R' (who was not captured), cartel cells burned dozens of vehicles and some 25 Oxxo convenience stores and set up blockades across the Guadalajara metropolitan area and at least a dozen Guanajuato cities including Celaya, Irapuato, León and Silao.","impact":"The coordinated 'narcobloqueos' opened a week of cartel violence across four states and demonstrated the CJNG's ability to shut down two of Mexico's most important industrial regions at will.","state":"JAL","city":"Guadalajara metropolitan area (triggered in Ixtlahuacán del Río)","lat":20.6597,"lng":-103.3496,"cartels":["cjng","government"],"figures":["Ricardo 'El Doble R' Ruiz Velasco","Enrique Alfaro Ramírez","Diego Sinhue Rodríguez Vallejo"],"type":"attack","importance":4,"confidence":"high","sources":["https://www.jornada.com.mx/notas/2022/08/10/estados/bloqueos-y-quema-de-vehiculos-y-tiendas-en-jalisco-y-guanajuato/","https://www.informador.mx/amp/jalisco/CJNG-Quien-es-El-Doble-R-relacionado-con-los-bloqueos-en-Jalisco-y-Guanajuato-20220810-0145.html","https://www.radioformula.com.mx/nacional/2022/8/10/narcobloqueos-del-cjng-por-que-quemaron-oxxos-en-guanajuato-727258.html"]},{"id":"2022-juarez-prison-riot-rampage","date":"2022-08-11","precision":"day","title":"Juárez prison brawl spills into street rampage; 11 killed","summary":"On the afternoon of 11 August 2022 a fight between Los Mexicles and the rival Los Chapos inside Cereso No. 3 in Ciudad Juárez killed two inmates and injured about 20. Mexicles gunmen then attacked civilians across the city, shooting up convenience stores and a pizzeria and killing nine people, including four employees of the MegaRadio station and an Oxxo worker, for a total of 11 dead.","impact":"The deliberate killing of bystanders as a message to the state, alongside the Jalisco–Guanajuato and Baja California attacks the same week, marked a new level of cartel terror tactics; the prison was stormed on 1 January 2023 to free the Mexicles' leader, leaving 17 dead.","state":"CHH","city":"Ciudad Juárez","lat":31.6904,"lng":-106.4245,"cartels":["sinaloa","other"],"figures":["Cruz Pérez Cuéllar","Maru Campos"],"type":"attack","importance":4,"confidence":"high","sources":["https://riodoce.mx/2022/08/15/el-culiacanazo-ahora-en-guanajuato-jalisco-ciudad-juarez-y-baja-california/","https://es.wikipedia.org/wiki/Anexo:Cronolog%C3%ADa_de_la_guerra_contra_el_narcotr%C3%A1fico_en_M%C3%A9xico","https://en.wikipedia.org/wiki/Los_Mexicles"]},{"id":"2022-baja-california-narco-blockades","date":"2022-08-12","precision":"day","title":"Narco-blockades and arson paralyse Tijuana and Baja California","summary":"On the evening of Friday 12 August 2022 gunmen hijacked and burned some two dozen buses, taxis and private cars and set up blockades in Tijuana, Mexicali, Ensenada, Rosarito and Tecate, bringing Baja California's cities to a standstill. The US consulate in Tijuana told staff to shelter in place, authorities blamed the CJNG and 17 suspects were arrested; hundreds of additional National Guard troops were sent to the state in the following days.","impact":"Closing the week of nationwide cartel violence, the blockades in Mexico's busiest border metro showed the CJNG's reach in Sinaloa-dominated Baja California and prompted the largest federal reinforcement of Tijuana in years.","state":"BCN","city":"Tijuana","lat":32.5149,"lng":-117.0382,"cartels":["cjng","government"],"figures":["Marina del Pilar Ávila Olmeda","Montserrat Caballero Ramírez"],"type":"attack","importance":4,"confidence":"high","sources":["https://www.taiwannews.com.tw/en/news/4625635","https://riodoce.mx/2022/08/15/el-culiacanazo-ahora-en-guanajuato-jalisco-ciudad-juarez-y-baja-california/","https://es.wikipedia.org/wiki/Anexo:Cronolog%C3%ADa_de_la_guerra_contra_el_narcotr%C3%A1fico_en_M%C3%A9xico"]},{"id":"2022-murillo-karam-arrested-ayotzinapa","date":"2022-08-19","precision":"day","title":"Ex-attorney general Murillo Karam arrested over Ayotzinapa 'state crime'","summary":"On 18 August 2022 the presidential truth commission led by Alejandro Encinas declared the 2014 disappearance of the 43 Ayotzinapa students a 'crime of the state' involving Guerreros Unidos, municipal police, soldiers and federal officials. The next day, 19 August, former attorney general Jesús Murillo Karam, author of the discredited 'historical truth', was arrested outside his Mexico City home on charges of forced disappearance, torture and obstruction of justice, and 83 arrest warrants were sought, including for military personnel.","impact":"The first arrest of a former attorney general in Mexican history reopened the country's most notorious human-rights case, though the subsequent collapse of many warrants and the resignation of the special prosecutor limited its judicial results.","state":"CMX","city":"Ciudad de México","lat":19.4326,"lng":-99.1332,"cartels":["guerreros_unidos","government"],"figures":["Jesús Murillo Karam","Alejandro Encinas Rodríguez","Omar Gómez Trejo","Andrés Manuel López Obrador"],"type":"corruption","importance":4,"confidence":"high","sources":["https://www.nytimes.com/2022/08/20/world/americas/mexico-arrests-jesus-murillo-karam.html","https://www.cnn.com/2022/08/19/americas/jess-murillo-karam-mexico-missing-students-intl-latam","https://www.washingtonpost.com/world/2022/08/19/mexico-disappeared-students-ayotzinapa/"]},{"id":"2022-tony-montana-oseguera-arrested","date":"2022-12-20","precision":"day","title":"El Mencho's brother 'Tony Montana' arrested in Tlajomulco","summary":"On 20 December 2022 army special forces arrested Antonio Oseguera Cervantes, 'Tony Montana', brother of CJNG leader Nemesio Oseguera, in Tlajomulco de Zúñiga on the outskirts of Guadalajara, seizing rifles, ammunition and drugs. Accused of coordinating the cartel's weapons purchases, money laundering and logistics, he had been arrested in Tlajomulco on 3 December 2015 and released on 15 July 2016 after an appeals court found procedural violations.","impact":"The arrest, followed weeks later by the recapture of Ovidio Guzmán, signalled the López Obrador government's late shift toward high-value targets and struck the CJNG's financial and logistical inner circle.","state":"JAL","city":"Tlajomulco de Zúñiga","lat":20.4736,"lng":-103.4431,"cartels":["cjng","government"],"figures":["Antonio 'Tony Montana' Oseguera Cervantes","Nemesio 'El Mencho' Oseguera Cervantes"],"type":"capture","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Antonio_Oseguera_Cervantes","https://es.wikipedia.org/wiki/C%C3%A1rtel_de_Jalisco_Nueva_Generaci%C3%B3n"]},{"id":"2023-cereso3-juarez-prison-break","date":"2023-01-01","precision":"day","title":"El Neto's Mexicles storm Cereso 3 in Juárez: 19 dead, 30 escape","summary":"At about 7 a.m. on New Year's Day gunmen in armoured vehicles attacked Cereso No. 3 in Ciudad Juárez while inmates rioted inside, in an operation to free Los Mexicles boss Ernesto Alfredo Piñón de la Cruz, 'El Neto'. Ten guards, seven inmates and two attackers were killed and at least 30 prisoners escaped, El Neto among them. Chihuahua state police killed El Neto in a shootout in Juárez in the early hours of 5 January 2023, four days after his escape.","impact":"The deadliest prison break of the decade exposed cartel control inside state prisons; the prison director was removed and the federal government pushed to take over state penitentiaries. It also inflamed the Mexicles (Sinaloa-aligned) versus La Línea war for Juárez.","state":"CHH","city":"Ciudad Juárez","lat":31.6904,"lng":-106.4245,"cartels":["other","sinaloa","juarez","government"],"figures":["Ernesto Alfredo Piñón de la Cruz 'El Neto'"],"type":"escape","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/2023_Ciudad_Ju%C3%A1rez_prison_attack","https://elpasomatters.org/2023/01/02/guards-prisoners-killed-prison-escape-juarez/"]},{"id":"2023-ovidio-guzman-captured-jesus-maria","date":"2023-01-05","precision":"day","title":"Ovidio Guzmán captured in Jesús María; Culiacán erupts","summary":"Army special forces captured Ovidio Guzmán López, 'El Ratón', at dawn in Jesús María, north of Culiacán, after months of surveillance in a joint US-Mexican intelligence effort (Operation Mongoose Azteca). Chapitos gunmen answered with blockades, burning vehicles and attacks on the airport and military aircraft. Ten soldiers, one police officer and 19 gunmen were killed before Guzmán was flown to Mexico City and then to the Altiplano prison.","impact":"Reversed the humiliating 2019 'Culiacanazo' release and opened the path to Ovidio's September 2023 extradition and eventual cooperation with US prosecutors, while demonstrating the Chapitos' capacity to paralyse a state capital.","state":"SIN","city":"Jesús María, Culiacán","lat":24.9667,"lng":-107.3833,"cartels":["chapitos","sinaloa","government","us_government"],"figures":["Ovidio Guzmán López","Luis Cresencio Sandoval","Andrés Manuel López Obrador"],"type":"capture","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/2023_Sinaloa_unrest","https://en.wikipedia.org/wiki/Operation_Mongoose_Azteca","https://www.washingtonpost.com/world/2023/01/05/mexico-ovidio-guzman-el-chapo/"]},{"id":"2023-garcia-luna-convicted","date":"2023-02-21","precision":"day","title":"García Luna convicted in Brooklyn of taking Sinaloa Cartel bribes","summary":"A federal jury in the Eastern District of New York found Genaro García Luna, Mexico's public security secretary under Felipe Calderón (2006-2012), guilty on all five counts, including cocaine trafficking conspiracy, continuing criminal enterprise and false statements. Prosecutors showed he took millions in bribes from the Sinaloa Cartel and Beltrán Leyva figures while running the war on drugs.","impact":"The highest-ranking Mexican official ever convicted in the United States; the verdict discredited the Calderón-era security strategy and became a political weapon for Morena.","state":"US","city":"Brooklyn, New York","lat":40.6928,"lng":-73.9903,"cartels":["sinaloa","beltran_leyva","government","us_government"],"figures":["Genaro García Luna","Brian Cogan"],"type":"trial","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Genaro_Garc%C3%ADa_Luna"]},{"id":"2023-matamoros-americans-kidnapped","date":"2023-03-03","precision":"day","title":"Gulf Cartel gunmen kidnap four Americans in Matamoros","summary":"Four US citizens from South Carolina who had driven into Matamoros for a medical appointment were shot at and abducted by Gulf Cartel gunmen; Shaeed Woodard and Zindell Brown were killed and a Mexican bystander, Areli Pablo Servando, also died. Latavia McGee and a wounded Eric Williams were rescued on 7 March. On 9 March the cartel's Grupo Escorpión left five bound men at the scene with a letter apologising to the victims and to Matamoros residents.","impact":"The case drove US calls to designate cartels as terrorist organisations and to authorise military force, previewing the 2025 policy shift, and illustrated the cartel's attempt to manage its image under pressure.","state":"TAM","city":"Matamoros","lat":25.869,"lng":-97.5027,"cartels":["gulf","government","us_government"],"figures":["Latavia McGee","Eric Williams","Shaeed Woodard","Zindell Brown"],"type":"attack","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/2023_Matamoros_kidnappings"]},{"id":"2023-chapitos-fentanyl-indictments","date":"2023-04-14","precision":"day","title":"US unseals fentanyl indictments against Los Chapitos","summary":"The Justice Department announced indictments in the Southern District of New York, the District of Columbia and the Northern District of Illinois charging 28 members of the Sinaloa Cartel's Chapitos network, including Iván Archivaldo and Jesús Alfredo Guzmán Salazar, Ovidio and Joaquín Guzmán López, with fentanyl trafficking, money laundering and weapons crimes. Treasury sanctions and State Department rewards were issued alongside.","impact":"Made El Chapo's sons the public face of the US fentanyl crisis and framed the pressure campaign that culminated in Ovidio's extradition, El Mayo's 2024 capture and the 2025 terrorist designations.","state":"US","city":"Washington, D.C.","lat":38.9072,"lng":-77.0369,"cartels":["chapitos","sinaloa","us_government"],"figures":["Iván Archivaldo Guzmán Salazar","Jesús Alfredo Guzmán Salazar","Ovidio Guzmán López","Joaquín Guzmán López","Merrick Garland"],"type":"trial","importance":4,"confidence":"high","sources":["https://www.justice.gov/opa/pr/justice-department-announces-charges-against-sinaloa-cartel-s-global-operation"]},{"id":"2023-hipolito-mora-killed","date":"2023-06-29","precision":"day","title":"Autodefensa founder Hipólito Mora assassinated in La Ruana","summary":"Gunmen ambushed Hipólito Mora, founder of Michoacán's 2013 self-defence movement, in La Ruana (Felipe Carrillo Puerto, Buenavista), riddling and torching his armoured pickup; Mora and three bodyguards were killed. Michoacán prosecutors blamed Los Viagras, the Cárteles Unidos faction that dominates the Tierra Caliente lime economy, and arrested suspects including Brayan 'N' (December 2023), 'El Rojo' (May 2024) and 'El Betillo' (January 2026); 'El Conejo' or 'El Conejillo' was detained in California on 24 July 2026 and Michoacán requested his extradition.","impact":"Closed the autodefensa era symbolically: the man who took up arms against the Knights Templar was killed by the successor groups, underscoring Cárteles Unidos' and CJNG's grip on Tierra Caliente.","state":"MIC","city":"La Ruana, Buenavista","lat":19.083,"lng":-102.533,"cartels":["carteles_unidos","autodefensas"],"figures":["Hipólito Mora"],"type":"killing","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Hip%C3%B3lito_Mora","https://www.infobae.com/mexico/2026/08/11/michoacan-pide-a-eeuu-extradicion-de-el-conejo-presunto-implicado-en-asesinato-de-hipolito-mora/","https://www.jornada.com.mx/noticia/2026/01/02/estados/detienen-a-el-betillo-presunto-implicado-en-el-asesinato-de-hipolito-mora"]},{"id":"2023-lagos-de-moreno-five-youths","date":"2023-08-11","precision":"day","title":"Five youths abducted and killed in Lagos de Moreno","summary":"Roberto Olmeda, Diego Lara, Uriel Galván, Jaime Martínez and Dante Cedillo, friends aged 19-22, vanished after a fair in Lagos de Moreno, Jalisco, on 11 August 2023. A video showed them beaten and forced to attack one another; charred remains were found in a burned car and at a brick kiln. Authorities attributed the crime to a CJNG cell (the 'GEDRI' group led by 'El Chilo'); ten suspects had been arrested by December 2023.","impact":"Became a national symbol of forced recruitment and youth disappearance in Jalisco, the state with the most missing people, and of the Sinaloa-CJNG dispute over Los Altos.","state":"JAL","city":"Lagos de Moreno","lat":21.3565,"lng":-101.9297,"cartels":["cjng"],"figures":["Roberto Olmeda Cuéllar","Diego Alberto Lara Santoyo","Uriel Galván González","Jaime Adolfo Martínez Miranda","Dante Cedillo Hernández"],"type":"massacre","importance":4,"confidence":"high","sources":["https://mexiconewsdaily.com/news/5-young-men-abducted-in-jalisco-presumed-dead/","https://mexiconewsdaily.com/news/5-more-suspects-arrested-in-lagos-de-moreno-abduction-case/"]},{"id":"2023-ovidio-guzman-extradited","date":"2023-09-15","precision":"day","title":"Ovidio Guzmán extradited to the United States","summary":"Mexico extradited Ovidio Guzmán López to the United States eight months after his capture; he was flown to Chicago to face fentanyl trafficking, money laundering and weapons charges in the Northern District of Illinois and pleaded not guilty days later.","impact":"The first Chapito in US custody; his eventual cooperation (guilty plea July 2025) and his brother Joaquín's delivery of El Mayo in 2024 flowed from this case.","state":"US","city":"Chicago, Illinois","lat":41.8781,"lng":-87.6298,"cartels":["chapitos","sinaloa","government","us_government"],"figures":["Ovidio Guzmán López"],"type":"extradition","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Ovidio_Guzm%C3%A1n_L%C3%B3pez"]},{"id":"2023-chapitos-fentanyl-ban-banners","date":"2023-10-02","precision":"day","title":"Chapitos banners 'ban' fentanyl in Sinaloa","summary":"Machine-printed narcomantas signed 'Att: Chapitos' appeared on Monday 2 October 2023 in Culiacán, Mazatlán, Guamúchil and Ahome declaring the sale, manufacture and transport of fentanyl, and of its precursors, strictly prohibited in Sinaloa, denying the group had ever dealt in the drug and threatening violators. Reports later that month documented killings and disappearances of cooks and dealers who defied the order.","impact":"Widely read as a public-relations move under US indictment pressure; it did not end production but shifted labs and marked the Chapitos' attempt to distance themselves from the fentanyl brand ahead of the 2024 rupture.","state":"SIN","city":"Culiacán","lat":24.8091,"lng":-107.394,"cartels":["chapitos","sinaloa"],"figures":["Iván Archivaldo Guzmán Salazar"],"type":"other","importance":3,"confidence":"high","sources":["https://mexiconewsdaily.com/news/banners-appear-in-sinaloa-signed-by-los-chapitos/"]},{"id":"2023-texcaltitlan-villagers-kill-extortionists","date":"2023-12-08","precision":"day","title":"Texcapilla villagers fight off Familia Michoacana extortionists","summary":"In Texcapilla, Texcaltitlán (State of Mexico), farmers armed with machetes, tools and a few guns confronted Familia Michoacana gunmen who had summoned them to demand extortion payments. Fourteen people died: ten gunmen, including regional boss Rigoberto de la Sancha Santillán 'El Payaso', and four villagers. In the following weeks 14 townspeople were kidnapped in reprisal and remained missing.","impact":"A rare community uprising against the Hurtado brothers' organisation that revealed the depth of extortion in the southern State of Mexico and triggered a federal deployment, but also brutal retaliation.","state":"MEX","city":"Texcapilla, Texcaltitlán","lat":18.9236,"lng":-100.0119,"cartels":["nueva_familia_michoacana","government"],"figures":["Rigoberto de la Sancha Santillán 'El Payaso'"],"type":"battle","importance":3,"confidence":"high","sources":["https://mexiconewsdaily.com/news/clash-between-farmers-and-alleged-cartel-members-leaves-14-dead/","https://mexiconewsdaily.com/news/kidnapped-farmers-cartel-texcaltitlan-deadly/"]},{"id":"2024-chicomuselo-massacre-chiapas-displacement","date":"2024-05-12","precision":"day","title":"Chicomuselo massacre amid Sinaloa–CJNG war displacing Chiapas","summary":"Eleven members of one family, five men, five women and a 15-year-old boy, including catechist Ignacio 'Nacho' López, were executed in Nueva Morelia, Chicomuselo, on the night of 12 May 2024 after refusing to work for the armed group controlling the area and opposing illegal mining; the attack was attributed to 'El Maíz', a CJNG armed wing. The killings were part of the Sinaloa Cartel-CJNG war over migrant and drug routes along the Guatemalan border (Frontera Comalapa, Chicomuselo, Amatenango) that since 2023 produced blockades, sieges of entire towns, thousands of forced displacements and, in July 2024, the flight of about 600 villagers to Cuilco, Guatemala.","impact":"Turned Chiapas from a quiet corridor into an open war zone; peace advocate Father Marcelo Pérez was murdered in San Cristóbal in October 2024 and a local franchise, the Cártel de Chiapas y Guatemala, emerged from the fighting.","state":"CHP","city":"Nueva Morelia, Chicomuselo","lat":15.7456,"lng":-92.2811,"cartels":["cjng","sinaloa","chiapas_guatemala"],"figures":["Marcelo Pérez Pérez"],"type":"massacre","importance":4,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Chicomuselo_massacre","https://mexiconewsdaily.com/news/chiapas-massacre-leaves-11-dead-as-cartel-turf-wars-intensify/","https://mexiconewsdaily.com/news/indigenous-priest-peace-leader-assassinated-chiapas/"]},{"id":"2024-election-sheinbaum-wins-violence","date":"2024-06-02","precision":"day","title":"Sheinbaum wins after Mexico's most violent election","summary":"Claudia Sheinbaum won the presidency with 59.8% of the vote (35.9 million votes), about 32 points ahead of Xóchitl Gálvez (27.9%), in the largest election in Mexican history. The 2023-24 cycle was the most violent on record, with roughly 37 candidates or aspirants murdered by press and academic counts and hundreds of attacks on politicians; the killing of Celaya mayoral candidate Gisela Gaytán on 1 April 2024 became emblematic, and hundreds of candidates required federal protection.","impact":"Gave Morena a supermajority and continuity of 'abrazos no balazos' rhetoric, while the death toll showed criminal groups' capture of municipal politics from Guanajuato to Chiapas.","state":"MULTI","city":"Mexico City","lat":19.4326,"lng":-99.1332,"cartels":["other","government"],"figures":["Claudia Sheinbaum","Xóchitl Gálvez","Gisela Gaytán"],"type":"other","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/2024_Mexican_general_election","https://mexiconewsdaily.com/mexico-elections-2024/record-breaking-votes-for-claudia-sheinbaum/","https://en.wikipedia.org/wiki/Gisela_Gayt%C3%A1n"]},{"id":"2024-el-mayo-zambada-detained-el-paso","date":"2024-07-25","precision":"day","title":"El Mayo Zambada and Joaquín Guzmán López detained near El Paso","summary":"Ismael 'El Mayo' Zambada García, co-founder and last patriarch of the Sinaloa Cartel, was taken into US custody when a small plane landed at the Doña Ana County jetport in Santa Teresa, New Mexico, outside El Paso. Joaquín Guzmán López, El Chapo's son, was on board and surrendered; Zambada later said he had been lured to a meeting in Culiacán, bound and flown against his will, a version Guzmán López confirmed in his December 2025 guilty plea.","impact":"The capture of a man never before arrested shattered the cartel's internal pact, triggering the Chapitos-Mayiza civil war and a political crisis over what Sinaloa's governor knew.","state":"US","city":"Santa Teresa, New Mexico (El Paso area)","lat":31.8776,"lng":-106.7083,"cartels":["sinaloa","mayiza","chapitos","us_government"],"figures":["Ismael 'El Mayo' Zambada García","Joaquín Guzmán López"],"type":"capture","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Ismael_Zambada_Garc%C3%ADa","https://www.justice.gov/usao-edny/pr/ismael-el-mayo-zambada-garcia-co-founder-sinaloa-cartel-arraigned-brooklyn"]},{"id":"2024-hector-cuen-killing-rocha-moya-controversy","date":"2024-07-25","precision":"day","title":"Héctor Cuén killed the day El Mayo vanished; cover-up unravels","summary":"Héctor Melesio Cuén Ojeda, former rector of the Universidad Autónoma de Sinaloa and political rival of Governor Rubén Rocha Moya, was shot dead in Culiacán on 25 July 2024. State prosecutors said he died in a gas-station robbery, but the FGR found he was killed at the Huertos del Pedregal ranch where Zambada was abducted. In an August letter Zambada said he had gone there to mediate between Cuén and Rocha; state attorney general Sara Bruna Quiñónez resigned on 16 August after the FGR exposed irregularities in her office's investigation.","impact":"Exposed the fusion of Sinaloa politics and the cartel, kept Rocha Moya under a cloud for two years and fed directly into the April 2026 US indictment of the governor.","state":"SIN","city":"Culiacán","lat":24.8091,"lng":-107.394,"cartels":["sinaloa","mayiza","chapitos","government"],"figures":["Héctor Melesio Cuén Ojeda","Rubén Rocha Moya","Ismael 'El Mayo' Zambada García","Sara Bruna Quiñónez Estrada"],"type":"killing","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/H%C3%A9ctor_Melesio_Cu%C3%A9n_Ojeda","https://www.elfinanciero.com.mx/estados/2024/08/16/asesinato-de-hector-cuen-fiscal-de-sinaloa-renuncia-tras-inconsistencias-halladas-por-la-fgr/"]},{"id":"2024-sinaloa-civil-war-begins","date":"2024-09-09","precision":"day","title":"Sinaloa Cartel civil war erupts: Chapitos vs La Mayiza","summary":"After weeks of tension over Zambada's abduction, Ismael 'El Mayito Flaco' Zambada Sicairos' faction launched coordinated attacks on the Chapitos in Culiacán on 9 September 2024; at dawn an army convoy clashed with gunmen in La Campiña, a Chapitos stronghold, and a sergeant was killed, and gunfights, blockades and body dumps spread across the city and to Elota, Navolato and the sierra. Schools and businesses closed and the state capital was effectively paralysed for weeks.","impact":"Began the longest and bloodiest internal war in the cartel's history, fracturing Mexico's most powerful trafficking organisation and drawing the CJNG into an alliance with the Chapitos.","state":"SIN","city":"Culiacán","lat":24.8091,"lng":-107.394,"cartels":["chapitos","mayiza","sinaloa","government"],"figures":["Ismael 'El Mayito Flaco' Zambada Sicairos","Iván Archivaldo Guzmán Salazar","Rubén Rocha Moya"],"type":"split","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Timeline_of_the_Infighting_in_the_Sinaloa_Cartel","https://insightcrime.org/special-series-sinaloa-cartel-internal-war/"]},{"id":"2024-sheinbaum-takes-office","date":"2024-10-01","precision":"day","title":"Sheinbaum takes office; Harfuch's security strategy","summary":"Claudia Sheinbaum was sworn in as Mexico's first woman president on 1 October 2024 and named Omar García Harfuch security secretary. Within days the government presented a four-pillar strategy (attention to causes, National Guard consolidation, intelligence and investigation, coordination) and returned to targeting cartel leaders and laboratories, a break with López Obrador's non-confrontation.","impact":"Set the intelligence-led, capture-heavy approach that produced the 2025-26 mass transfers to the US, the El Mencho operation and falling homicide numbers, while managing unprecedented pressure from Washington.","state":"CMX","city":"Mexico City","lat":19.4326,"lng":-99.1332,"cartels":["government"],"figures":["Claudia Sheinbaum","Omar García Harfuch"],"type":"policy","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Claudia_Sheinbaum","https://en.wikipedia.org/wiki/Omar_Garc%C3%ADa_Harfuch"]},{"id":"2024-garcia-luna-sentenced","date":"2024-10-16","precision":"day","title":"García Luna sentenced to 38 years","summary":"Judge Brian Cogan sentenced Genaro García Luna to 38 years and 4 months in prison and a US$2 million fine in Brooklyn federal court. He was later sent to the ADX Florence supermax, and on 22 May 2025 a Florida civil court ordered him and his wife Linda Cristina Pereyra to pay the Mexican government about US$2.49 billion for diverting public funds.","impact":"Cemented the legal record that Mexico's top cop of the Calderón war years worked for the Sinaloa Cartel, a precedent invoked when US prosecutors charged a sitting governor in 2026.","state":"US","city":"Brooklyn, New York","lat":40.6928,"lng":-73.9903,"cartels":["sinaloa","government","us_government"],"figures":["Genaro García Luna","Brian Cogan"],"type":"trial","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Genaro_Garc%C3%ADa_Luna","https://www.aljazeera.com/news/2025/5/23/florida-court-orders-ex-mexican-security-chief-to-pay-millions-to-mexico"]},{"id":"2024-ahome-record-fentanyl-seizure","date":"2024-12-03","precision":"day","title":"Record fentanyl seizure in Ahome: over a ton of pills","summary":"In operations in Ahome (Los Mochis area) and Guasave on 3 December 2024, the army, navy and federal security forces seized more than 1,100 kg of fentanyl, over 20 million doses valued at roughly US$400 million, the largest fentanyl seizure in Mexican history, and arrested two cell leaders. US Treasury later tied the stash to the Beltrán Leyva remnant network of Fausto Isidro Meza Flores, 'El Chapo Isidro', which is aligned with the Mayiza in the Sinaloa war.","impact":"Announced by Sheinbaum as proof of a new posture just as Donald Trump threatened tariffs over fentanyl, it became the centrepiece of Mexico's case that it was acting against the trade.","state":"SIN","city":"Ahome (Los Mochis)","lat":25.7933,"lng":-108.9964,"cartels":["beltran_leyva","sinaloa","mayiza","government"],"figures":["Omar García Harfuch","Claudia Sheinbaum","Fausto Isidro Meza Flores 'El Chapo Isidro'"],"type":"discovery","importance":3,"confidence":"high","sources":["https://mexiconewsdaily.com/news/federal-authorities-largest-fentanyl-bust-mexican-history/","https://home.treasury.gov/news/press-releases/sb0076"]},{"id":"2025-trump-executive-order-cartels-fto","date":"2025-01-20","precision":"day","title":"Trump orders cartel terrorist designations (EO 14157)","summary":"Hours after his inauguration Donald Trump signed Executive Order 14157, declaring international cartels an 'unusual and extraordinary threat', declaring a national emergency and giving the State Department 14 days to recommend Foreign Terrorist Organization and SDGT designations for cartels, Tren de Aragua and MS-13. He also ordered troops to the border and floated the Alien Enemies Act.","impact":"Launched the most aggressive US posture toward Mexican organised crime since the Camarena era, with tariffs, terrorist designations and talk of military force reshaping Mexico's security policy.","state":"US","city":"Washington, D.C.","lat":38.9072,"lng":-77.0369,"cartels":["us_government"],"figures":["Donald Trump","Marco Rubio"],"type":"policy","importance":4,"confidence":"high","sources":["https://www.whitehouse.gov/presidential-actions/2025/01/designating-cartels-and-other-organizations-as-foreign-terrorist-organizations-and-specially-designated-global-terrorists/","https://en.wikipedia.org/wiki/Executive_Order_14157"]},{"id":"2025-fto-designation-six-mexican-cartels","date":"2025-02-20","precision":"day","title":"US designates six Mexican cartels as terrorist organizations","summary":"The State Department designated the Sinaloa Cartel, the Cártel Jalisco Nueva Generación, the Cártel del Noreste, the Gulf Cartel, La Nueva Familia Michoacana and Cárteles Unidos, along with Tren de Aragua and MS-13, as Foreign Terrorist Organizations and Specially Designated Global Terrorists, effective 20 February 2025.","impact":"Exposed anyone providing 'material support' to US terrorism prosecutions, enabled sanctions on banks and officials, and underpinned later mass transfers, the CIBanco-Intercam-Vector actions and the July 2026 additions of the Juárez Cartel and Los Viagras.","state":"US","city":"Washington, D.C.","lat":38.9072,"lng":-77.0369,"cartels":["sinaloa","cjng","cdn","gulf","nueva_familia_michoacana","carteles_unidos","us_government"],"figures":["Marco Rubio","Donald Trump"],"type":"policy","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/United_States_Department_of_State_list_of_Foreign_Terrorist_Organizations","https://www.state.gov/designation-of-international-cartels/"]},{"id":"2025-mass-transfer-29-capos-caro-quintero","date":"2025-02-27","precision":"day","title":"Mexico flies 29 capos, incl. Caro Quintero and Z-40, to the US","summary":"Invoking national security rather than the extradition treaty, Mexico flew 29 imprisoned cartel figures to eight US cities in one night: Rafael Caro Quintero (Camarena's killer), Zetas founders Miguel Ángel 'Z-40' and Omar 'Z-42' Treviño Morales, Juárez boss Vicente Carrillo Fuentes and CJNG figure Antonio 'Tony Montana' Oseguera among them. Caro Quintero and Carrillo Fuentes were arraigned in Brooklyn the next day.","impact":"The largest handover in the history of the bilateral relationship, made to blunt Trump's tariff threat and terrorist designations; it bypassed Mexican courts and ended decades-long extradition fights.","state":"MULTI","city":"Mexico City","lat":19.4326,"lng":-99.1332,"cartels":["guadalajara","caborca","zetas","cdn","juarez","cjng","sinaloa","government","us_government"],"figures":["Rafael Caro Quintero","Miguel Ángel Treviño Morales 'Z-40'","Omar Treviño Morales 'Z-42'","Vicente Carrillo Fuentes","Claudia Sheinbaum"],"type":"extradition","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Rafael_Caro_Quintero","https://en.wikipedia.org/wiki/Miguel_Trevi%C3%B1o_Morales"]},{"id":"2025-rancho-izaguirre-teuchitlan","date":"2025-03-05","precision":"day","title":"Rancho Izaguirre: CJNG training and extermination site exposed","summary":"The search collective Guerreros Buscadores de Jalisco entered Rancho Izaguirre in La Estanzuela, Teuchitlán, on 5 March 2025 and found some 200 pairs of shoes, piles of clothing, makeshift ovens and charred bone fragments. The National Guard and Jalisco prosecutors had raided the ranch in September 2024 (18 September per the state prosecutor), arresting ten and freeing two captives, without reporting the site. The FGR took over the case on 20 March; recruiter José Gregorio Lastra Hermida, 'El Lastra', was arrested in Cuajimalpa, Mexico City, on 22 March, and Teuchitlán mayor José Murguía Santiago on 3 May 2025.","impact":"Mexico's 'Auschwitz' moment: it forced national recognition of CJNG forced recruitment through fake job offers, of more than 120,000 disappeared, and of state complicity, and pushed Sheinbaum to announce disappearance reforms.","state":"JAL","city":"Teuchitlán","lat":20.6833,"lng":-103.85,"cartels":["cjng","government"],"figures":["José Gregorio Lastra Hermida","José Murguía Santiago","Claudia Sheinbaum","Alejandro Gertz Manero"],"type":"discovery","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Rancho_Izaguirre","https://www.jornada.com.mx/2025/03/23/politica/007n1pol","https://mexiconewsdaily.com/el-bajio/authorities-arrest-teuchitlan-mayor/"]},{"id":"2025-ovidio-relatives-cross-into-us","date":"2025-05-09","precision":"day","title":"Seventeen of Ovidio Guzmán's relatives cross into the US","summary":"Seventeen relatives of Ovidio Guzmán, led by his mother Griselda López Pérez, El Chapo's former wife, walked across the San Ysidro port of entry from Tijuana on 9 May 2025 carrying suitcases and more than US$70,000 and were received by FBI agents. Security secretary García Harfuch confirmed on 13 May that the crossing was part of Ovidio's negotiation with US prosecutors and that none of them was wanted in Mexico; Sheinbaum criticised Washington for not sharing information on the case.","impact":"Public confirmation that the Chapitos were cutting deals with the US, deepening the sense inside Sinaloa that the faction had traded El Mayo and would trade the cartel for leniency.","state":"US","city":"San Ysidro, California","lat":32.5522,"lng":-117.043,"cartels":["chapitos","us_government","government"],"figures":["Griselda López Pérez","Ovidio Guzmán López","Omar García Harfuch"],"type":"other","importance":3,"confidence":"high","sources":["https://mexiconewsdaily.com/news/el-chapo-family-members-turn-themselves-in-us-mexico/","https://en.wikipedia.org/wiki/Ovidio_Guzm%C3%A1n_L%C3%B3pez"]},{"id":"2025-irapuato-festival-massacre","date":"2025-06-24","precision":"day","title":"Gunmen kill 12 at street festival in Irapuato","summary":"On the night of 24 June 2025 gunmen opened fire on a crowd celebrating the feast of San Juan in a residential street of Irapuato, Guanajuato, killing 12 people and wounding about 20. No group was formally charged; the attack occurred in the heartland of the CJNG-Santa Rosa de Lima war that has made Guanajuato Mexico's most murderous state.","impact":"One of the deadliest massacres of Sheinbaum's first year, it underscored that Guanajuato's fuel-theft-driven conflict continued unabated despite falling national homicide figures.","state":"GUA","city":"Irapuato","lat":20.6767,"lng":-101.3542,"cartels":["other","cjng","santa_rosa_lima"],"figures":["Libia Dennise García Muñoz Ledo"],"type":"massacre","importance":3,"confidence":"high","sources":["https://en.wikipedia.org/wiki/2025_Irapuato_shooting"]},{"id":"2025-ovidio-guzman-pleads-guilty","date":"2025-07-11","precision":"day","title":"Ovidio Guzmán pleads guilty in Chicago","summary":"Ovidio Guzmán López pleaded guilty before Judge Sharon Johnson Coleman in the Northern District of Illinois to two drug-distribution counts and two continuing-criminal-enterprise counts, admitting to running fentanyl, methamphetamine and cocaine operations for the Chapitos; prosecutors had dropped the death penalty in exchange for his cooperation.","impact":"The first of El Chapo's sons to become a US cooperator, raising fears in Sinaloa and Mexican politics about whom he would name and feeding the April 2026 indictment of Sinaloa officials.","state":"US","city":"Chicago, Illinois","lat":41.8781,"lng":-87.6298,"cartels":["chapitos","sinaloa","us_government"],"figures":["Ovidio Guzmán López","Sharon Johnson Coleman"],"type":"trial","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Ovidio_Guzm%C3%A1n_L%C3%B3pez","https://insightcrime.org/mexico-organized-crime-news/los-chapitos/"]},{"id":"2025-second-mass-transfer-26-la-tuta","date":"2025-08-12","precision":"day","title":"Second mass transfer: 26 capos incl. La Tuta sent to the US","summary":"Mexico sent 26 more imprisoned cartel figures to the United States on Tuesday 12 August 2025 after the Justice Department agreed not to seek the death penalty against them or the February transferees. They included Abigael González Valencia, leader of Los Cuinis and El Mencho's brother-in-law, former Knights Templar chief Servando Gómez 'La Tuta', and Roberto Salazar, wanted for the 2008 killing of a Los Angeles County sheriff's deputy.","impact":"Confirmed the mass 'national security transfer' as a standing tool of Sheinbaum's relationship with Trump, emptying Mexican prisons of historic bosses and their extradition appeals.","state":"MULTI","city":"Mexico City","lat":19.4326,"lng":-99.1332,"cartels":["cjng","templarios","sinaloa","government","us_government"],"figures":["Abigael González Valencia","Servando Gómez Martínez 'La Tuta'","Roberto Salazar"],"type":"extradition","importance":4,"confidence":"high","sources":["https://www.cbsnews.com/news/mexico-sends-26-cartel-members-deal-trump-administration/","https://www.cnn.com/2025/08/12/americas/mexico-26-cartels-trump-intl-latam"]},{"id":"2025-el-mayo-zambada-pleads-guilty","date":"2025-08-25","precision":"day","title":"El Mayo Zambada pleads guilty in Brooklyn","summary":"Ismael Zambada García pleaded guilty before Judge Brian Cogan in the Eastern District of New York to racketeering conspiracy and running a continuing criminal enterprise, admitting to decades of trafficking and to bribing Mexican police, military and politicians; he agreed to forfeit US$15 billion after prosecutors took the death penalty off the table.","impact":"Ended any prospect of a trial exposing his protectors and closed the career of the cartel's founding generation, while his statement that officials had been on his payroll rattled Mexican politics.","state":"US","city":"Brooklyn, New York","lat":40.6928,"lng":-73.9903,"cartels":["sinaloa","mayiza","us_government"],"figures":["Ismael 'El Mayo' Zambada García","Brian Cogan"],"type":"trial","importance":5,"confidence":"high","sources":["https://www.justice.gov/usao-edny/pr/co-founder-if-sinaloa-cartel-ismael-el-mayo-zambada-garcia-pleads-guilty-brooklyn","https://mexiconewsdaily.com/news/sinaloa-cartel-el-mayo-zambada-confess-us-court/"]},{"id":"2025-hernan-bermudez-requena-arrested","date":"2025-09-12","precision":"day","title":"Tabasco ex-security chief Bermúdez, La Barredora boss, arrested","summary":"Hernán Bermúdez Requena, Tabasco's secretary of public security from December 2019 to January 2024 under governors Adán Augusto López and Carlos Merino, was arrested on 12 September 2025 in a luxury home in the Surubi'i gated community of Mariano Roque Alonso, outside Asunción, Paraguay, after fleeing Mexico in late January 2025. Prosecutors identify him as 'El Abuelo' or 'Comandante H', leader of La Barredora, the CJNG-linked group running fuel theft, extortion and drugs in Tabasco. Paraguay expelled him on 17 September and he was jailed at the Altiplano that night.","impact":"The starkest case of a state security chief doubling as a cartel boss, it engulfed Morena's Senate leader Adán Augusto López and showed CJNG's expansion into the Gulf coast oil states.","state":"TAB","city":"Villahermosa (arrested in Mariano Roque Alonso, Paraguay)","lat":17.9895,"lng":-92.9475,"cartels":["barredora","cjng","government"],"figures":["Hernán Bermúdez Requena","Adán Augusto López Hernández","Omar García Harfuch"],"type":"corruption","importance":4,"confidence":"high","sources":["https://mexiconewsdaily.com/news/former-tabasco-security-minister-arrested-paraguay-organized-crime-charges/","https://en.wikipedia.org/wiki/Hern%C3%A1n_Berm%C3%BAdez_Requena","https://www.proceso.com.mx/nacional/justicia/2025/9/17/paraguay-expulsa-hernan-bermudez-requena-autoridades-de-mexico-van-por-el-video-359022.html"]},{"id":"2025-carlos-manzo-assassinated-uruapan","date":"2025-11-01","precision":"day","title":"Uruapan mayor Carlos Manzo assassinated; Plan Michoacán follows","summary":"Carlos Manzo, the independent 'sombrero' mayor of Uruapan who had demanded a real war on organised crime, was shot dead at about 8:10 p.m. during the Festival de las Velas in the Plaza Mártires de Uruapan on 1 November 2025; the 17-year-old gunman was killed on the spot. His widow Grecia Quiroz was sworn in as mayor on 5 November. Sheinbaum announced Plan Michoacán on 4 November and presented its 12 axes and 57 billion pesos on 9 November. Investigators tied the hit to Los Rs, a CJNG-linked cell whose leader Ramón Ángel Álvarez Ayala, 'R1', was captured in Atotonilco, Jalisco, on 30 July 2026; lime growers' leader Bernardo Bravo had been murdered near Apatzingán on 20 October.","impact":"The most politically explosive killing of Sheinbaum's term: it sparked nationwide protests, a federal surge into Michoacán and a rethink of avocado and lime extortion, and made Manzo a symbol of resistance to CJNG.","state":"MIC","city":"Uruapan","lat":19.4208,"lng":-102.0628,"cartels":["cjng","carteles_unidos","government"],"figures":["Carlos Manzo","Grecia Quiroz","Ramón Ángel Álvarez Ayala 'R1'","Bernardo Bravo Manríquez","Claudia Sheinbaum"],"type":"killing","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/Carlos_Manzo","https://mexiconewsdaily.com/news/plan-michoacan-sheinbaum-12-point-strategy-pacify-state/","https://mexiconewsdaily.com/news/uruapan-mayor-manzo-murder-mastermind-arrested-cjng-jalisco/"]},{"id":"2025-gen-z-march-zocalo","date":"2025-11-15","precision":"day","title":"'Gen Z' march on the Zócalo turns violent","summary":"Roughly 17,000 people marched from the Ángel de la Independencia along Reforma to the Zócalo on 15 November 2025 under the 'Generación Z' banner, with parallel protests in dozens of cities, demanding justice for Carlos Manzo and an end to impunity and cartel rule. After hours of peaceful protest a black bloc of about 1,000 masked people tore down barriers at the National Palace; police used tear gas, about 100 officers were injured (40 hospitalised) and around 20 people were detained in Mexico City, with 44 more arrested in Guadalajara.","impact":"The first large anti-Sheinbaum street mobilisation, contested as opposition-driven by the government, it turned cartel violence into the central political issue of her presidency.","state":"CMX","city":"Mexico City","lat":19.4326,"lng":-99.1332,"cartels":["government"],"figures":["Claudia Sheinbaum","Carlos Manzo"],"type":"other","importance":4,"confidence":"high","sources":["https://en.wikipedia.org/wiki/2025_Mexican_protests","https://www.aljazeera.com/news/2025/11/15/protest-in-mexico-inspired-by-gen-z-movement-draws-older-govt-critics"]},{"id":"2026-trump-land-strikes-vow-jiatf-counter-cartel","date":"2026-01-09","precision":"day","title":"Trump vows to 'hit land'; JIATF-Counter Cartel stands up","summary":"After months of US strikes on alleged drug boats in the Caribbean and Pacific and the January 2026 US operation that seized Nicolás Maduro, Donald Trump said on 9 January 2026 that the US would 'start now hitting land, with regard to' the cartels; Sheinbaum answered that it would not happen and, after a call with Trump on 12 January, ruled out any US military action in Mexico. On 15 January the Pentagon formally established the Joint Interagency Task Force-Counter Cartel under Brig. Gen. Maurizio Calabrese to map and disrupt cartel networks. As of September 2026 no unilateral US strike on Mexican soil has been confirmed: the task force supplied intelligence for the Tapalpa raid, both governments rejected a May 2026 CNN report that the CIA had facilitated a lethal car bombing in the State of Mexico, and the US ran anti-drone operations on the border.","impact":"Set the terms of the 2026 relationship: intense US intelligence involvement inside Mexico and a standing threat of force that Sheinbaum met with kingpin captures and transfers to preserve sovereignty.","state":"US","city":"Washington, D.C.","lat":38.9072,"lng":-77.0369,"cartels":["us_government","government","cjng","sinaloa"],"figures":["Donald Trump","Claudia Sheinbaum","Maurizio Calabrese"],"type":"policy","importance":4,"confidence":"medium","sources":["https://www.cnbc.com/2026/01/09/trump-us-military-cartels-mexico-land.html","https://en.wikipedia.org/wiki/Joint_Interagency_Task_Force-Counter_Cartel","https://lieber.westpoint.edu/when-cartels-fight-back-el-mencho-niac-question-mexico/"]},{"id":"2026-el-mencho-killed-tapalpa","date":"2026-02-22","precision":"day","title":"El Mencho killed in Tapalpa; CJNG unleashes nationwide terror","summary":"Army special forces raided a compound in the Tapalpa Country Club, an upscale gated development in Tapalpa, Jalisco, on the morning of Sunday 22 February 2026, aided by intelligence from the US task force. Nemesio Oseguera Cervantes fled into the woods with bodyguards, was critically wounded in the firefight and died aboard the helicopter to Mexico City; eight CJNG members and three soldiers died in the operation. Within hours the cartel mounted some 250 blockades across roughly 20 states, burned buses and stores, attacked National Guard posts and stormed the Puerto Vallarta prison at Ixtapa, from which 23 inmates escaped; at least 25 National Guard troops and dozens of gunmen were killed, Guadalajara transit and Puerto Vallarta flights stopped, and schools closed across the west. His body was buried in Zapopan on 3 March; stepson Juan Carlos Valencia González, 'El 03', emerged as successor.","impact":"The fall of Mexico's most wanted man and the largest cartel retaliation ever recorded; it decapitated CJNG without breaking it, vindicated Sheinbaum's kingpin turn and preceded World Cup security fears.","state":"JAL","city":"Tapalpa","lat":19.9453,"lng":-103.7586,"cartels":["cjng","government","us_government"],"figures":["Nemesio 'El Mencho' Oseguera Cervantes","Claudia Sheinbaum","Omar García Harfuch","Juan Carlos Valencia González 'El 03'"],"type":"killing","importance":5,"confidence":"high","sources":["https://en.wikipedia.org/wiki/2026_Jalisco_operation","https://www.nbcnews.com/world/mexico/jalisco-new-generation-cartel-leader-killed-rcna260184","https://acleddata.com/expert-comment/mexico-el-menchos-killing-triggers-nationwide-escalation"]},{"id":"2026-el-jardinero-captured-nayarit","date":"2026-04-27","precision":"day","title":"CJNG commander 'El Jardinero' captured in Nayarit ditch","summary":"Navy special forces, more than 500 troops with six helicopters and several planes, captured Audias Flores Silva, 'El Jardinero', hiding in a ditch near a cabin at El Mirador, about 20 km north of Puerto Vallarta in Bahía de Banderas, Nayarit, on Monday 27 April 2026 without firing a shot after a perimeter of some 30 pickup trucks guarding him scattered. The CJNG Pacific-coast commander carried a US$5 million US reward and was seen as a contender to succeed El Mencho.","impact":"Removed the main rival to 'El 03' in the CJNG succession and showed the post-Mencho campaign against the cartel's regional commanders would continue.","state":"NAY","city":"El Mirador, Bahía de Banderas","lat":20.8072,"lng":-105.2469,"cartels":["cjng","government"],"figures":["Audias Flores Silva 'El Jardinero'"],"type":"capture","importance":4,"confidence":"high","sources":["https://www.aljazeera.com/news/2026/4/28/mexicos-jalisco-drug-cartel-commander-el-jardinero-found-hiding-in-ditch","https://en.wikipedia.org/wiki/Audias_Flores_Silva"]},{"id":"2026-rocha-moya-indicted-sdny","date":"2026-04-29","precision":"day","title":"US indicts Sinaloa Governor Rocha Moya for cartel collusion","summary":"Prosecutors in the Southern District of New York unsealed an indictment on 29 April 2026 charging Sinaloa Governor Rubén Rocha Moya and nine other officials, including Senator Enrique Inzunza Cázarez and Culiacán mayor Juan de Dios Gámez Mendívil, with conspiring with the Sinaloa Cartel, alleging he took bribes and electoral help from the Chapitos in exchange for protection. Sheinbaum demanded conclusive evidence; Rocha took leave on 1 May, the Financial Intelligence Unit froze his accounts on 6 May, he returned on 21 August and requested indefinite leave again within two days after a backlash inside Morena.","impact":"The first US indictment of a sitting Mexican governor; it forced Morena to abandon Rocha, revived the Cuén-Zambada questions and became the sharpest sovereignty dispute of the Sheinbaum-Trump era.","state":"US","city":"New York","lat":40.7128,"lng":-74.006,"cartels":["chapitos","sinaloa","government","us_government"],"figures":["Rubén Rocha Moya","Enrique Inzunza Cázarez","Juan de Dios Gámez Mendívil","Claudia Sheinbaum"],"type":"corruption","importance":5,"confidence":"high","sources":["https://mexiconewsdaily.com/politics/us-indictment-sinaloa-governor-rocha-proof-sheinbaum-april-30-mananera/","https://mexiconewsdaily.com/politics/sinaloa-governor-rocha-moya-returned-office/","https://en.wikipedia.org/wiki/Rub%C3%A9n_Rocha_Moya"]},{"id":"2026-world-cup-security-operation","date":"2026-06-11","precision":"day","title":"World Cup opens under massive security shield","summary":"The 2026 FIFA World Cup opened at the Estadio Azteca on 11 June 2026 with Mexico's first match, and Mexico hosted 13 matches in Mexico City, Guadalajara and Monterrey through early July. The government deployed a large federal security operation, reported at close to 100,000 soldiers, National Guard and police with anti-drone systems, four months after El Mencho's killing raised fears of CJNG attacks. The host cities recorded no major incidents and Sheinbaum called the tournament a success, but cartel violence continued elsewhere, including reported drone attacks in rural Michoacán.","impact":"A reputational test passed for Sheinbaum and Harfuch, though analysts argued the concentration of forces in three metros left rural Michoacán, Guanajuato and Sinaloa more exposed.","state":"CMX","city":"Mexico City (Estadio Azteca)","lat":19.3029,"lng":-99.1505,"cartels":["government","cjng"],"figures":["Claudia Sheinbaum","Omar García Harfuch"],"type":"policy","importance":3,"confidence":"low","sources":["https://www.cnn.com/2026/07/09/americas/mexico-world-cup-security-cartel-attack-intl-latam","https://mexiconewsdaily.com/politics/risk-world-cup-sheinbaum-tuesdays-mananera-recapped/","https://mexiconewsdaily.com/news/tariffs-security-mexico-week-in-review-july-20/"]},{"id":"2026-el-mayo-sentenced-life","date":"2026-07-20","precision":"day","title":"El Mayo sentenced to life, ordered to forfeit $15 billion","summary":"Judge Brian Cogan sentenced Ismael 'El Mayo' Zambada García, 76, to life in prison in Brooklyn federal court on 20 July 2026 and ordered US$15 billion in forfeiture; Zambada told the court that violence 'must end' in Mexico and elsewhere and urged young people not to follow his path. His kidnapper, Joaquín Guzmán López, had pleaded guilty in Chicago on 1 December 2025, admitting he lured and seized Zambada in the hope of earning cooperation credit for himself and Ovidio.","impact":"Closed the judicial chapter of the Sinaloa Cartel's founding generation two years after the abduction that started the Chapitos-Mayiza war.","state":"US","city":"Brooklyn, New York","lat":40.6928,"lng":-73.9903,"cartels":["sinaloa","mayiza","chapitos","us_government"],"figures":["Ismael 'El Mayo' Zambada García","Brian Cogan","Joaquín Guzmán López"],"type":"trial","importance":4,"confidence":"high","sources":["https://www.justice.gov/opa/pr/co-founder-sinaloa-cartel-ismael-el-mayo-zambada-garcia-sentenced-life-prison-and-ordered","https://www.aljazeera.com/news/2026/7/20/mexican-drug-lord-ismael-el-mayo-zambada-sentenced-to-life-in-us-prison","https://mexiconewsdaily.com/news/son-el-chapo-joaquin-guzman-lopez-admits-kidnapping-el-mayo/"]},{"id":"2026-poncho-la-quiringua-captured-los-reyes","date":"2026-08-01","precision":"day","title":"'Poncho La Quiringua' of Cártel de Los Reyes captured","summary":"The army, with federal and state forces, detained Alfonso Fernández Magallón, 'Poncho La Quiringua', leader of the Cártel de Los Reyes, a Cárteles Unidos cell fighting CJNG in Michoacán's avocado belt, in Los Reyes on 1 August 2026; the US had offered up to US$5 million for him. Gunmen responded with blockades and burning vehicles in Los Reyes and Peribán. His successor, Luis Enrique Barragán Chávez, 'R5' or 'El Güicho', was killed by the army in a shootout in Tocumbo on 1 September 2026.","impact":"Part of the post-Manzo federal campaign in Michoacán that struck both sides of the CJNG-Cárteles Unidos war, aimed at the extortion networks strangling the avocado and lime trades.","state":"MIC","city":"Los Reyes","lat":19.5911,"lng":-102.4733,"cartels":["carteles_unidos","cjng","government","us_government"],"figures":["Alfonso Fernández Magallón 'Poncho La Quiringua'","Luis Enrique Barragán Chávez 'R5'"],"type":"capture","importance":3,"confidence":"high","sources":["https://www.riotimesonline.com/mexico-army-captures-cartel-de-los-reyes-leader-michoacan-2026/","https://mexiconewsdaily.com/news/mexico-military-kills-r5/"]},{"id":"2026-us-25m-reward-el-03-cjng-leaders","date":"2026-08-05","precision":"day","title":"US posts $25M bounty on El Mencho's successor 'El 03'","summary":"On 5 August 2026 the State Department raised its reward for Juan Carlos Valencia González, 'El 03', El Mencho's California-born stepson and the CJNG's new leader, from the US$5 million posted in 2021 to US$25 million, as the DEA announced new charges and rewards against a group of senior CJNG leaders. Weeks earlier, on 16 July, the US had formally added the Juárez Cartel/La Línea and Los Viagras to the terrorist list, bringing designated Mexican groups to eight.","impact":"Placed the CJNG heir alongside history's most-wanted fugitives and signalled that Washington would pursue the cartel's second generation as terrorists, not merely traffickers.","state":"US","city":"Washington, D.C.","lat":38.9072,"lng":-77.0369,"cartels":["cjng","juarez","carteles_unidos","us_government"],"figures":["Juan Carlos Valencia González 'El 03'","Marco Rubio"],"type":"policy","importance":4,"confidence":"medium","sources":["https://www.dea.gov/press-releases/2026/08/05/new-charges-and-rewards-announced-for-capture-andor-conviction-senior","https://www.upi.com/Top_News/World-News/2026/08/06/latam-us-reward-new-mexican-cartel-leader/8341786029473/","https://mexiconewsdaily.com/news/us-names-2-more-mexican-cartels-foreign-terrorist-organizations/"]},{"id":"2026-ojocaliente-zacatecas-car-bomb","date":"2026-08-30","precision":"day","title":"Car bomb wounds 11 at Ojocaliente police station, Zacatecas","summary":"A stolen vehicle from Jalisco packed with explosives detonated outside the municipal police headquarters in Ojocaliente, Zacatecas, at about 8 p.m. on Sunday 30 August 2026, during the town's patron-saint festivities, injuring ten civilians and a policewoman and damaging some 30 buildings and 13 vehicles. It was the third explosive attack in the state in four days; Zacatecas prosecutor Cristian Camacho said everything pointed to the CJNG, possibly in reprisal for the arrest of an 18-year-old alleged CJNG gunman the day before, and the federal security cabinet reinforced its deployment.","impact":"Emblematic of the 2026 shift toward car bombs, drones and IEDs by cartels under military pressure, extending the CJNG-Sinaloa war for Zacatecas that has displaced whole villages since 2021.","state":"ZAC","city":"Ojocaliente","lat":22.5667,"lng":-102.25,"cartels":["cjng","government"],"figures":["Cristian Camacho"],"type":"attack","importance":3,"confidence":"medium","sources":["https://mexiconewsdaily.com/news/car-bomb-zacatecas/"]},{"id":"2026-sinaloa-war-two-year-toll","date":"2026-09-01","precision":"month","title":"Two years of Sinaloa war: thousands dead or missing","summary":"As the Chapitos-Mayiza war approached its second anniversary, the conflict had left well over 4,000 people dead or missing by press and Wikipedia tallies, with 1,657 people killed in Sinaloa in 2025 alone, some 5,800 disappearances counted by the Sabuesos Guerreras collective since July 2024 and dozens of police officers killed. The Chapitos, allied with CJNG since late 2024 and weakened by the loss of security chiefs such as El Nini (captured November 2023) and El Perris (killed 23 May 2025), lost ground to Mayito Flaco's Mayiza; monthly killings eased in 2026 and Culiacán prepared its first Independence Day festivities since 2024.","impact":"Mexico's most powerful cartel emerged fractured into rival franchises, its territory in Baja California, Sonora, Chiapas and Zacatecas contested by CJNG, while Sinaloa's economy and civic life absorbed the deepest damage since the 1990s.","state":"SIN","city":"Culiacán","lat":24.8091,"lng":-107.394,"cartels":["chapitos","mayiza","sinaloa","cjng","government"],"figures":["Ismael 'El Mayito Flaco' Zambada Sicairos","Iván Archivaldo Guzmán Salazar","Jesús Alfredo Guzmán Salazar"],"type":"battle","importance":4,"confidence":"medium","sources":["https://en.wikipedia.org/wiki/Infighting_in_the_Sinaloa_Cartel","https://www.aljazeera.com/features/longform/2026/4/23/decapitating-cartels-mexico-leans-into-kingpin-strategy-but-at-a-cost","https://www.latintimes.com/year-bloodshed-sinaloa-nearly-2000-dead-war-between-los-chapitos-la-mayiza-589356"]}];
